export const ExperimentSetupOutcome = Schema.Struct({ "metric_type": Schema.String.annotate({ "description": "metric_type of the metric this outcome describes: 'funnel', 'mean', 'ratio', 'retention' or 'quantile'." }), "metric_samples": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Units the result counted across all variants. What a unit is depends on metric_type, so read analyzed_exposures where you need exposures. Null when the result stores no sample counts." }), "analyzed_exposures": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "metric_samples, but only where the metric type makes it the analyzed population: 'funnel' and 'mean'. Users seen in several variants are left out under the default handling, so it can be lower than exposures. Null for 'retention', whose samples are the units that did the start event, and for 'ratio', whose samples are not exposures either. Also null when the result stores no sample counts, which is not the same as analyzing nobody." }), "control_baseline_value": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "What control measured: a conversion rate for 'funnel', an average per unit for 'mean'. Compare it with the rate on the surface itself to see whether the exposure was diluted by users who never reached the surface. Null for other metric types and when control analyzed no units.", "format": "double" }), "any_variant_significant": Schema.Boolean.annotate({ "description": "Whether any variant was significant on that metric in that result." }), "result_completed_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When that result was computed.", "format": "date-time" }), "result_data_through": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The last moment the result covers. A backfill writes an older day with a recent completed_at, so this says how current the numbers are.", "format": "date-time" }) }).annotate({ "identifier": "ExperimentSetupOutcome" })
