export const FeatureFlagSetReleaseConditionRolloutRequest = Schema.Struct({ "condition_index": Schema.Number.annotate({ "description": "Zero-based position of the release condition in `filters.groups`, counted from the read that produced `version`." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })), "rollout_percentage": Schema.Number.annotate({ "description": "Percentage of the users matching that condition who are served the flag, 0 through 100. On a multivariate flag this is how many matching users get a variant at all, not how the variants are split between them. Fractional percentages such as 0.5 are accepted, the same as a write that sends `filters`.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })).check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })).check(Schema.isLessThanOrEqualTo(100).annotate({ "expected": "a value less than or equal to 100" })), "version": Schema.Union([Schema.Int.check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })), Schema.Null]).annotate({ "description": "The `version` from your most recent read of this flag. The change is refused with 409 if anyone else changed the flag after that version. A flag written before versioning reads as `null`; send that back unchanged and it is read as 0, so the value a read returns is always one this accepts." }) }).annotate({ "identifier": "FeatureFlagSetReleaseConditionRolloutRequest" })
export type FeatureFlagRolloutSummary = { readonly "effectively_full_rollout": boolean, readonly "has_targeting_conditions": boolean, readonly "max_rollout_percentage": number | null, readonly "is_multivariate": boolean }
export const FeatureFlagRolloutSummary = Schema.Struct({ "effectively_full_rollout": Schema.Boolean.annotate({ "description": "True if the flag is effectively rolled out to everyone, independent of recent evaluation. For boolean flags this means at least one release condition targets 100% with no property filters, or there are no release conditions. For multivariate flags it means every release condition a user can reach, up to the first one at 100% with no property filters, serves the same variant. In a flag of either type that mixes person and group aggregation, only a person-level condition counts as that 100% condition. This is the signal for 'fully rolled out' / GA, unlike `status`, which only reflects recent evaluation." }), "has_targeting_conditions": Schema.Boolean.annotate({ "description": "True if any release condition has property filters, i.e. the flag is conditionally targeted rather than a blanket rollout. This says nothing about which condition produced `max_rollout_percentage`: the two fields are computed independently over the whole condition list." }), "max_rollout_percentage": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Highest rollout percentage (0-100) across the flag's release conditions, treating a missing percentage as 100. Null when the flag has no release conditions. The maximum can come from an untargeted condition even when `has_targeting_conditions` is true, so it cannot be attributed to a targeted condition or read as a share of a targeted segment.", "format": "double" }), "is_multivariate": Schema.Boolean.annotate({ "description": "True if the flag serves multiple variants (has a multivariate variant set)." }) }).annotate({ "identifier": "FeatureFlagRolloutSummary" })
