export const WorkflowProposalCreate = Schema.Struct({ "title": Schema.String.annotate({ "description": "Short summary of the proposed change." }).check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" })), "rationale": Schema.String.annotate({ "description": "Why this change is worth making, in prose a human reads." }), "content": Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })).annotate({ "description": "Only the workflow content fields this proposal changes. Approving merges them over the live content to build the staged draft, so unrelated parts of the workflow stay as they are. In `actions`, send each step you change with its `id` and only the fields you change; they merge into the live step, and a null field deletes it." }), "evidence": Schema.optionalKey(Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })).annotate({ "description": "The metric numbers behind the proposal, so a human can judge it without re-deriving them." })), "base_version": Schema.Number.annotate({ "description": "Workflow version this was authored against, as read from the workflow. It is the snapshot approve compares against to tell whether someone edited the same steps or fields since, and a defaulted version would read as current however long the producer took." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })), "step_id": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" })), Schema.Null]).annotate({ "description": "The step this is about. Send it for a change to one step: both the evidence and the outcome then read that step's metrics, so a change to one email in a sequence is not measured against the rest. Leave it out only for a change that spans the workflow, such as its exit condition or a step being taken out, which is measured on the workflow's own numbers." })), "source_id": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" })), Schema.Null]).annotate({ "description": "Stable id of the producing agent run or finding. Posting the same one twice returns the existing proposal instead of creating a duplicate." })) }).annotate({ "identifier": "WorkflowProposalCreate" })
