export const WorkflowEmailSendingRates = Schema.Struct({ "bounce_rate": Schema.Number.annotate({ "description": "Hard (permanent) bounces / emails sent over the last 30 days (0-1), matching how AWS counts its bounce rate — transient bounces (greylisting, mailbox full) are excluded. Bounces are counted when the feedback arrives, so the ratio is approximate at the window boundary and capped at 1.", "readOnly": true, "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "complaint_rate": Schema.Number.annotate({ "description": "Spam complaints / emails sent over the last 30 days (0-1). Complaints are counted when the feedback arrives, so the ratio is approximate at the window boundary and capped at 1.", "readOnly": true, "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "emails_sent": Schema.Number.annotate({ "description": "Emails sent in the last 30 days.", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "hog_flow_id": Schema.String.annotate({ "description": "The workflow these rates are for.", "readOnly": true, "format": "uuid" }), "hog_flow_name": Schema.String.annotate({ "description": "Display name of the workflow; empty for unnamed workflows.", "readOnly": true }), "email_sending_paused": Schema.Boolean.annotate({ "description": "True when PostHog paused this workflow's email automatically because its complaint or hard bounce rate crossed a threshold. Independent of the AWS tenant verdict and of the project-wide suspension.", "readOnly": true }), "email_sending_paused_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When the pause started; null when not paused.", "readOnly": true, "format": "date-time" }), "email_sending_paused_reason": Schema.String.annotate({ "description": "Plain-language reason for the pause, naming the signal and the window. Empty when not paused.", "readOnly": true }) }).annotate({ "description": "Bounce/complaint rates over the last 30 days of workflow email, computed on the fly from app metrics.", "identifier": "WorkflowEmailSendingRates" })
