export const IspSendingHealth = Schema.Struct({ "isp": Schema.String.annotate({ "description": "The recipient mailbox provider, as AWS names it — for example Gmail or Yahoo.", "readOnly": true }), "emails_sent": Schema.Number.annotate({ "description": "Emails sent to this provider during the window.", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "delivery_rate": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Emails this provider accepted, divided by emails sent to it (0-1). Acceptance is not inbox placement: a provider can accept a message and still file it as spam. Null when the underlying metric could not be loaded from AWS, which is not the same as zero.", "readOnly": true, "format": "double" }), "bounce_rate": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Hard (permanent) bounces at this provider, divided by emails sent to it (0-1). Null when the underlying metric could not be loaded from AWS.", "readOnly": true, "format": "double" }), "transient_bounce_rate": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Soft (transient) bounces at this provider, divided by emails sent to it (0-1). These are deferrals the provider may accept on a retry, such as a full mailbox, greylisting or rate limiting, so they are counted apart from permanent bounces. Null when the underlying metric could not be loaded from AWS.", "readOnly": true, "format": "double" }), "complaint_rate": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Spam complaints from this provider, divided by the deliveries it reports complaints for (0-1). Null when there is no rate to state — the provider runs no feedback loop, or nothing was delivered — and also when the metric could not be loaded from AWS.", "readOnly": true, "format": "double" }), "complaint_base": Schema.Number.annotate({ "description": "Deliveries the provider reports complaints for, which is what `complaint_rate` divides by. Far smaller than `emails_sent`, so a caller deciding whether the rate rests on enough volume has to weigh it against this. Zero when there is no base.", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "unavailable": Schema.Array(Schema.String).annotate({ "description": "Rates AWS did not return for this provider, from `delivery`, `bounce`, `transient_bounce` and `complaint`. A rate named here is missing, not zero, and the UI says so rather than showing a number.", "readOnly": true }) }).annotate({ "description": "How one mailbox provider treated this project's email, from AWS SES's own delivery data.", "identifier": "IspSendingHealth" })
