export const ScoutToolCatalogueEntry = Schema.Struct({ "name": Schema.String.annotate({ "description": "The tool's permanent identifier, for example `insight-get`. This is the name a scout calls." }), "title": Schema.String.annotate({ "description": "The label people read, for example `Get insight`." }), "summary": Schema.String.annotate({ "description": "One line on what the tool does. The tool's full description runs to several kilobytes on some tools, so it is not part of this listing." }), "category": Schema.String.annotate({ "description": "The product area the tool belongs to, for example `Error tracking`. Use it to group the listing." }), "feature": Schema.String.annotate({ "description": "The feature key the MCP server filters on, for example `error_tracking`. Narrower than `category`." }), "required_scopes": Schema.Array(Schema.String).annotate({ "description": "The API scopes a token must carry to call the tool. Empty for a tool that needs none." }), "is_read_only": Schema.Boolean.annotate({ "description": "True when the tool only reads. A false value means the tool can change the project's data." }), "requires_ai_consent": Schema.Boolean.annotate({ "description": "True when the tool is hidden until the project consents to AI features." }), "holdable": Schema.Boolean.annotate({ "description": "True when a scout run can hold every scope the tool requires. A false value means no scout reaches the tool, whatever it is granted, so it cannot be configured for one." }), "missing_scopes": Schema.Array(Schema.String).annotate({ "description": "Required scopes the baseline `signals_scout` preset does not carry. On a holdable tool these are what the scout has to be granted, or the preset it has to opt into. On a tool that is not holdable they include every scope no scout can reach, and can also include scopes a person can grant. Compare them with `grantable_write_scopes` and `presets` to tell the two apart." }), "feature_flag": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Feature flag key that gates the tool, or null when the tool is always served. The flag resolves per project, so evaluate it for the project you are configuring before you offer the tool." }), "feature_flag_behavior": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "How `feature_flag` gates the tool: `enable` (served only while the flag is on) or `disable` (served only while the flag is off). Null means the default, `enable`." }), "feature_flag_variant": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Variant of `feature_flag` the tool needs, or null when any truthy value serves it." }), "hidden_when_flag_on": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "A second flag key that hides the tool while it is on, independent of `feature_flag`. Usually null." }), "feature_entitlement": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Plan feature the organization must have for the tool to be served, or null when the tool is free." }) }).annotate({ "description": "One MCP tool, with what a scout would need to call it.", "identifier": "ScoutToolCatalogueEntry" })
