export const ScoutLimits = Schema.Struct({ "max_runs_per_tick": Schema.Number.annotate({ "description": "Most scout runs the team can start in a single 30-minute coordinator tick." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "max_runs_per_day": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Most scout runs the team can start per rolling 24 hours, or null when uncapped." }), "runs_today": Schema.Number.annotate({ "description": "Scout runs the team has started in the trailing 24 hours." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "runs_remaining_today": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Runs still allowed in the trailing 24h window (max_runs_per_day − runs_today), or null when uncapped." }), "max_enabled_scouts": Schema.Number.annotate({ "description": "Most scouts the project can have switched on at once. Enabling another past this is rejected." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "description": "A team's enforced scout caps and current usage.\n\nThese are the values the coordinator actually applies at dispatch (resolved per-team override →\nfleet-wide default → code constant), so the UI can show the real throttle rather than what a\nuser thinks they configured.", "identifier": "ScoutLimits" })
