export const ScoutNote = Schema.Struct({ "id": Schema.String.annotate({ "description": "Note UUID. Pass to `scout-notes-delete` to retire the note." }), "skill_name": Schema.String.annotate({ "description": "Who the note is addressed to: a configured scout's skill name, a pipeline audience (`pipeline:*`, e.g. `pipeline:report-research`), or blank for a general note every scout sees." }), "content": Schema.String.annotate({ "description": "The note's prose, read verbatim by the run that picks it up." }), "created_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 creation timestamp." }), "expires_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 expiry, or null for a note that stays active until deleted." }), "created_by_name": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Display name of the user who left the note, or null when unavailable." }), "origin": Schema.String.annotate({ "description": "Where the note came from. `human`: left directly through this API. `report_note`: left through this API with `report_id` set, about the report its content names. `report_dismissal`: the note someone typed when they dismissed, snoozed, or restored one or more inbox reports. `report_discussion`: the question someone asked when they opened a discussion on a report. `report_feedback`: the note someone left when they rated a report useful or not. `report_reviewer_correction`: someone added or removed a suggested reviewer on a report, or a person or their agent claimed a report. The `scout-notes-list` tool description says how a scout reads each origin." }) }).annotate({ "description": "`SignalScoutNote` projection used by `notes-list` and `notes-create`.", "identifier": "ScoutNote" })
export type ScoutNoteCreateRequest = { readonly "content": string, readonly "skill_name"?: string, readonly "report_id"?: string | null, readonly "expires_at"?: string | null }
export const ScoutNoteCreateRequest = Schema.Struct({ "content": Schema.String.annotate({ "description": "The note's prose — feedback, a pointer, or a nudge for the scout(s) to weigh on their next runs (e.g. 'we shipped a new checkout on Tuesday, watch conversion closely', 'stop flagging the staging traffic spike'). Write it in Markdown; the run reads it verbatim." }).check(Schema.isMaxCodePoints(10000).annotate({ "expected": "a string with at most 10000 code points" })), "skill_name": Schema.optionalKey(Schema.String.annotate({ "description": "Address the note to one scout by its skill name (exact match against a configured scout on the project — check `scout-config-list` for the roster), or to one stage of the report pipeline by its reserved audience (`pipeline:report-research`); any other `pipeline:*` value is rejected. Use a pipeline audience for guidance about how reports get researched, judged, and routed rather than about what the scouts watch, so it reaches that stage and no scout. Omit or leave blank for a general note every scout sees." }).check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" }))), "report_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional id of the inbox report this note is about. The note then names the report so a scout can fetch it, and the report's activity log records that the note was left. Requires edit access to inbox reports, and the report must belong to this project. The report reference shares the note's character budget, so `content` is capped at 9938 characters when this is set.", "format": "uuid" })), "expires_at": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional ISO-8601 expiry. After this time the note drops out of the default list view, so time-boxed steering ('watch closely this week') retires itself. Omit for a note that stays active until deleted. Best-effort — a value that can't be parsed or is already in the past is dropped (the note stays active), not rejected, so the note is never lost." })) }).annotate({ "description": "Request body for `notes-create`.", "identifier": "ScoutNoteCreateRequest" })
export type EmitEligibility = { readonly "ai_processing_approved": boolean, readonly "source_enabled": boolean, readonly "scout_emit_enabled": boolean | null, readonly "can_emit": boolean, readonly "blocking_reason": string | null, readonly "remediation": string | null }
export const EmitEligibility = Schema.Struct({ "ai_processing_approved": Schema.Boolean.annotate({ "description": "Whether the organization has approved AI data processing (an org-level gate on all scout emits)." }), "source_enabled": Schema.Boolean.annotate({ "description": "Whether the `signals_scout` signal source is enabled for this team." }), "scout_emit_enabled": Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether the calling scout's own config can write, as opposed to running in dry-run (`emit=false`), where it investigates but everything it writes is discarded. Null when the read is not from a scout run, so no single scout's config applies." }), "can_emit": Schema.Boolean.annotate({ "description": "True only when every gate passes, so this scout's findings and reports (both channels) actually reach the inbox. When False, every write is dropped or refused — quick-close instead of doing throwaway investigation. Read this one value: it accounts for the calling scout's own dry-run posture as well as the team-wide gates, and it is the same gate `emit-report` and `edit-report` apply at write time." }), "blocking_reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Which gate blocks the write: `scout_emit_disabled`, `scout_config_missing`, `ai_processing_not_approved`, or `source_disabled`. Null when `can_emit` is True. Matches the `skipped_reason` `emit-report` returns for the same block." }), "remediation": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "One-line next step to unblock writes when `can_emit` is False; null when writes can flow." }) }).annotate({ "description": "`inventory.emit_eligibility` — whether the calling scout's findings and reports can reach the inbox.", "identifier": "EmitEligibility" })
