export const TopEventEntry = Schema.Struct({ "window_days": Schema.Number.annotate({ "description": "Rolling lookback window (in days) that every count and timestamp on this row is measured over — these are windowed figures, NOT lifetime totals. A capture gap can collapse a real, high-volume project's in-window counts to near-zero, so a thin `count` here does not by itself mean the project is low-volume: rule out an ingestion gap (compare against a trailing baseline via a direct `execute-sql`) before closing out a surface as unused." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "event": Schema.String.annotate({ "description": "Event name as captured." }), "count": Schema.Number.annotate({ "description": "Number of occurrences within the last `window_days` (windowed, not lifetime)." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "distinct_users": Schema.Number.annotate({ "description": "`uniq(person_id)` over the window — reach. Distinguishes a high-count event firing on one power user from one firing on many users." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "recent_24h_count": Schema.Number.annotate({ "description": "Count in just the last 24 hours. Compare to `count / window_days` to spot bursts: a ratio well above `1 / window_days` means the event is concentrated in the last day." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "recent_24h_users": Schema.Number.annotate({ "description": "`uniq(person_id)` over just the last 24 hours. A burst across many users is qualitatively different from one user in a loop." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "first_seen_in_window": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 timestamp of the earliest occurrence within the `window_days` window. Compare to the window start to spot new event types: close to `now` ⇒ likely new or recently bursting; close to the window edge ⇒ has been around at least that long (the window can't tell you when the event *truly* first appeared)." }), "last_seen_in_window": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 timestamp of the most recent occurrence within the `window_days` window." }) }).annotate({ "description": "One row in `inventory.top_events`.", "identifier": "TopEventEntry" })
