export const ScoutCheckSummary = Schema.Struct({ "check_id": Schema.String.annotate({ "description": "The check.", "format": "uuid" }), "report_id": Schema.String.annotate({ "description": "The report it is attached to.", "format": "uuid" }), "title": Schema.String.annotate({ "description": "The expectation the check states." }), "kind": Schema.String.annotate({ "description": "`metric_threshold` (the coordinator measures it) or `agent` (a run does)." }), "status": Schema.String.annotate({ "description": "`pending` while the check waits for the report to resolve, `active` while it still runs; every other value is terminal." }), "next_run_at": Schema.String.annotate({ "description": "When the check next runs. Provisional while it is `pending`.", "format": "date-time" }), "last_outcome": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Verdict of the most recent run; null before the first." }), "last_outcome_reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why the most recent run was `inconclusive`: `awaiting_data`, `unmeasurable`, `needs_manual_verification`, or `no_fix_to_measure`. Null on any other outcome." }), "run_state": Schema.String.annotate({ "description": "Where the check is in its run cycle. `waiting_on_report`: pending, no fix to measure yet. `paused`: active, but its report is suppressed or its horizon passed, so nothing runs it. `scheduled`: active, not due yet. `due`: due now, so a run on the check's scout may record the verdict. `queued`: a run was dispatched and has not started. `running`: the dispatched run started and has time left. `stale`: the dispatched run recorded nothing in its window, so the coordinator dispatches again. Any other value is the terminal status." }), "waiting_on_run": Schema.Boolean.annotate({ "description": "True while an `agent` check waits on a dispatched run to record its verdict." }), "dispatched_run_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The scout run the coordinator dispatched for the check, once it started. Null while queued.", "format": "uuid" }), "dispatched_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When the coordinator last dispatched a run for the check. Null when no run waits.", "format": "date-time" }) }).annotate({ "description": "One check as a scout run reads it back.", "identifier": "ScoutCheckSummary" })
