export const FleetFindingsSummary = Schema.Struct({ "count": Schema.Number.annotate({ "description": "Total findings the fleet emitted in the window — the sum of each run's `emitted_count`, over the most recent 120 runs that produced output." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "scout_count": Schema.Number.annotate({ "description": "Number of distinct scouts (skills) that produced output in the window — emitted a finding, or authored/edited an inbox report that survives the 50-report cap (a report-only scout whose touched reports all fell outside the cap is not counted, matching the findings page's scout filter)." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "authored_report_count": Schema.Number.annotate({ "description": "Number of distinct inbox reports scouts authored via `emit_report`, deduped across runs, over the same most-recent-120-output-runs set as `count`, capped to the 50 most recently touched reports (the same slice the findings page lists)." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "edited_report_count": Schema.Number.annotate({ "description": "Number of distinct inbox reports scouts edited via `edit_report`, deduped across runs, over the same most-recent-120-output-runs set as `count`, capped to the 50 most recently touched reports (the same slice the findings page lists) and excluding reports also authored within that set (authoring supersedes an edit; a report whose authoring run falls outside the cap counts as edited)." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "run_count": Schema.Number.annotate({ "description": "Number of scout runs created in the window, whether or not they produced output. Unlike the report tallies it is not capped, so it is the fleet's activity over the same span the output counts describe." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "latest_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 timestamp of the most recent output run (TaskRun completion, falling back to run creation), or null when nothing was produced in the window.", "format": "date-time" }) }).annotate({ "description": "Fleet-wide tally of recent scout output — legacy `emit_signal` findings plus reports\nauthored/edited via the report channel. Backs the \"Scout findings\" callout so it renders\nfrom one cheap query instead of the client walking the whole paginated runs window.", "identifier": "FleetFindingsSummary" })
export type RememberRequest = { readonly "key": string, readonly "content": string, readonly "run_id"?: string | null, readonly "expires_at"?: string | null }
export const RememberRequest = Schema.Struct({ "key": Schema.String.annotate({ "description": "Short stable ID for what you're tracking, e.g. `noise:<fingerprint>`; max 300 chars, the note goes in `content`. Unique per team; re-using a key overwrites the entry. Never embed a date, timestamp, or run id (that mints a new row every run). For run state, use one fixed key and keep the timestamp in `content`." }).check(Schema.isMaxCodePoints(300).annotate({ "expected": "a string with at most 300 code points" })), "content": Schema.String.annotate({ "description": "Markdown to write. Future prompts read it verbatim and people read it directly, so structured Markdown (headings, bullets, inline code for ids) is easier to skim than a wall of prose." }).check(Schema.isMaxCodePoints(50000).annotate({ "expected": "a string with at most 50000 code points" })), "run_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Run that authored this memory; persisted as `created_by_run_id` for lineage. Best-effort — a `run_id` that is unparseable, or that isn't a run on this project, is dropped rather than rejected, so the memory write is never lost. Omit it and the lineage still lands: a write from a scout sandbox is attributed to that sandbox's own run. A report-pipeline caller is attributed by its stage and does not pass one.", "format": "uuid" })), "expires_at": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional ISO-8601 expiry for a memory that's only true for a while (a cooldown, a window you're watching). After this time the entry drops out of searches, so you don't have to come back and forget it. Omit for a durable memory — every write sets the whole entry, so omitting it on a later write clears an expiry set earlier. Best-effort — a value that can't be parsed or is already in the past is dropped (the memory stays durable), not rejected, so the memory write is never lost." })) }).annotate({ "description": "Request body for `remember`.", "identifier": "RememberRequest" })
