export const DraftScannerRequest = Schema.Struct({ "goal": Schema.String.annotate({ "description": "What the user wants to accomplish, e.g. 'find out where users get stuck during onboarding'." }).check(Schema.isMaxCodePoints(2000).annotate({ "expected": "a string with at most 2000 code points" })), "monthly_credit_budget": Schema.optionalKey(Schema.Number.annotate({ "description": "Credits a month to spend (1 credit = $0.01). The draft picks the `model`, then solves `sampling_mode` and `sampling_rate` so the projected spend lands on this number, and sets `credit_limit` to it as a hard cap. Ask the person for it rather than guessing. Required unless `free_only` is true, and not allowed with it." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })).check(Schema.isLessThanOrEqualTo(100000000).annotate({ "expected": "a value less than or equal to 100000000" }))), "free_only": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Draft a scanner that runs only on the organization's free monthly credits, so it never adds to the bill and stops when they run out. The draft is sized to those free credits and comes back with `free_only` true and no `credit_limit`. Use instead of `monthly_credit_budget`.", "default": false })), "experiment_id": Schema.optionalKey(Schema.Number.annotate({ "description": "A launched experiment the person picked for the scanner to watch. The draft is then an `experiment` scanner on it.", "format": "int64" }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })).check(Schema.isLessThanOrEqualTo(9223372036854776000).annotate({ "expected": "a value less than or equal to 9223372036854776000" }))), "query": Schema.optionalKey(Schema.Json.annotate({ "expected": "JSON value", "description": "A `RecordingsQuery` the person already chose, as the replay list holds it. The draft starts from it and never removes or widens it. When the goal asks for narrower recordings, the draft can AND its own page, event, action or cohort filters onto it. It keeps them only when the combined filter still matches recent recordings, returns them in `query_additions`, and sizes the sampling dials against the combined `query`. `experiment_exposure` becomes the scanner's experiment and variants, which the draft keeps as they are. `date_from`/`date_to` are dropped, because a scanner's schedule owns time. `comment_text`, `hide_viewed_recordings` and in-session exposure are refused, because a scanner cannot apply them. A query with no filters starts from every new recording. Omit to let the draft pick the sessions." })) }).annotate({ "description": "Body of POST /vision/scanners/draft/ — the user's goal, stated in their own words.", "identifier": "DraftScannerRequest" })
