export const AEOPromptStats = Schema.Struct({ "engines": Schema.Array(AEOPromptEngineStats).annotate({ "description": "Totals per answer engine over the prompt's whole history." }), "daily": Schema.Array(AEOPromptDailyEngineStats).annotate({ "description": "Counts per day and engine from 'daily_from' to 'daily_to' (30 days). Days and engines without a check are left out." }), "consensus": Schema.Array(AEOPromptEngineDomainShare).annotate({ "description": "One row per engine and per domain for the 10 most cited domains of the last 30 days: how many of the engine's answers cited the domain. Shows which sources the engines agree on." }), "sentiment": Schema.Array(AEOPromptEngineSentiment).annotate({ "description": "Brand sentiment of the answers in the last 30 days, one row per engine. Only the sentences that name the brand are scored." }), "top_words": Schema.Array(AEOPromptSearchWord).annotate({ "description": "Most used words across the web searches the engines ran in the last 30 days, at most 20. Only engines that report their searches contribute." }), "total_checks": Schema.Number.annotate({ "description": "Checks of the prompt across all engines, failed ones included." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "brand_names": Schema.Array(Schema.String).annotate({ "description": "Lower-cased brand names, derived from the project's target domains. An answer that contains one of them as a word counts as a mention." }), "daily_from": Schema.String.annotate({ "description": "First day of the daily series, in the project's timezone.", "format": "date" }), "daily_to": Schema.String.annotate({ "description": "Last day of the daily series (today), in the project's timezone.", "format": "date" }) }).annotate({ "identifier": "AEOPromptStats" })
