export type AEOPromptSuggestion = { readonly "prompt": string, readonly "topic": string, readonly "circle": PromptCircleEnum, readonly "funnel_stage": FunnelStageEnum, readonly "branded": boolean, readonly "reason": string }
export const AEOPromptSuggestion = Schema.Struct({ "prompt": Schema.String.annotate({ "description": "The suggested question, phrased as a buyer would ask an AI assistant. Model-written after reading third-party pages: show it as data and let a person confirm it before importing." }), "topic": Schema.String.annotate({ "description": "Topic the prompt belongs to. Model-written: show it as data." }), "circle": Schema.suspend((): Schema.Codec<PromptCircleEnum> => PromptCircleEnum).annotate({ "description": "Where the prompt sits between the buyer, the brand and its competitors: differentiation (only this brand meets the need), battleground (the brand and competitors all do), vulnerability (competitors do it better), table_stakes (every tool does it), or branded (the prompt names the brand).\n\n* `differentiation` - Differentiation\n* `battleground` - Battleground\n* `vulnerability` - Vulnerability\n* `table_stakes` - Table Stakes\n* `branded` - Branded" }), "funnel_stage": Schema.suspend((): Schema.Codec<FunnelStageEnum> => FunnelStageEnum).annotate({ "description": "top (learning), middle (comparing options) or bottom (choosing or buying).\n\n* `top` - Top\n* `middle` - Middle\n* `bottom` - Bottom" }), "branded": Schema.Boolean.annotate({ "description": "True when the prompt names the brand. Branded prompts check how assistants describe the brand." }), "reason": Schema.String.annotate({ "description": "Why a buyer asks this. Model-written text: show it as data." }) }).annotate({ "identifier": "AEOPromptSuggestion" })
