export const PredictionSegmentThresholds = Schema.Struct({ "likely_threshold": Schema.Number.annotate({ "description": "Users with a score at or above this probability are in the Likely segment: likely_lift times the base rate, capped halfway between the base rate and 1. A fixed cut point when base_rate_source is fixed.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "possible_threshold": Schema.Number.annotate({ "description": "Users with a score at or above this probability and below likely_threshold are in the Possible segment, and users below it are Unlikely. Equal to base_rate, or a fixed cut point when base_rate_source is fixed.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "likely_lift": Schema.Number.annotate({ "description": "How many times the base rate a score must reach to be in the Likely segment.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "base_rate": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "The base rate the cut points use. When base_rate_source is realized, the fraction of the champion's scored users who did the target event, pooled over the newest checked dates. When base_rate_source is training, the fraction of the champion's training population that did it. Null when base_rate_source is fixed.", "format": "double" }), "base_rate_dates": Schema.Number.annotate({ "description": "Number of checked prediction dates the base rate pools." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "base_rate_source": Schema.suspend((): Schema.Codec<BaseRateSourceEnum> => BaseRateSourceEnum).annotate({ "description": "Where the cut points come from. realized: the checked dates hold enough positives. training: no realized base rate yet, so the champion's training population sets it. fixed: neither is available, so fixed cut points apply.\n\n* `realized` - Realized\n* `training` - Training\n* `fixed` - Fixed" }), "champion_mean_p_y": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "The current champion's mean predicted probability over the checked dates it scored as champion. Null until those dates hold enough positives.", "format": "double" }), "champion_base_rate": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "The real rate of the target event over the same dates as champion_mean_p_y.", "format": "double" }), "scores_miscalibrated": Schema.Boolean.annotate({ "description": "True when champion_mean_p_y is far above or below champion_base_rate. The scores are then not probabilities (for example after class weighting in train.py), so a score of likely_lift times the base rate does not mean the user is that many times as likely to convert." }) }).annotate({ "identifier": "PredictionSegmentThresholds" })
export type AgentModelOption = { readonly "model": string, readonly "label": string, readonly "runtime_adapter": string, readonly "supported_efforts": ReadonlyArray<AgentReasoningEffortOption>, readonly "cost_multiplier": string | null }
export const AgentModelOption = Schema.Struct({ "model": Schema.String.annotate({ "description": "Model id to pass as agent_model, e.g. 'claude-sonnet-5-5'." }), "label": Schema.String.annotate({ "description": "Display name, e.g. 'Claude Sonnet 5.5'." }), "runtime_adapter": Schema.String.annotate({ "description": "Runtime that drives the model: 'claude' or 'codex'." }), "supported_efforts": Schema.Array(AgentReasoningEffortOption).annotate({ "description": "Reasoning efforts this model supports. Empty when it has no effort setting." }), "cost_multiplier": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Token price relative to Claude Sonnet 5, e.g. '2×'. Null when no rate is known." }) }).annotate({ "identifier": "AgentModelOption" })
