export const ResolvedTemplate = Schema.Struct({ "template_key": Schema.suspend((): Schema.Codec<TemplateKeyEnum> => TemplateKeyEnum).annotate({ "description": "The template key that was resolved. Pass it back to re-resolve with a different target_event.\n\n* `likely_active_soon` - Likely Active Soon\n* `at_risk_of_inactivity` - At Risk Of Inactivity\n* `return_after_first_use` - Return After First Use\n* `feature_adoption` - Feature Adoption\n* `repeat_key_behavior` - Repeat Key Behavior" }), "display_name": Schema.String.annotate({ "description": "Human-readable template name." }), "description": Schema.String.annotate({ "description": "What this template predicts." }), "suggested_name": Schema.String.annotate({ "description": "Suggested pipeline name. Pass as 'name' to autoresearch-create." }), "target_event": Schema.String.annotate({ "description": "Resolved target event. Pass as 'target_event' to autoresearch-create. For activity-based templates this is the auto-resolved activity event (or your override)." }), "resolved_activity_event": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Activity event found in your event schema, populated only for templates that auto-resolve the target ('likely_active_soon', 'at_risk_of_inactivity', 'return_after_first_use'). Null for templates where you supply target_event directly." }), "activity_event_alternatives": Schema.Array(Schema.String).annotate({ "description": "Other viable activity events found in your schema. If the resolved event is not the right signal, re-resolve with one of these as target_event." }), "horizon_days": Schema.Number.annotate({ "description": "Resolved prediction horizon in days." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "training_lookback_days": Schema.Number.annotate({ "description": "Training lookback in days, sized so the horizon leaves room for training examples. Pass as 'training_lookback_days' to autoresearch-create." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "training_population": Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })).annotate({ "description": "Resolved training population filter. Pass as 'training_population' to autoresearch-create.", "examples": [{ "kind": "performed_event_within_days", "event": "$pageview", "days": 30 }] }), "inference_population": Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })).annotate({ "description": "Resolved inference (daily scoring) population filter. Pass as 'inference_population' to autoresearch-create.", "examples": [{ "kind": "performed_event_within_days", "event": "$pageview", "days": 30 }] }), "output_person_property": Schema.String.annotate({ "description": "Suggested person property name for prediction scores. Pass as 'output_person_property' to autoresearch-create." }), "notes": Schema.String.annotate({ "description": "Usage notes and guidance for interpreting this resolved config." }) }).annotate({ "identifier": "ResolvedTemplate" })
