export const ValidationWarning = Schema.Struct({ "code": Schema.String.annotate({ "description": "Machine-readable warning code. 'horizon_exceeds_lookback', and 'population_too_large' with severity 'error', mean a run would fail: fix the definition before creating. 'population_too_large' with severity 'info' means training uses a sample of the population, or each scoring run scores a rolling part of it: users never scored first, then users whose last score was oldest. 'low_volume', 'low_positives' and 'low_negatives' mean the data is too thin for a reliable model (severity 'error', advisory). 'moderate_volume', 'mostly_anonymous_population', 'extreme_imbalance' and 'near_universal' are severity 'warning'." }), "message": Schema.String.annotate({ "description": "Human-readable warning description." }), "severity": Schema.suspend((): Schema.Codec<ValidationWarningSeverityEnum> => ValidationWarningSeverityEnum).annotate({ "description": "Severity level. 'error' means training would fail or the data is too thin for a reliable model; see 'code' for which. 'warning' is worth acknowledging. Creation enforces none of them.\n\n* `info` - info\n* `warning` - warning\n* `error` - error" }) }).annotate({ "identifier": "ValidationWarning" })
