export const CanvasSourceEditOperation = Schema.Struct({ "op": Schema.optionalKey(Schema.suspend((): Schema.Codec<CanvasSourceEditOpEnum> => CanvasSourceEditOpEnum).annotate({ "description": "What to do. 'str_replace' replaces old_string with new_string inside the file: the default for changing an existing file. 'write' sets the file's complete content (new files, full rewrites). 'delete' removes the file. 'rename' moves it to new_path. When omitted, it follows the fields sent: old_string or new_string means 'str_replace', new_path means 'rename', non-null content means 'write', and content null means 'delete'. An operation with none of these fields is rejected.\n\n* `write` - Write\n* `delete` - Delete\n* `rename` - Rename\n* `str_replace` - Str Replace" })), "path": Schema.String.annotate({ "description": "Project-relative path of the file to edit (e.g. \"src/canvas.tsx\")." }), "content": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "For 'write': the file's complete new content." })), "old_string": Schema.optionalKey(Schema.String.annotate({ "description": "For 'str_replace': the exact text to replace, copied from the file with a few surrounding lines so it matches one place only. If whitespace differs slightly, a unique line-by-line match is still accepted." })), "new_string": Schema.optionalKey(Schema.String.annotate({ "description": "For 'str_replace': the text that replaces old_string. An empty string deletes old_string." })), "replace_all": Schema.optionalKey(Schema.Boolean.annotate({ "description": "For 'str_replace': replace every exact match of old_string instead of requiring exactly one.", "default": false })), "new_path": Schema.optionalKey(Schema.String.annotate({ "description": "For 'rename': the file's new project-relative path." })) }).annotate({ "description": "One file edit: replace text in a file, write a whole file, delete it, or rename it.", "identifier": "CanvasSourceEditOperation" })
