export const BrokenTestRow = Schema.Struct({ "fingerprint": Schema.String.annotate({ "description": "Stable identity of this distinct failure: the failing test's node id plus a normalized error signature, so the same failure across runs groups into one row." }), "test_id": Schema.String.annotate({ "description": "The pytest node id from the CI 'FAILED <id>' line: the failing test." }), "error_signature": Schema.String.annotate({ "description": "The trailing failure detail with volatile bits (numbers, hashes) normalized, shared across runs of the same failure. Empty when the FAILED line carried no detail." }), "job_name": Schema.String.annotate({ "description": "The CI job the failure most recently came from. Matched against default-branch job status to decide whether trunk is currently broken by it." }), "repo": Schema.String.annotate({ "description": "'owner/name' repository the failure belongs to." }), "state": Schema.suspend((): Schema.Codec<BrokenTestStateEnum> => BrokenTestStateEnum).annotate({ "description": "The classifier's verdict on how this failure is behaving right now: 'breaking_master' (failing on trunk, latest trunk run still red), 'blocking_merge_queue' (stopped a merge on a commit that already passed the PR's own CI, trunk still green), 'novel_burst' (new within a day and spreading across branches, not on trunk yet), 'potentially_resolved' (hit trunk but trunk is green again), 'flaky' (sporadic across branches over more than a day), or 'pr_only' (confined to one branch: one PR's own problem).\n\n* `breaking_master` - Breaking Master\n* `blocking_merge_queue` - Blocking Merge Queue\n* `novel_burst` - Novel Burst\n* `potentially_resolved` - Potentially Resolved\n* `flaky` - Flaky\n* `pr_only` - PR Only" }), "first_seen": Schema.String.annotate({ "description": "Earliest failure line for this fingerprint in the analysis window.", "format": "date-time" }), "last_seen": Schema.String.annotate({ "description": "Most recent failure line for this fingerprint in the analysis window.", "format": "date-time" }), "occurrences": Schema.Number.annotate({ "description": "Total failure lines for this fingerprint in the window. An absolute count, never a rate: passing runs aren't in this data." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "branches": Schema.Number.annotate({ "description": "Distinct branches the failure appeared on in the window." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "master_hits": Schema.Number.annotate({ "description": "Failure lines on the default branch (master/main). 0 means it never reached trunk." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "latest_run_id": Schema.Number.annotate({ "description": "The most recent failing workflow run for this fingerprint: pass it to run_failure_logs to fetch the actual failing log lines." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "latest_branch": Schema.String.annotate({ "description": "The branch of the most recent failing run." }), "trend_24h": Schema.optionalKey(Schema.Array(Schema.Int).annotate({ "description": "Hourly failure counts over the last 24 hours, oldest first (fixed 24-slot array), for the row sparkline. All zeros when nothing failed in the last day." })), "latest_ci_engine": Schema.optionalKey(Schema.Union([CIEngineEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "CI execution engine; null when unknown.\n\n* `github_actions` - GitHub Actions\n* `depot_ci` - Depot CI" })) }).annotate({ "identifier": "BrokenTestRow" })
