export const JobLogBadge = Schema.Struct({ "kind": Schema.suspend((): Schema.Codec<JobLogBadgeKindEnum> => JobLogBadgeKindEnum).annotate({ "description": "What the badge is about: a dependency cache, or migrations.\n\n* `cache` - Cache\n* `migrations` - Migrations" }), "state": Schema.suspend((): Schema.Codec<JobLogBadgeStateEnum> => JobLogBadgeStateEnum).annotate({ "description": "What happened. For a cache: 'hit' (exact key restored), 'partial' (an older cache restored from a restore key), 'miss' (nothing restored), 'failed' (the restore itself failed). For migrations: 'none' (nothing to apply) or 'applied'.\n\n* `hit` - Cache hit\n* `partial` - Older cache\n* `miss` - Cache miss\n* `failed` - Cache restore failed\n* `none` - No migrations\n* `applied` - Migrations applied" }), "count": Schema.Number.annotate({ "description": "How many times the log reports this outcome." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "detail": Schema.Array(Schema.String).annotate({ "description": "What each occurrence was about: a cache key or a migration name. Capped, so it can hold fewer entries than `count`." }) }).annotate({ "identifier": "JobLogBadge" })
