export type PRTimelineSegment = { readonly "kind": PRTimelineSegmentKindEnum, readonly "started_at": string, readonly "ended_at": string }
export const PRTimelineSegment = Schema.Struct({ "kind": Schema.suspend((): Schema.Codec<PRTimelineSegmentKindEnum> => PRTimelineSegmentKindEnum).annotate({ "description": "What the PR waited on: draft; waiting_for_review (no approval yet, or re-review after a push); changes_requested (no push since); approved_not_enqueued (approved, with no failing or running check); review_state_unknown (reviews not synced); ci_running; red_passed_on_rerun (the failed workflows passed a re-run of the same commit); red_master_broken (the failed jobs also failed on the default branch within 12 hours); red_fixed_by_push (a later commit arrived); red_not_provable; merge_queue (every queue state collapsed); out_of_merge_queue (open PR, Trunk says failed or cancelled).\n\n* `draft` - Draft\n* `waiting_for_review` - Waiting For Review\n* `changes_requested` - Changes Requested\n* `approved_not_enqueued` - Approved Not Enqueued\n* `review_state_unknown` - Review State Unknown\n* `ci_running` - CI Running\n* `red_passed_on_rerun` - Red Passed On Rerun\n* `red_master_broken` - Red Master Broken\n* `red_fixed_by_push` - Red Fixed By Push\n* `red_not_provable` - Red Not Provable\n* `merge_queue` - Merge Queue\n* `out_of_merge_queue` - Out Of Merge Queue" }), "started_at": Schema.String.annotate({ "description": "Segment start.", "format": "date-time" }), "ended_at": Schema.String.annotate({ "description": "Segment end: the next segment's start, the merge or close, or now.", "format": "date-time" }) }).annotate({ "identifier": "PRTimelineSegment" })
