export const EndExperiment = Schema.Struct({ "conclusion": Schema.optionalKey(Schema.Union([ConclusionEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The conclusion of the experiment.\n\n* `won` - won\n* `lost` - lost\n* `inconclusive` - inconclusive\n* `stopped_early` - stopped_early\n* `invalid` - invalid" })), "conclusion_comment": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(4000).annotate({ "expected": "a string with at most 4000 code points" })), Schema.Null]).annotate({ "description": "Optional comment about the experiment conclusion." })), "open_cleanup_pr": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, open a draft pull request that removes the experiment's feature-flag code from the linked repository. A personal API key needs the task:write scope (403 otherwise). Skipped when the conclusion is empty, or when no connected repository can be resolved.", "default": false })), "repository": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(255).annotate({ "expected": "a string with at most 255 code points" })), Schema.Null]).annotate({ "description": "GitHub repository to open the cleanup pull request in, in `organization/repository` format. Only used when open_cleanup_pr is true. It must be one of the team's connected repositories (see the flag_cleanup_target action); it is then saved as the experiment's repository. When omitted, the experiment's saved repository, the team's default cleanup repository, or the team's only connected repository is used." })), "set_repository_as_team_default": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, also save `repository` as this environment's default cleanup repository, used for experiments that have no repository of their own. Only acts when open_cleanup_pr is true and `repository` is provided and belongs to the team's GitHub installation. Requires project admin access (403 otherwise).", "default": false })) }).annotate({ "identifier": "EndExperiment" })
