export const ExperimentHealthSetup = Schema.Struct({ "release_conditions": Schema.Array(ExperimentHealthReleaseCondition).annotate({ "description": "The flag's condition sets as stored, in the order the flag evaluates them. Whether a set can serve a request depends on the sets before it and on `early_exit`." }), "early_exit": Schema.Boolean.annotate({ "description": "Whether the flag stops at the first condition set whose filters match, also when its rollout leaves the user out. Otherwise such a user goes on to the next set." }), "bucketing_identifier": Schema.suspend((): Schema.Codec<BucketingIdentifierEnum> => BucketingIdentifierEnum).annotate({ "description": "The flag's `bucketing_identifier`. Null on the flag reads as distinct_id.\n\n* `distinct_id` - User ID (default)\n* `device_id` - Device ID" }), "aggregation_group_type_index": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "The flag's own group type, which the exposure counts and the results use. A condition set can override it. Null for users." }), "evaluation_runtime": Schema.suspend((): Schema.Codec<EvaluationRuntimeEnum> => EvaluationRuntimeEnum).annotate({ "description": "The flag's `evaluation_runtime`. Null on the flag reads as all.\n\n* `server` - Server\n* `client` - Client\n* `all` - All" }), "evaluation_contexts": Schema.Array(Schema.String).annotate({ "description": "The names of the flag's evaluation contexts. When PostHog evaluates the flag, an SDK that sends evaluation contexts gets it only when it sends one of these, and an SDK that sends none gets it. Empty when the flag has none." }), "ensure_experience_continuity": Schema.Boolean.annotate({ "description": "The flag's 'Persist flag across authentication steps' setting." }) }).annotate({ "identifier": "ExperimentHealthSetup" })
