export type ExperimentHealthInputsConditionSetTraffic = { readonly "since": string, readonly "team_timezone": string, readonly "people_by_set": ReadonlyArray<ExperimentHealthInputsConditionSetPeople>, readonly "calls": number, readonly "remotely_evaluated_calls": number, readonly "people_assigned_outside": number, readonly "filters_test_accounts": boolean }
export const ExperimentHealthInputsConditionSetTraffic = Schema.Struct({ "since": Schema.String.annotate({ "description": "The start of the window: the latest of launch, the flag's last save and 7 days ago.", "format": "date-time" }), "team_timezone": Schema.String.annotate({ "description": "The project's time zone, which the finding uses for times." }), "people_by_set": Schema.Array(ExperimentHealthInputsConditionSetPeople).annotate({ "description": "People by the release condition that served their latest call of the flag's version." }), "calls": Schema.Number.annotate({ "description": "The flag's calls in the window, of any flag version." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "remotely_evaluated_calls": Schema.Number.annotate({ "description": "The calls that the flag service evaluated. Only those name a condition set. Local evaluation in a server SDK and a bootstrapped value name none." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "people_assigned_outside": Schema.Number.annotate({ "description": "The people who got a variant from a call without a flag version that is no local evaluation in a server SDK, from an hour after the start of the window: a bootstrap or the caller's own assignment. With a 0% rollout, 10 or more of them turn `running_but_no_rollout` into `assigned_outside_flag_service`." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "filters_test_accounts": Schema.Boolean.annotate({ "description": "Whether the counts leave out the calls that the project's filter for internal and test users excludes, because the experiment applies that filter." }) }).annotate({ "identifier": "ExperimentHealthInputsConditionSetTraffic" })
