export const ExperimentSetupSdkLib = Schema.Struct({ "lib": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The $lib value of the SDK, for example 'web'." }), "category": Schema.suspend((): Schema.Codec<SdkLibCategoryEnum> => SdkLibCategoryEnum).annotate({ "description": "'web' for the JavaScript web SDK, 'mobile', 'server', or 'other' for libraries not classified.\n\n* `web` - Web\n* `mobile` - Mobile\n* `server` - Server\n* `other` - Other" }), "calls": Schema.Number.annotate({ "description": "Multivariate flag calls this SDK sent in the window." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "distinct_ids": Schema.Number.annotate({ "description": "Distinct ids that sent those calls." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "device_id_share": Schema.Number.annotate({ "description": "Share of calls that carry a $device_id. 0 when this SDK never sends one, as server SDKs don't.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "locally_evaluated_share": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Share of calls evaluated locally in the SDK instead of by the flags service. Null when no call from this SDK reported it, as the web SDK doesn't.", "format": "double" }), "anonymous_share": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Share of distinct ids that were anonymous, among those that report whether they are identified. Null when no call from this SDK reported it.", "format": "double" }) }).annotate({ "identifier": "ExperimentSetupSdkLib" })
export type ExperimentSetupLibActivity = { readonly "lib": string | null, readonly "category": SdkLibCategoryEnum, readonly "events": number, readonly "distinct_ids": number }
export const ExperimentSetupLibActivity = Schema.Struct({ "lib": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The $lib value of the SDK, for example 'web'." }), "category": Schema.suspend((): Schema.Codec<SdkLibCategoryEnum> => SdkLibCategoryEnum).annotate({ "description": "'web', 'mobile', 'server', or 'other'.\n\n* `web` - Web\n* `mobile` - Mobile\n* `server` - Server\n* `other` - Other" }), "events": Schema.Number.annotate({ "description": "Events this SDK sent in the window, of any kind." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "distinct_ids": Schema.Number.annotate({ "description": "Distinct ids that sent those events." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "identifier": "ExperimentSetupLibActivity" })
