export const ExperimentSetupLibReach = Schema.Struct({ "lib": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The $lib value that sent the target events." }), "category": Schema.suspend((): Schema.Codec<SdkLibCategoryEnum> => SdkLibCategoryEnum).annotate({ "description": "'web', 'mobile', 'server', or 'other'.\n\n* `web` - Web\n* `mobile` - Mobile\n* `server` - Server\n* `other` - Other" }), "unique_persons": Schema.Number.annotate({ "description": "Persons who sent the target event from this SDK." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "anonymous_share": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Among this SDK's distinct ids that report whether they are identified, the share that was anonymous. Null when no target event from this SDK reported it.", "format": "double" }), "device_id_share": Schema.Number.annotate({ "description": "Share of this SDK's target events that carry a $device_id. 0 when it never sends one.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })) }).annotate({ "identifier": "ExperimentSetupLibReach" })
