export type ExperimentMetricsRecalculationJob = { readonly "id": string, readonly "experiment_id": number, readonly "status": MetricsRecalculationStatusEnum, readonly "total_metrics": number, readonly "completed_metrics": number, readonly "failed_metrics": number, readonly "metric_errors": Schema.Json, readonly "created_at": string, readonly "started_at": string | null, readonly "completed_at": string | null, readonly "query_to": string | null, readonly "is_existing": boolean }
export const ExperimentMetricsRecalculationJob = Schema.Struct({ "id": Schema.String.annotate({ "description": "Unique identifier for this recalculation job", "readOnly": true, "format": "uuid" }), "experiment_id": Schema.Number.annotate({ "description": "ID of the experiment being recalculated", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "status": Schema.suspend((): Schema.Codec<MetricsRecalculationStatusEnum> => MetricsRecalculationStatusEnum).annotate({ "description": "Current status of the recalculation job\n\n* `pending` - Pending\n* `in_progress` - In Progress\n* `completed` - Completed\n* `failed` - Failed", "readOnly": true }), "total_metrics": Schema.Number.annotate({ "description": "Total number of metrics to recalculate", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "completed_metrics": Schema.Number.annotate({ "description": "Number of metrics with a COMPLETED result row that did not fail in this run (derived, not stored)", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "failed_metrics": Schema.Number.annotate({ "description": "Number of failed metrics in this run (derived): metrics with a FAILED result row or a metric_errors entry. A metric that fails keeps its earlier completed result, so it can count here and still have a completed row in results. The error of a rejected run counts only for a metric without a row", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "metric_errors": Schema.Json.annotate({ "expected": "JSON value", "description": "Terminal failure per metric_uuid: {step, message, error_type, retriable, timestamp, exposures_path}. retriable is true when a transient error exhausted its attempts, so a heal_latest_run or manual_retry can succeed; false when the metric config, the data, or a resource limit must change first. exposures_path is where the query read the exposures, and is missing when the query failed before it was built", "readOnly": true }), "created_at": Schema.String.annotate({ "description": "When the job was created", "readOnly": true, "format": "date-time" }), "started_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When processing started", "readOnly": true, "format": "date-time" }), "completed_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When processing completed", "readOnly": true, "format": "date-time" }), "query_to": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Upper time bound the metrics in this run were calculated against (the data freshness cutoff). Shared by every metric in the run; null until processing starts", "readOnly": true, "format": "date-time" }), "is_existing": Schema.Boolean.annotate({ "description": "True if returning an existing job rather than a newly created one", "readOnly": true }) }).annotate({ "description": "POST response: the job just queued, or the one already active. It carries no results or live progress yet.", "identifier": "ExperimentMetricsRecalculationJob" })
