export const ActiveRecalculationRun = Schema.Struct({ "id": Schema.String.annotate({ "description": "Identifier of the run that is still executing", "readOnly": true, "format": "uuid" }), "status": Schema.suspend((): Schema.Codec<MetricsRecalculationStatusEnum> => MetricsRecalculationStatusEnum).annotate({ "description": "Status of the executing run (pending or in_progress)\n\n* `pending` - Pending\n* `in_progress` - In Progress\n* `completed` - Completed\n* `failed` - Failed", "readOnly": true }) }).annotate({ "description": "Pointer to a recalculation run that is still executing, surfaced alongside the latest terminal results.", "identifier": "ActiveRecalculationRun" })
