export const MetricRecalculationResult = Schema.Struct({ "configuration_status": Schema.suspend((): Schema.Codec<ExperimentResultConfigurationStatusEnum> => ExperimentResultConfigurationStatusEnum).annotate({ "description": "Whether this result uses current settings, earlier settings, or settings that were not recorded.\n\n* `current` - Current settings\n* `previous` - Earlier settings\n* `unknown` - Settings not recorded", "readOnly": true }), "metric_uuid": Schema.String.annotate({ "description": "UUID of the metric this result belongs to", "readOnly": true }), "status": Schema.suspend((): Schema.Codec<MetricRecalculationResultStatusEnum> => MetricRecalculationResultStatusEnum).annotate({ "description": "Status of this metric's calculation in the run\n\n* `pending` - pending\n* `completed` - completed\n* `failed` - failed", "readOnly": true }), "result": Schema.Json.annotate({ "expected": "JSON value", "description": "The computed metric result (ExperimentQueryResponse shape); null when status is pending or failed", "readOnly": true }), "error_message": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Error message when status is failed; otherwise null", "readOnly": true }) }).annotate({ "description": "One metric's recalculated result row, read back from ExperimentMetricResult.", "identifier": "MetricRecalculationResult" })
export type RunningTimeOutlook = { readonly "days_since_launch": number, readonly "exposures_per_day": number, readonly "detectable_effect_now": number, readonly "upcoming_checkpoints": ReadonlyArray<DetectableEffectCheckpoint>, readonly "reachable_effect": number }
export const RunningTimeOutlook = Schema.Struct({ "days_since_launch": Schema.Number.annotate({ "description": "Days since the experiment launched, with fractions.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "exposures_per_day": Schema.Number.annotate({ "description": "Exposures that count toward the target, per day from launch to the end of the window the current results cover.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "detectable_effect_now": Schema.Number.annotate({ "description": "The smallest relative change, as a percentage, that the exposures so far can detect.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "upcoming_checkpoints": Schema.Array(DetectableEffectCheckpoint).annotate({ "description": "Up to three week marks after today, out of weeks 1, 2, 4, 6, 8, 12, 16, 26 and 52, with the change each can detect at the exposure rate so far." }), "reachable_effect": Schema.Number.annotate({ "description": "The smallest relative change, as a percentage, that the experiment can detect within four weeks from today. A target for a smaller change is out of reach.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })) }).annotate({ "description": "What the experiment can detect over time, at its exposure rate so far.", "identifier": "RunningTimeOutlook" })
export type ExperimentSessionBucketRequest = { readonly "bucket": ExperimentSessionBucketEnum, readonly "metric_uuids"?: ReadonlyArray<string>, readonly "variant"?: string | null, readonly "limit"?: number }
export const ExperimentSessionBucketRequest = Schema.Struct({ "bucket": Schema.suspend((): Schema.Codec<ExperimentSessionBucketEnum> => ExperimentSessionBucketEnum).annotate({ "description": "Which question the returned session set answers. 'fired_any': the session fired at least one event of any listed metric (an OR the recordings query itself can't express). 'no_metric_activity': the session fired none of them. 'funnel_dropoff': the session saw an exposure event but never fired the funnel metric's last step; the exposure is the funnel's implicit first step, the same as in the experiment analysis. All three are session-scoped and goal-free: they say what happened in the session, not whether it helped or hurt the metric.\n\n* `fired_any` - fired_any\n* `no_metric_activity` - no_metric_activity\n* `funnel_dropoff` - funnel_dropoff" }), "metric_uuids": Schema.optionalKey(Schema.Array(Schema.String.annotate({ "description": "UUID of one of the experiment's metrics." })).annotate({ "description": "Metrics the bucket is computed over. Exactly one funnel metric for 'funnel_dropoff'. Omit for the other buckets to use every metric of the experiment that can be matched to recordings." })), "variant": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Restrict to sessions that saw this variant. Omit for every variant. A session that saw more than one variant matches each variant it saw." })), "limit": Schema.optionalKey(Schema.Number.annotate({ "description": "Maximum session IDs to return, at most 100. The most recently active matching sessions win.", "default": 100 }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })).check(Schema.isLessThanOrEqualTo(100).annotate({ "expected": "a value less than or equal to 100" }))) }).annotate({ "description": "Request body for the session-bucket endpoint.", "identifier": "ExperimentSessionBucketRequest" })
export type ExperimentSessionBucketResponse = { readonly "session_ids": ReadonlyArray<string>, readonly "truncated": boolean, readonly "considered_metrics": ReadonlyArray<ExperimentSessionBucketMetric>, readonly "excluded_metrics": ReadonlyArray<ExperimentSessionBucketExcludedMetric>, readonly "date_from": string, readonly "date_to": string, readonly "filter_test_accounts": boolean, readonly "used_exposure_fallback": boolean }
export const ExperimentSessionBucketResponse = Schema.Struct({ "session_ids": Schema.Array(Schema.String).annotate({ "description": "IDs of matching sessions that have a recording, most recently active first. Feed these to a recordings query as session_ids; they are a subset of the experiment's exposed sessions, so the exposure filter can stay in place alongside them." }), "truncated": Schema.Boolean.annotate({ "description": "True when more sessions matched than the limit returned. Older matches were dropped first." }), "considered_metrics": Schema.Array(ExperimentSessionBucketMetric).annotate({ "description": "The metrics the bucket was actually computed over. Load-bearing for 'no_metric_activity': 'fired nothing' only means something next to the list of metrics it was evaluated against." }), "excluded_metrics": Schema.Array(ExperimentSessionBucketExcludedMetric).annotate({ "description": "Requested metrics left out of the bucket because they can never match a recording, with the reason. They are reported rather than silently producing an empty result." }), "date_from": Schema.String.annotate({ "description": "Start of the window scanned, never before the experiment started. At most 30 days before date_to when the scan found an exposure to anchor on. When it found none, how far back the search for one reached, which the project's recording retention bounds. Matches outside the window are not returned.", "format": "date-time" }), "date_to": Schema.String.annotate({ "description": "End of the window scanned: 24 hours after the latest exposure captured in a session, capped at the experiment's end date or now. The pad covers the metric events a session fires after its exposure. The scan ends at the experiment's end date, or now while it runs, when that exposure can't be located, so an experiment whose exposures stopped long ago is still scanned where its sessions are.", "format": "date-time" }), "filter_test_accounts": Schema.Boolean.annotate({ "description": "Whether the project's test-account filters were applied, following the experiment's exposure criteria, the same rule the experiment's recordings list uses." }), "used_exposure_fallback": Schema.Boolean.annotate({ "description": "True when the exposed population was matched on the stamped $feature/<flag key> event property instead of the exposure event, because the default exposure event has only ever been captured server-side and can never match a session. The sessions then mean 'the flag was active in this session', not 'the exposure moment was captured'. The variant comes from the flag's value on each event, so a returning user can appear under a variant they were re-bucketed into later." }) }).annotate({ "description": "Session recordings of an experiment matching a bucket.", "identifier": "ExperimentSessionBucketResponse" })
export type ExperimentWatchCard = { readonly "kind": ExperimentWatchCardKindEnum, readonly "event": string, readonly "variant": string, readonly "strength": ExperimentWatchCardStrengthEnum | NullEnum, readonly "metric_name": string | null, readonly "recording_count": number, readonly "session_ids": ReadonlyArray<string>, readonly "highlights": ReadonlyArray<ExperimentWatchHighlight> }
export const ExperimentWatchCard = Schema.Struct({ "kind": Schema.suspend((): Schema.Codec<ExperimentWatchCardKindEnum> => ExperimentWatchCardKindEnum).annotate({ "description": "What the card is: 'behavior' for an event this variant did clearly more than the other variants together, 'friction' for the same finding on an error or rage signal, 'variant_only' for an event no other variant fired at all, and 'metric' for a shortcut to recordings around one of the experiment's own metric events. A 'variant_only' card shows the variant rendering its own change rather than a behavior difference, so present it as confirmation the change is live and never as a finding. Metric cards claim nothing about how the metric moved: that is the experiment results' answer.\n\n* `behavior` - behavior\n* `friction` - friction\n* `variant_only` - variant_only\n* `metric` - metric" }), "event": Schema.String.annotate({ "description": "The event behind the card." }), "variant": Schema.String.annotate({ "description": "The variant whose recordings these are: for comparison cards, the one that did the event more." }), "strength": Schema.Union([ExperimentWatchCardStrengthEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How far apart this variant and the rest are, as a band rather than a number: 'only' when nobody in the other variants did it at all among the people compared, then 'far_more', 'more' and 'slightly_more'. Read off the conservative end of the difference, so a card that clears the bar only because the sample is large reports as slight. Null on metric cards, which compare nothing. Present a band as a comparison ('far more common in test'), never convert it into a multiple.\n\n* `only` - only\n* `far_more` - far_more\n* `more` - more\n* `slightly_more` - slightly_more" }), "metric_name": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The metric this card's event belongs to, on a comparison card as well as on a shortcut card. When set, the experiment's results measure this event over the whole run window with the statistics that go with a result, so say the card points there and never present the card as a second answer about that metric. Null when no metric counts the event." }), "recording_count": Schema.Number.annotate({ "description": "How many recordings the card carries, at most max_card_recordings (20). Every card is backed by recordings that actually exist: a finding whose sessions were never recorded is dropped rather than promised. A count sitting on the ceiling means at least that many, so say 'at least' and never compare two such counts: how often the event happened is the experiment's results, and this only counts what replay kept." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "session_ids": Schema.Array(Schema.String).annotate({ "description": "The recordings themselves, most recent first, ready to hand to the recordings list as-is." }), "highlights": Schema.Array(ExperimentWatchHighlight).annotate({ "description": "Which of the card's recordings to open first, at most 3, ranked by how much each one carries: recordings showing several kinds of signal at once come before recordings showing more of a single kind. Offer these before the full list: the recordings list orders by its own sort, so session_ids order never reaches the viewer, and twenty recordings that share an event are otherwise indistinguishable in it. Empty when no recording the viewer can open carries a signal, which is worth saying rather than hiding." }) }).annotate({ "description": "One group of recordings worth opening, and the sentence that justifies it.\n\nDeliberately no rate, no ratio and no person count: a precise number next to an event name is\nan effect size, and the experiment's results publish those for everything it measures, computed\nover a different window and a different unit. The only number here is how many recordings the\ncard can actually show.", "identifier": "ExperimentWatchCard" })
