export const RunningTimeCalculationInput = Schema.Struct({ "metric_type": Schema.suspend((): Schema.Codec<MetricTypeEnum> => MetricTypeEnum).annotate({ "description": "Metric type to size for. 'funnel' for conversion rates, 'mean_count' for event counts per user, 'mean_sum_or_avg' for summed property values per user, 'ratio' and 'retention' for ratio-style metrics (both require baseline_stats or an explicit variance).\n\n* `funnel` - funnel\n* `mean_count` - mean_count\n* `mean_sum_or_avg` - mean_sum_or_avg\n* `ratio` - ratio\n* `retention` - retention" }), "minimum_detectable_effect": Schema.Number.annotate({ "description": "Smallest relative change to detect, as a percentage (e.g. 5 means a 5% lift). Must be > 0.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })).check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })), "number_of_variants": Schema.optionalKey(Schema.Number.annotate({ "description": "Total number of variants including control (default 2, at most 100).", "default": 2 }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(2).annotate({ "expected": "a value greater than or equal to 2" })).check(Schema.isLessThanOrEqualTo(100).annotate({ "expected": "a value less than or equal to 100" }))), "exposure_rate_per_day": Schema.optionalKey(Schema.Union([Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })), Schema.Null]).annotate({ "description": "Expected exposures per day. When provided, the response includes the recommended running time.", "format": "double" })), "baseline_value": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Baseline metric value: conversion rate as a fraction 0-1 (funnel), average per user (mean), or the ratio (ratio/retention). Provide this or baseline_stats.", "format": "double" })), "variance": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Pre-computed variance per user. Provide this or baseline_stats when metric_type is ratio/retention and baseline_value is given directly. When given, it replaces the variance the calculator derives for any metric type, including p(1-p) for funnels.", "format": "double" })), "baseline_stats": Schema.optionalKey(Schema.Union([RunningTimeBaselineStats, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Raw control-group statistics. When provided, the server derives baseline_value and variance." })) }).annotate({ "description": "Inputs for estimating the recommended sample size and running time of an experiment.", "identifier": "RunningTimeCalculationInput" })
