export const BulkDeleteFilters = Schema.Struct({ "active": Schema.optionalKey(Schema.suspend((): Schema.Codec<ActiveEnum> => ActiveEnum).annotate({ "description": "'true' and 'false' filter on serving state, the flag's `active` column. 'STALE' returns enabled flags only, so a disabled flag is never STALE. An enabled flag matches when its last recorded `$feature_flag_called` event is more than 30 days old. With no recorded event, it matches when it is at least 30 days old and either stores `filters` as `{}` or serves one result to everyone through a release condition at 100% with no property filters. A flag with no recorded event and an empty `groups` list does not match, even when its `status` reads STALE. The reverse also happens: a multivariate flag matches when a variant is at 100% under a release condition at 100% with no property filters, or when that condition names a variant. Its `status` can still read ACTIVE, because an earlier variant in the list or an earlier targeted condition can serve a different result. In a flag of either type that mixes person and group aggregation, the filter also counts a group-aggregated condition at 100% with no property filters, which `status` does not. An SDK that sends no `$feature_flag_called` event leaves no record, so a STALE flag can still be in use.\n\n* `true` - true\n* `false` - false\n* `STALE` - STALE" })), "created_by_id": Schema.optionalKey(Schema.Number.annotate({ "description": "Filter to flags created by a specific user ID." }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "search": Schema.optionalKey(Schema.String.annotate({ "description": "Search by feature flag key or name (case-insensitive). Spaces, underscores, and hyphens count as the same separator." })), "type": Schema.optionalKey(Schema.suspend((): Schema.Codec<BulkDeleteFiltersTypeEnum> => BulkDeleteFiltersTypeEnum).annotate({ "description": "Filter by flag type.\n\n* `boolean` - boolean\n* `multivariant` - multivariant\n* `experiment` - experiment\n* `remote_config` - remote_config" })), "evaluation_runtime": Schema.optionalKey(Schema.suspend((): Schema.Codec<EvaluationRuntimeEnum> => EvaluationRuntimeEnum).annotate({ "description": "Filter by evaluation runtime.\n\n* `server` - Server\n* `client` - Client\n* `all` - All" })), "excluded_properties": Schema.optionalKey(Schema.String.annotate({ "description": "JSON-encoded property filter to exclude. Same shape as the list endpoint." })), "tags": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Tag names to filter by. Flags carrying at least one of these tags match." })), "excluded_tags": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Tag names to exclude. Flags carrying any of these tags are filtered out." })), "has_evaluation_contexts": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, only matches flags with at least one evaluation context." })), "archived": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Filter by archived state. When omitted, archived flags are excluded." })) }).annotate({ "description": "Allowed filter keys for bulk_delete — same shape as the list endpoint's query params.", "identifier": "BulkDeleteFilters" })
