export const InsightDataCheck = Schema.Struct({ "key": Schema.suspend((): Schema.Codec<InsightDataCheckKeyEnum> => InsightDataCheckKeyEnum).annotate({ "description": "Which check this is.\n\n* `internal_users` - Internal and test users\n* `local_development` - Local development events\n* `bot_traffic` - Bot and crawler traffic\n* `duplicate_events` - Events sent twice" }), "level": Schema.suspend((): Schema.Codec<InsightDataCheckLevelEnum> => InsightDataCheckLevelEnum).annotate({ "description": "`passed` when the check found nothing worth acting on, `warning` for a small share of the events, `problem` for a fifth of the events or more, and `skipped` when the check could not run. The local development check is never a `problem`, because some apps serve real users from a local host.\n\n* `passed` - Passed\n* `warning` - Warning\n* `problem` - Problem\n* `skipped` - Not checked" }), "skip_reason": Schema.Union([InsightDataCheckSkipReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why the check did not run. Null unless `level` is `skipped`.\n\n* `too_many_events` - The days checked hold too many events to count\n* `read_limit` - The check would read more data than it is allowed\n* `time_limit` - The check took longer than it is allowed\n* `memory_limit` - The check needed more memory than it is allowed\n* `too_few_sampled_events` - The sample has too few events to give a share\n* `filtered_by_traffic_type` - The insight already filters on traffic type\n* `hidden_property` - A property the check reads is hidden from you\n* `invalid_filter` - The project's internal and test users filter cannot run\n* `on_request` - The check would read a lot of data, so it runs only on request" }), "method": Schema.Union([InsightDataCheckMethodEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "`counted` when the check counted every event on the days checked, `sampled` when it read a sample. Null when the check did not run.\n\n* `counted` - Counted every event on the days checked\n* `sampled` - Checked a sample of the events on the days checked" }), "events": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "How many events on the days checked the check found. Null when the check did not run." }), "share": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "`events` as a share of the events checked, from 0 to 1. Null when the check did not run, or when the sample is too small to give a share.", "format": "double" }), "scaled": Schema.Boolean.annotate({ "description": "True when `events` is an estimate scaled up from a sample, rather than a count of every event." }), "action": Schema.Union([InsightDataCheckActionEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The change that fixes it. `filter_internal_users`: set `filterTestAccounts` to true on the insight's query. `open_filter_settings`: change the project's internal and test users filter, for example by adding `filter_to_add`. Null when there is no single change.\n\n* `filter_internal_users` - Turn on the internal and test users filter for the insight\n* `open_filter_settings` - Change the project's internal and test users filter" }), "top_events": Schema.Array(Schema.String).annotate({ "description": "The event names the check found most often, most affected first." }), "top_hosts": Schema.Array(Schema.String).annotate({ "description": "For the local development check, the local hosts whose events the project's internal and test users filter keeps, most affected first." }), "distinct_hosts": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "For the local development check, how many local hosts sent the events in `events`. Null for the other checks and when the check did not run." }), "top_bots": Schema.Array(Schema.String).annotate({ "description": "For the bot traffic check, the bots and crawlers found most often, most affected first." }), "distinct_bots": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "For the bot traffic check, how many named bots and crawlers sent the sampled events. Null for the other checks and when the check did not run." }), "removed_by_filter": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "For the internal users check, the part of `events` that the project's internal and test users filter removes. It is 0 when the insight already applies the filter. Null for the other checks and when the check did not run." }), "missed_by_filter": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "For the internal users check, the part of `events` from team emails that the project's internal and test users filter keeps. Null for the other checks and when the check did not run." }), "top_emails": Schema.Array(Schema.String).annotate({ "description": "For the internal users check, the team emails whose events the project's internal and test users filter keeps, most affected first. Only emails the caller may see as the team's are matched. Empty for a token without the `person:read` scope." }), "distinct_emails": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "For the internal users check, how many team emails sent events that the project's internal and test users filter keeps. Null for the other checks and when the check did not run." }), "filter_to_add": Schema.Union([InsightDataCheckFilter, Schema.Null], { mode: "oneOf" }).annotate({ "description": "A rule for the project's internal and test users filter that removes what the check found: the local hosts or team emails it found, up to 50 values, or bot and AI agent traffic. Null when the check found none, and for the internal users check for a token without the `person:read` scope." }) }).annotate({ "identifier": "InsightDataCheck" })
