export const LogsAnomalyScanBucket = Schema.Struct({ "time": Schema.String.annotate({ "description": "Start of the 5 minute bucket (UTC).", "format": "date-time" }), "observed": Schema.Number.annotate({ "description": "Log records observed in this bucket.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "expected": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Expected count from the learned baseline. Null when the bucket was not scored.", "format": "double" }), "lower": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Lower edge of the expected band. Observed below this is a drop or silence candidate.", "format": "double" }), "upper": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Upper edge of the expected band. Observed above this is a spike candidate.", "format": "double" }), "stage": Schema.Union([LogsAnomalyBaselineStageEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How much history backed the baseline for this bucket. Wider bands and lower confidence in cold_start; mature means a full seasonal baseline. Null when the bucket was gated out (for example, traffic below the detection floor).\n\n* `insufficient` - insufficient\n* `cold_start` - cold_start\n* `developing` - developing\n* `mature` - mature" }), "verdict": Schema.Union([LogsAnomalyVerdictEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Anomaly verdict for this bucket, or null when the observed count sat inside the band.\n\n* `spike` - spike\n* `drop` - drop\n* `silence` - silence" }) }).annotate({ "identifier": "LogsAnomalyScanBucket" })
export type LogsAnomalyScanIssue = { readonly "direction": LogsAnomalyScanIssueDirectionEnum, readonly "severity": string | null, readonly "kind": LogsAnomalyVerdictEnum, readonly "state": LogsAnomalyScanIssueStateEnum, readonly "opened_at": string, readonly "last_anomalous_at": string, readonly "resolved_at": string | null, readonly "anomalous_bucket_times": ReadonlyArray<string> }
export const LogsAnomalyScanIssue = Schema.Struct({ "direction": Schema.suspend((): Schema.Codec<LogsAnomalyScanIssueDirectionEnum> => LogsAnomalyScanIssueDirectionEnum).annotate({ "description": "up covers spikes; down covers drops and silences (which share one issue per service).\n\n* `up` - up\n* `down` - down" }), "severity": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Severity of the spiking series. Null for down issues, which are tracked per service." }), "kind": Schema.suspend((): Schema.Codec<LogsAnomalyVerdictEnum> => LogsAnomalyVerdictEnum).annotate({ "description": "Most severe verdict the issue reached. A drop that deepens into silence escalates in place.\n\n* `spike` - spike\n* `drop` - drop\n* `silence` - silence" }), "state": Schema.suspend((): Schema.Codec<LogsAnomalyScanIssueStateEnum> => LogsAnomalyScanIssueStateEnum).annotate({ "description": "Lifecycle state at the end of the evaluation window.\n\n* `pending` - pending\n* `active` - active\n* `resolved` - resolved" }), "opened_at": Schema.String.annotate({ "description": "Bucket where the issue first opened.", "format": "date-time" }), "last_anomalous_at": Schema.String.annotate({ "description": "Most recent anomalous bucket attributed to this issue.", "format": "date-time" }), "resolved_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Bucket where the issue resolved, or null if it was still open at the end of the window.", "format": "date-time" }), "anomalous_bucket_times": Schema.Array(Schema.String.annotate({ "format": "date-time" })).annotate({ "description": "Every anomalous bucket attributed to this issue, oldest first." }) }).annotate({ "identifier": "LogsAnomalyScanIssue" })
export type LogsSeriesBandsRequest = { readonly "serviceName": string, readonly "dateRange"?: _SeriesBandsDateRange, readonly "intervalMinutes"?: IntervalMinutesEnum | NullEnum }
export const LogsSeriesBandsRequest = Schema.Struct({ "serviceName": Schema.String.annotate({ "description": "Service whose per-series volume to chart (the log record's service_name)." }), "dateRange": Schema.optionalKey(Schema.suspend((): Schema.Codec<_SeriesBandsDateRange> => _SeriesBandsDateRange).annotate({ "description": "Window to chart. Defaults to the last 7 days. It may span at most 7 days and start at most 35 days ago, past which the volume rollup no longer reaches." })), "intervalMinutes": Schema.optionalKey(Schema.Union([IntervalMinutesEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Display grain in minutes for buckets and bands. One of 5, 15, 30, 60. The window may hold at most 500 buckets per series at the chosen grain, so a finer grain needs a shorter window. Omit it to let the window pick its grain, the coarsest that still cuts it into about 168 buckets. A series too sparse to read at this grain is returned at a coarser one; see each series' interval_minutes.\n\n* `5` - 5\n* `15` - 15\n* `30` - 30\n* `60` - 60" })) }).annotate({ "identifier": "LogsSeriesBandsRequest" })
