export const LogsSeriesBandBucket = Schema.Struct({ "time": Schema.String.annotate({ "description": "Start of the display bucket (UTC).", "format": "date-time" }), "observed": Schema.Number.annotate({ "description": "Log count observed in this bucket." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "lower": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Lower edge of the calibrated count range targeting 99% marginal bucket coverage under stable traffic. Null without four complete preceding weeks.", "format": "double" }), "upper": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Upper edge of the calibrated count range targeting 99% marginal bucket coverage under stable traffic. Null without four complete preceding weeks.", "format": "double" }), "verdict": Schema.Union([LogsSeriesBandVerdictEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Where the observed count sits against the band: above when it exceeds upper, below when it falls under lower. Null while it sits inside the band, or while the band is not ready. An out-of-range bucket is not a confirmed incident or an alert.\n\n* `above` - Above the band\n* `below` - Below the band" }) }).annotate({ "identifier": "LogsSeriesBandBucket" })
