export const ReviewProgress = Schema.Struct({ "review_stage": Schema.suspend((): Schema.Codec<ReviewStageEnum> => ReviewStageEnum).annotate({ "description": "How far the in-flight review turn has come: fetching the diff, chunking, picking each chunk's perspectives, reviewing chunks, merging overlapping findings, validating them, or finalizing (building and publishing the review). A single-agent Standard turn reports its own `single_agent_*` stages instead: preparing, reviewing (main and lens sessions), and finalizing (merging, capping, and publishing the findings).\n\n* `fetching` - fetching\n* `chunking` - chunking\n* `selecting` - selecting\n* `reviewing` - reviewing\n* `deduplicating` - deduplicating\n* `validating` - validating\n* `finalizing` - finalizing\n* `single_agent_preparing` - single_agent_preparing\n* `single_agent_reviewing` - single_agent_reviewing\n* `single_agent_finalizing` - single_agent_finalizing" }), "done": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Work units finished within the stage; null when the stage has no counter." }), "total": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Work units the stage expects in total; null when unknown." }), "review_mode": Schema.Union([ReviewTriggerReviewModeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "What the in-flight turn runs: 'full' (Deep) or 'flash' (Standard). The row's `review_mode` describes the last completed turn, which can differ. Null until the turn records its mode, shortly before its review sessions start.\n\n* `full` - Deep\n* `flash` - Standard" }) }).annotate({ "identifier": "ReviewProgress" })
