export const ReviewFinding = Schema.Struct({ "title": Schema.String.annotate({ "description": "One-line summary of the finding." }), "file": Schema.String.annotate({ "description": "Repository-relative path of the affected file." }), "lines": Schema.Array(ReviewFindingLineRange).annotate({ "description": "Affected line ranges within the file." }), "body": Schema.String.annotate({ "description": "Description of the problem." }), "suggestion": Schema.String.annotate({ "description": "The specific fix or improvement the reviewer proposes." }), "effective_priority": Schema.suspend((): Schema.Codec<ReviewIssuePriorityEnum> => ReviewIssuePriorityEnum).annotate({ "description": "The priority that gates publishing: the validator's override when set, else the reviewer's.\n\n* `must_fix` - must_fix\n* `should_fix` - should_fix\n* `consider` - consider" }), "reviewer_priority": Schema.suspend((): Schema.Codec<ReviewIssuePriorityEnum> => ReviewIssuePriorityEnum).annotate({ "description": "The reviewer's original priority, before any validator override.\n\n* `must_fix` - must_fix\n* `should_fix` - should_fix\n* `consider` - consider" }), "source_perspective": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The review skill that produced the finding (perspective or blind-spot sweep)." }), "validator_category": Schema.Union([ValidatorCategoryEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The validator's category for the finding; null when it didn't set one.\n\n* `bug` - bug\n* `security` - security\n* `performance` - performance\n* `code_quality` - code_quality\n* `best_practice` - best_practice\n* `documentation` - documentation\n* `testing` - testing\n* `accessibility` - accessibility\n* `compatibility` - compatibility" }), "validator_note": Schema.String.annotate({ "description": "The validator's argumentation for keeping or dismissing the finding." }) }).annotate({ "identifier": "ReviewFinding" })
