export const ReviewDroppedFinding = Schema.Struct({ "title": Schema.String.annotate({ "description": "One-line summary of the finding." }), "file": Schema.String.annotate({ "description": "Repository-relative path of the affected file." }), "lines": Schema.Array(ReviewFindingLineRange).annotate({ "description": "Affected line ranges within the file." }), "body": Schema.String.annotate({ "description": "Description of the problem." }), "suggestion": Schema.String.annotate({ "description": "The specific fix the reviewer proposes. Usually empty: a single-agent finding ends its body with the fix direction instead." }), "priority": Schema.suspend((): Schema.Codec<ReviewDroppedFindingPriorityEnum> => ReviewDroppedFindingPriorityEnum).annotate({ "description": "The reviewer's priority for the finding.\n\n* `must_fix` - Must fix\n* `should_fix` - Should fix\n* `consider` - Consider" }), "source_perspective": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The session that raised the finding: the main review or a lens." }), "disposition": Schema.suspend((): Schema.Codec<ReviewDropDispositionEnum> => ReviewDropDispositionEnum).annotate({ "description": "Why the turn did not post the finding. `old_code`: a follow-up turn's finding on code that did not change since the last reviewed head. An automatic follow-up (run 2 and later) drops P2 and P3 findings this way, a requested review drops only P3, and a first review drops none. `dedup_prior`: repeats an earlier turn's finding. `dedup_comment`: repeats a PR comment. `dedup_anchor`: repeats a main-review finding at the same spot. `dedup_sibling`: repeats another finding from the same session or lens. `cap`: ranked below the per-review finding limit.\n\n* `old_code` - On unchanged code\n* `dedup_prior` - Repeat of an earlier review\n* `dedup_comment` - Already in a PR comment\n* `dedup_anchor` - Same spot as another finding\n* `dedup_sibling` - Repeat of a finding\n* `cap` - Over the limit\n* `budget` - Over the pull request limit" }), "duplicate_of": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "For a dedup drop, what it repeats: an issue key, or `comment:<id>` for a PR comment. Null for other dispositions." }), "comment_url": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Link to the PR comment the finding repeats, when `duplicate_of` names one and the PR URL is known. Null otherwise." }), "rank": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "For a `cap` drop, the finding's 1-based position in the turn's ranked findings. Null otherwise." }) }).annotate({ "identifier": "ReviewDroppedFinding" })
