export type ReviewPRStatusRequestOutcome = { readonly "status": ReviewRequestOutcomeStatusEnum, readonly "reason": string | null, readonly "review_id": string | null, readonly "run_index": number | null }
export const ReviewPRStatusRequestOutcome = Schema.Struct({ "status": Schema.suspend((): Schema.Codec<ReviewRequestOutcomeStatusEnum> => ReviewRequestOutcomeStatusEnum).annotate({ "description": "How the request ended: 'pending' while a run for it is queued or running, 'completed' when a turn of the requested mode or deeper finished after `requested_at` and either started after it or reviewed the given `head_sha` (Deep covers Standard), 'skipped' when the run ended without doing the work, 'failed' when the run died or no run answered the request, 'unknown' when the run state could not be read (retry later).\n\n* `pending` - Pending\n* `completed` - Completed\n* `skipped` - Skipped\n* `failed` - Failed\n* `unknown` - Unknown" }), "reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why it was skipped or failed: 'flash_after_full' (Standard dropped after a Deep review), 'review_failed', 'stopped' (Resolve died partway), 'no_matching_run' (nothing ran for the request and nothing is queued, for example when the queue replaced it), or a Resolve skip reason such as 'pr_not_open', 'resolution_not_opted_in', 'no_unresolved_threads', 'pr_in_merge_queue'. Null otherwise." }), "review_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The review to read with `review-hog-reviews-get`; null before the PR has one.", "format": "uuid" }), "run_index": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "The review turn that answered or failed the request, for `review-hog-reviews-get`. Null for 'resolve_only' and while pending." }) }).annotate({ "identifier": "ReviewPRStatusRequestOutcome" })
