export const ReviewTriggerRequest = Schema.Struct({ "pr_url": Schema.String.annotate({ "description": "GitHub pull request URL to review, e.g. 'https://github.com/PostHog/posthog.com/pull/123'. The repository must be accessible to the project's GitHub App installation." }), "run_mode": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReviewTriggerRequestRunModeEnum> => ReviewTriggerRequestRunModeEnum).annotate({ "description": "What to run on the pull request. 'review' (default) reviews it and, when the pull request owner's resolve_comments setting is on, chains the resolution stage; 'review_only' reviews without resolving regardless of that setting; 'resolve_only' skips the review and only runs the resolution stage on the PR's existing unresolved review threads, which needs the owner's opt-in; 'flash' runs a Standard review: a lower-cost model for the review passes and validation, never resolves comments, and is refused once the PR has a published Deep review. The owner is the PR's author, or the Inbox reviewer of a pull request the PostHog app opened.\n\n* `review` - Review\n* `review_only` - Review only\n* `resolve_only` - Resolve only\n* `flash` - Standard", "default": "review" })) }).annotate({ "identifier": "ReviewTriggerRequest" })
