export const ReviewTriggerResponse = Schema.Struct({ "workflow_id": Schema.String.annotate({ "description": "Temporal workflow id for the started review run; empty when no run was started." }), "status": Schema.String.annotate({ "description": "Run lifecycle marker: 'started' when the review was queued, 'already_reviewed' when the pull request's current commit already has a published review in the requested mode, 'joined_running_review' when a review was already running and the request was queued on that pull request's run, to start after the running turn. A requested Deep review waits for an active Standard review." }), "repository": Schema.String.annotate({ "description": "The pull request's repository as 'owner/repo'." }), "pr_number": Schema.Number.annotate({ "description": "The pull request number." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "head_sha": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The pull request's head commit when the request was accepted." }), "review_mode": Schema.Union([ReviewTriggerReviewModeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The review this request runs: 'full' (Deep) or 'flash' (Standard). Null for 'resolve_only', which runs no review.\n\n* `full` - Deep\n* `flash` - Standard" }), "report_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Id of the pull request's existing review, for `review-hog-reviews-get`. Null on the pull request's first run, which creates the review later.", "format": "uuid" }), "requested_at": Schema.String.annotate({ "description": "Server time when the request was accepted.", "format": "date-time" }), "resolve_will_run": Schema.Boolean.annotate({ "description": "Whether this request plans to run the resolution stage, which can push fix commits to the pull request. It is the plan at request time: a request queued behind a running turn on the same head can be skipped as already published. `review-hog-reviews-pr-status` reports what actually ran." }), "resolve_skip_reason": Schema.Union([ResolveSkipReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why the resolution stage does not run: 'run_mode_excludes_resolve' ('review_only' and 'flash' never resolve), 'owner_not_opted_in' (the pull request owner has not turned on resolving comments), 'already_reviewed' (no run starts). Null when it runs.\n\n* `run_mode_excludes_resolve` - The run mode never resolves comments\n* `owner_not_opted_in` - The pull request owner has not opted in to resolution\n* `already_reviewed` - No run starts, because the head already has a review in this mode" }) }).annotate({ "identifier": "ReviewTriggerResponse" })
export type ReviewTriggerError = { readonly "error": string, readonly "code"?: ReviewRequestRefusalEnum }
export const ReviewTriggerError = Schema.Struct({ "error": Schema.String.annotate({ "description": "Human-readable explanation of why the trigger was rejected." }), "code": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReviewRequestRefusalEnum> => ReviewRequestRefusalEnum).annotate({ "description": "Why the request was refused, for a client that shows its own reason: 'flash_after_full' (the PR already has a published Deep review), 'resolution_not_opted_in' (the PR owner has not turned on resolving comments). Absent for other errors.\n\n* `flash_after_full` - Standard after a published Deep review\n* `resolution_not_opted_in` - The pull request owner has not opted in to resolution" })) }).annotate({ "identifier": "ReviewTriggerError" })
