export type SignalReportStateRequest = { readonly "state": SignalReportStateEnum, readonly "dismissal_reason"?: DismissalReasonEnum, readonly "dismissal_note"?: string, readonly "corrected_repository"?: string, readonly "snooze_for"?: number }
export const SignalReportStateRequest = Schema.Struct({ "state": Schema.suspend((): Schema.Codec<SignalReportStateEnum> => SignalReportStateEnum).annotate({ "description": "Target state for the report. Use 'suppressed' to dismiss the report from the inbox, 'potential' to snooze it or restore it from the archive, or 'resolved' when the report is finished. Resolving is allowed from ready, pending_input, failed, closed, or monitoring, or from a suppressed report that previously held one of those statuses or resolved. Resolving an already resolved report succeeds. Other statuses return 409 (skipped in bulk). Dismissing or resolving closes the report's open implementation PR, if it has one. Use 'monitoring' when implementation is complete and outcome verification is pending. Entry requires the organization rollout and snapshots this report's pending or active, unexpired checks. Without applicable checks the report resolves directly. Manual completion records caller attribution, stops remaining follow-up checks, and does not claim automatic verification or an evidence amendment. Use 'ready' to reopen a report in monitoring or closed. It returns to ready with its research, pull requests, and follow-up checks kept, and its Monitoring period ends. Completing implementation again starts a new period. Reopening is refused for other statuses and for refunded reports.\n\n* `suppressed` - suppressed\n* `potential` - potential\n* `resolved` - resolved\n* `monitoring` - monitoring\n* `ready` - ready" }), "dismissal_reason": Schema.optionalKey(Schema.suspend((): Schema.Codec<DismissalReasonEnum> => DismissalReasonEnum).annotate({ "description": "Optional canonical reason code recorded with the transition. Must be one of: already_fixed, report_unclear, analysis_wrong, wrong_assignee, wrong_repo, wontfix_intentional, wontfix_irrelevant, fixed_outside_posthog, verified_manually, no_action_needed, pr_merged, other — these match the inbox UI so the rationale renders as a labelled chip rather than a raw code. When the work this report asked for is done, the honest transition is state='resolved' with 'fixed_outside_posthog' (the fix landed without a pull request), 'pr_merged' (a pull request with the fix was merged but did not resolve the report on its own), or 'already_fixed' (it was fixed before the report was filed). Use 'no_action_needed' with state='resolved' when the report was useful but needs no implementation. A report that failed in processing resolves too, so a fix that landed is recorded as a fix rather than as a dismissal. These three codes claim the issue is gone, so a later signal about the same issue starts a fresh report linked to this one. Fixed reason codes require state='suppressed' or state='resolved', not 'potential'. The dismissal codes (report_unclear, analysis_wrong, wrong_assignee, wontfix_*) go with state='suppressed' and absorb later signals silently. 'wrong_assignee' is accepted from older clients, but a report sent to the wrong person still holds work: remove the person from the report's reviewers with a removal_reason instead of suppressing it. 'wrong_repo' when the agent picked the wrong repository for this report, ideally with corrected_repository naming the right one. The report stays suppressed, but a later matching signal starts a fresh linked report with a new repository selection informed by the project's correction feedback, even when no corrected_repository was supplied. Use 'verified_manually' with state='resolved' to stop Monitoring after manual verification. It requires Monitoring to be enabled and a report with a Monitoring period, and records no automatic verification result or evidence amendment. Use 'other' together with a dismissal_note for anything that doesn't fit a code.\n\n* `already_fixed` - Already fixed\n* `report_unclear` - Report is unclear to me\n* `analysis_wrong` - Agent's analysis is wrong\n* `wrong_assignee` - Wrong assignee\n* `wrong_repo` - Agent picked the wrong repository\n* `wontfix_intentional` - Won't fix - intentional behavior\n* `wontfix_irrelevant` - Not relevant to this project\n* `fixed_outside_posthog` - Fixed outside PostHog\n* `verified_manually` - Verified manually\n* `no_action_needed` - No action needed\n* `pr_merged` - PR was merged\n* `other` - Something else…" })), "dismissal_note": Schema.optionalKey(Schema.String.annotate({ "description": "Optional free-form note explaining the dismissal. Capped at 4000 characters." }).check(Schema.isMaxCodePoints(4000).annotate({ "expected": "a string with at most 4000 code points" }))), "corrected_repository": Schema.optionalKey(Schema.String.annotate({ "description": "Optional, only allowed with dismissal_reason='wrong_repo'. The repository this report should have targeted, in 'owner/repo' format (case-insensitive). It is recorded with the dismissal and fed into future repository selection for this project. When the repository is connected to the project, it also becomes the report's corrected repo selection, so restoring the report re-researches against it." }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })).check(Schema.isMaxCodePoints(140).annotate({ "expected": "a string with at most 140 code points" }))), "snooze_for": Schema.optionalKey(Schema.Number.annotate({ "description": "Optional, only honored when state is 'potential'. Number of additional signals the report must accumulate before it is re-promoted into the pipeline — effectively snoozing it until then. Omit to let the report re-enter the pipeline on the next matching signal." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })).check(Schema.isLessThanOrEqualTo(100000).annotate({ "expected": "a value less than or equal to 100000" }))) }).annotate({ "identifier": "SignalReportStateRequest" })
export type SignalReportBulkStateRequest = { readonly "state": SignalReportStateEnum, readonly "dismissal_reason"?: DismissalReasonEnum, readonly "dismissal_note"?: string, readonly "corrected_repository"?: string, readonly "snooze_for"?: number, readonly "ids": ReadonlyArray<string> }
