export const SignalReportArtefactLogCreate = Schema.Struct({ "expected_reviewers": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReviewerState> => ReviewerState).annotate({ "description": "Report reviewer_assignment.state read before selection began. Required when reviewer corrections are enabled." })), "reviewer_outcome": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReviewerSelectionOutcomeEnum> => ReviewerSelectionOutcomeEnum).annotate({ "description": "A successful selection, a deliberate empty result, or an unavailable lookup. Defaults to selected when omitted.\n\n* `selected` - Selected\n* `no_suitable_owner` - No suitable owner\n* `lookup_failed` - Lookup failed" })), "reviewer_retry_reason": Schema.optionalKey(Schema.String.annotate({ "description": "Reason the reviewer lookup failed." }).check(Schema.isMaxCodePoints(500).annotate({ "expected": "a string with at most 500 code points" }))), "claim_id": Schema.optionalKey(Schema.String.annotate({ "description": "Active claim to attribute this work to. Must belong to the caller and report.", "format": "uuid" })), "artefact_type": Schema.String.annotate({ "description": "The artefact type. One of: actionability_judgment, channel_assignment, code_reference, commit, dismissal, note, priority_judgment, related_to, repo_selection, safety_judgment, signal_finding, source_suggestion, suggested_reviewers. Log types accumulate; status types (safety_judgment, actionability_judgment, priority_judgment, repo_selection, suggested_reviewers, channel_assignment, source_suggestion) are latest-wins — appending a new version supersedes the previous one as the report's canonical status." }), "content": Schema.Json.annotate({ "expected": "JSON value", "description": "The artefact payload as a JSON object or array; shape depends on artefact_type and is validated against its schema." }) }).annotate({ "description": "Body for appending an artefact to a report.\n\nEverything is append-only: log artefacts accumulate, status artefacts supersede the previous\nversion (latest-wins). The `content` shape depends on `artefact_type` and is validated\nagainst the type's schema (see `products/signals/backend/artefact_schemas.py`).", "identifier": "SignalReportArtefactLogCreate" })
export type MonitoringCheckTiming = { readonly "state": MonitoringCheckTimingStateEnum, readonly "final_verification_state"?: FinalVerificationStateEnum | NullEnum, readonly "started_at": string | null, readonly "ends_at": string | null, readonly "next_measurement_at": string | null }
export const MonitoringCheckTiming = Schema.Struct({ "state": Schema.suspend((): Schema.Codec<MonitoringCheckTimingStateEnum> => MonitoringCheckTimingStateEnum).annotate({ "description": "Monitoring timing state. Final verification phases use paused for compatibility; read final_verification_state for their phase.\n\n* `scheduled` - Scheduled\n* `due` - Due\n* `window_ended` - Window ended\n* `no_interim_measurements` - No interim measurements\n* `waiting` - Waiting for scheduling\n* `paused` - Paused during Monitoring\n* `archived` - Archived\n* `unavailable` - Timing unavailable\n* `expiry_reached` - Expiry reached" }), "final_verification_state": Schema.optionalKey(Schema.Union([FinalVerificationStateEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Final verification phase when state is paused. Null for other timing states. Read the check outcome for its verdict.\n\n* `monitoring` - Monitoring\n* `verifying` - Verifying\n* `assessment_required` - Assessment required\n* `verification_complete` - Verification complete", "readOnly": true })), "started_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Original Monitoring start for this check's report.", "format": "date-time" }), "ends_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "End of this check's soak window, independent of its target reference period and safety expiry.", "format": "date-time" }), "next_measurement_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Stored next interim attempt, only when it falls before the soak deadline and expiry. Null when no interim measurement is scheduled.", "format": "date-time" }) }).annotate({ "identifier": "MonitoringCheckTiming" })
