export const SubmitMonitoringResultResponse = Schema.Struct({ "accepted": Schema.Boolean.annotate({ "description": "True when the result is stored, including an identical retry." }), "result_id": Schema.String.annotate({ "description": "The immutable Monitoring result's identifier.", "format": "uuid" }), "outcome": Schema.suspend((): Schema.Codec<SignalReportCheckOutcomeEnum> => SignalReportCheckOutcomeEnum).annotate({ "description": "The recorded verdict; this does not change the report's status.\n\n* `passed` - Passed\n* `failed` - Failed\n* `errored` - Errored\n* `inconclusive` - Inconclusive" }) }).annotate({ "identifier": "SubmitMonitoringResultResponse" })
export type RecordCheckResultRequest = { readonly "check_id": string, readonly "outcome": SignalReportCheckOutcomeEnum, readonly "reason"?: SignalReportCheckInconclusiveReasonEnum | NullEnum, readonly "explanation": string, readonly "observed_value"?: number | null }
export const RecordCheckResultRequest = Schema.Struct({ "check_id": Schema.String.annotate({ "description": "The check this run was dispatched to answer, as given in the run note.", "format": "uuid" }), "outcome": Schema.suspend((): Schema.Codec<SignalReportCheckOutcomeEnum> => SignalReportCheckOutcomeEnum).annotate({ "description": "`passed` when the evidence meets the check's stated bar and the expectation holds, `failed` when the evidence meets the bar and the expectation does not hold. `inconclusive` when your tools worked but the evidence cannot settle the question; give a `reason`. `errored` only when a tool, query, or model call failed. Reserve `failed` for a conclusion, not a suspicion.\n\n* `passed` - Passed\n* `failed` - Failed\n* `errored` - Errored\n* `inconclusive` - Inconclusive" }), "reason": Schema.optionalKey(Schema.Union([SignalReportCheckInconclusiveReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Required with `inconclusive`, and refused with any other outcome. `awaiting_data`: the data can still arrive (a rollout lag, a soak not complete, too few samples so far). `unmeasurable`: the data the check needs is not captured. `needs_manual_verification`: only a person or another environment can verify it. `no_fix_to_measure`: nothing was changed to fix the claim, so no window after a fix exists. A report resolved without a pull request still has a window that starts when it resolved.\n\n* `awaiting_data` - Awaiting Data\n* `unmeasurable` - Unmeasurable\n* `needs_manual_verification` - Needs Manual Verification\n* `no_fix_to_measure` - No Fix To Measure" })), "explanation": Schema.String.annotate({ "description": "One or two sentences on what you looked at and what it showed. This is what a person reads on the report, so write it for them, with the numbers or entities you checked." }).check(Schema.isMaxCodePoints(1000).annotate({ "expected": "a string with at most 1000 code points" })), "observed_value": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "The number you measured, when the check came down to one. Leave it out otherwise.", "format": "double" })) }).annotate({ "description": "Request body for `scout-check-record-result`: the verdict on one dispatched report check.", "identifier": "RecordCheckResultRequest" })
