export const SignalReportBulkStateResponse = Schema.Struct({ "results": Schema.Array(SignalReportBulkStateResult).annotate({ "description": "One result per requested id, in request order (after de-duplication)." }), "transitioned_count": Schema.Number.annotate({ "description": "Number of reports the call accepted. A report that already had the requested state counts here too, because a repeat dismiss or resolve still records its feedback." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "skipped_count": Schema.Number.annotate({ "description": "Number of reports whose transition was not allowed." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "failed_count": Schema.Number.annotate({ "description": "Number of reports that failed on invalid request data." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "not_found_count": Schema.Number.annotate({ "description": "Number of requested ids not visible to the caller." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "identifier": "SignalReportBulkStateResponse" })
