export const SignalReportBulkClaimResponse = Schema.Struct({ "results": Schema.Array(SignalReportBulkClaimResult).annotate({ "description": "One result per requested id, in request order (after de-duplication)." }), "claimed_count": Schema.Number.annotate({ "description": "Number of reports the caller now holds." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "conflict_count": Schema.Number.annotate({ "description": "Number of reports whose claim was refused." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "not_found_count": Schema.Number.annotate({ "description": "Number of requested ids not visible to the caller." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "identifier": "SignalReportBulkClaimResponse" })
