export const PullRequestCiStatus = Schema.Struct({ "report_id": Schema.String.annotate({ "description": "Report whose implementation pull request this status describes.", "readOnly": true, "format": "uuid" }), "ci_status": Schema.suspend((): Schema.Codec<PullRequestCiStatusEnum> => PullRequestCiStatusEnum).annotate({ "description": "Rollup of the pull request's checks on its head commit: 'passing' (nothing failed), 'failing', 'pending' (checks are still running), or 'none' (the head commit has no checks).\n\n* `passing` - Passing\n* `failing` - Failing\n* `pending` - Pending\n* `none` - No checks", "readOnly": true }) }).annotate({ "description": "The CI rollup of one report's implementation pull request.", "identifier": "PullRequestCiStatus" })
