export const SignalReportSearchHit = Schema.Struct({ "id": Schema.String.annotate({ "description": "The report id. Pass it to inbox-reports-retrieve for the full report.", "format": "uuid" }), "title": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The report title." }), "status": Schema.suspend((): Schema.Codec<SignalReportStatusEnum> => SignalReportStatusEnum).annotate({ "description": "The report status.\n\n* `potential` - Potential\n* `candidate` - Candidate\n* `in_progress` - In Progress\n* `pending_input` - Pending Input\n* `ready` - Ready\n* `monitoring` - Monitoring\n* `resolved` - Resolved\n* `closed` - Closed\n* `failed` - Failed\n* `deleted` - Deleted\n* `suppressed` - Suppressed" }), "priority": Schema.Union([AutonomyPriorityEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The report priority, P0 to P4, or null.\n\n* `P0` - P0\n* `P1` - P1\n* `P2` - P2\n* `P3` - P3\n* `P4` - P4" }), "updated_at": Schema.String.annotate({ "description": "When the report last changed.", "format": "date-time" }), "summary_snippet": Schema.String.annotate({ "description": "A short excerpt of the summary, around the first query word it holds, or the summary's opening when it holds none." }), "dismissal_reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The reason code from the latest dismissal of the report, or null." }), "dismissal_note": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The note a person wrote with the latest dismissal, or null." }), "match_kinds": Schema.Array(ReportMatchKindEnum).annotate({ "description": "How the report matched: `keyword`, `semantic`, or both." }), "score": Schema.Number.annotate({ "description": "The reciprocal rank fusion score. Higher is a better match. Compare it only within one response.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })) }).annotate({ "identifier": "SignalReportSearchHit" })
