export const ReviewerExclusion = Schema.Struct({ "id": Schema.String.annotate({ "description": "Identifier of the instruction.", "readOnly": true, "format": "uuid" }), "repository": Schema.String.annotate({ "description": "Repository in `owner/name` form that the instruction covers. Empty covers every one.", "readOnly": true }), "path_prefix": Schema.String.annotate({ "description": "Path inside the repository that the instruction covers. Empty covers the repository.", "readOnly": true }), "instruction": Schema.String.annotate({ "description": "Why the member stays off this area.", "readOnly": true }), "status": Schema.suspend((): Schema.Codec<SignalReviewerExclusionStatusEnum> => SignalReviewerExclusionStatusEnum).annotate({ "description": "`active` instructions apply to automatic reviewer selection. `revoked` instructions do not.\n\n* `active` - Active\n* `revoked` - Revoked", "readOnly": true }), "revision": Schema.Number.annotate({ "description": "Increases by one at each change.", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "created_at": Schema.String.annotate({ "description": "When the member saved the instruction.", "readOnly": true, "format": "date-time" }), "updated_at": Schema.String.annotate({ "description": "When the instruction last changed.", "readOnly": true, "format": "date-time" }) }).annotate({ "identifier": "ReviewerExclusion" })
