export const LighthouseAuditResponse = Schema.Struct({ "requested_url": Schema.String.annotate({ "description": "The url that was audited." }), "final_url": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Where the browser ended up after redirects." }), "form_factor": Schema.String.annotate({ "description": "The device profile the audit emulated." }), "lighthouse_version": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The Lighthouse version that produced this report. Audit ids move between major versions, so cite it when an expected field came back empty." }), "performance_score": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Lighthouse performance score out of 100 for this run." }), "metrics": Schema.Record(Schema.String, Schema.Number.annotate({ "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" }))).annotate({ "description": "Lab metrics from this run: `lcp_ms`, `fcp_ms`, `cls`, `tbt_ms`, `speed_index_ms`, `tti_ms`. One throttled cold load, not a p75 over real users — use it to explain a field finding, never to replace one." }), "lcp_element": Schema.Union([LcpElement, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The element the browser chose as the LCP, or null when Lighthouse could not name one." }), "lcp_phases": Schema.Array(LcpPhase).annotate({ "description": "Where the LCP time went, phase by phase. Empty when the report omits the breakdown." }), "lcp_checks_failed": Schema.Array(AuditOpportunity).annotate({ "description": "LCP-specific checks this page failed, such as an unprioritized or lazy-loaded hero image." }), "opportunities": Schema.Array(AuditOpportunity).annotate({ "description": "Ranked savings estimates across the whole page, largest first." }), "audits_remaining": Schema.Number.annotate({ "description": "How many audits this run may still spend. Each run gets 5." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "description": "The audit, reduced to what a web vitals finding cites.\n\nThe full Lighthouse report runs to a few hundred KB of detail no finding ever quotes, so the\nresponse carries the metrics, the LCP element and its phase breakdown, and the ranked\nopportunities, and drops the rest.", "identifier": "LighthouseAuditResponse" })
