export const StamphogPullRequestRouting = Schema.Struct({ "status": Schema.suspend((): Schema.Codec<RoutingStatusEnum> => RoutingStatusEnum).annotate({ "description": "The phase of the latest routing record: 'waiting' (fallback mode, the head waits for stamphog's verdict or the safety net), 'routing' (a task holds the claim and requested nobody yet), 'requested' (the review requests went out, the routing comment is not finished) or 'done'.\n\n* `waiting` - Waiting for stamphog's verdict\n* `routing` - Routing\n* `requested` - Requested\n* `done` - Done", "readOnly": true }), "mode": Schema.suspend((): Schema.Codec<RoutingModeEnum> => RoutingModeEnum).annotate({ "description": "The repository's routing_mode when the record was written. Compare with the pull request's routing_mode.\n\n* `off` - Off\n* `always` - Always\n* `fallback` - When stamphog does not approve", "readOnly": true }), "scope": Schema.Union([RoutingScopeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "'full', or 'pinned' when a stamphog approval asks only the owners of sensitive and new paths. Null while the record waits.\n\n* `full` - Every owner\n* `pinned` - Pinned owners only", "readOnly": true }), "head_sha": Schema.String.annotate({ "description": "The head commit the record is for. It can be older than the pull request head.", "readOnly": true }), "trigger": Schema.String.annotate({ "description": "What started the record: 'opened', 'ready_for_review', 'verdict:<outcome>', 'external_review', 'approval_retracted' or 'safety_net'.", "readOnly": true }), "claim_expired": Schema.Boolean.annotate({ "description": "True when a 'routing' or 'requested' claim is older than the takeover limit. The task can still be alive, and a later delivery does not always finish an expired 'requested' claim.", "readOnly": true }), "waiting_since": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When the head started to wait for stamphog's verdict. Null unless waiting.", "readOnly": true, "format": "date-time" }), "claimed_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When a task claimed the pull request for this record.", "readOnly": true, "format": "date-time" }), "routed_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When the claim planned its requests. Null until the plan is saved.", "readOnly": true, "format": "date-time" }), "full_routed_head": Schema.String.annotate({ "description": "The head that a full routing of this pull request requested owners for, blank if none. Fallback mode routes in full at most once per pull request.", "readOnly": true }), "pinned_routed_head": Schema.String.annotate({ "description": "The latest approved head whose pinned owners were requested, blank if none.", "readOnly": true }) }).annotate({ "identifier": "StamphogPullRequestRouting" })
