export const StamphogRepoConfigWrite = Schema.Struct({ "provider": Schema.optionalKey(Schema.String.annotate({ "description": "SCM provider this config talks to. Defaults to 'github'. Set on create only, an update ignores it." })), "repository": Schema.String.annotate({ "description": "Repository full name, e.g. 'PostHog/posthog'. Set on create only, an update ignores it." }), "enabled": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether stamphog actively reviews pull requests for this repo." })), "digest_enabled": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether merged PRs on this repo are captured for the daily Slack digest." })), "review_mode": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReviewModeEnum> => ReviewModeEnum).annotate({ "description": "When reviews run: 'label' reviews only pull requests carrying the trigger label (the default), mirroring the Action's opt-in flow; 'all' reviews every pull request.\n\n* `all` - All pull requests\n* `label` - Labeled pull requests" })), "trigger_label": Schema.optionalKey(Schema.String.annotate({ "description": "Pull request label that triggers a review when review_mode is 'label'. Defaults to 'stamphog'." })), "routing_mode": Schema.optionalKey(Schema.suspend((): Schema.Codec<RoutingModeEnum> => RoutingModeEnum).annotate({ "description": "When stamphog requests reviews from the code owners in the repository's owners.yaml: 'off' (the default) never; 'always' when a pull request opens ready for review or is marked ready; 'fallback' only when stamphog does not approve, where an approval requests only the owners of sensitive and new paths.\n\n* `off` - Off\n* `always` - Always\n* `fallback` - When stamphog does not approve" })), "routing_fork_labels": Schema.optionalKey(Schema.Record(Schema.String, Schema.String.check(Schema.isMaxCodePoints(50).annotate({ "expected": "a string with at most 50 code points" }))).annotate({ "description": "On fork pull requests, routing adds the mapped label instead of requesting a review from the team, so an outside author cannot notify it. Keys are owners.yaml team slugs such as 'team-devex', values are GitHub label names. A team with no entry gets a review request as usual. Sending the field replaces the whole map, and an empty object removes every label." })), "review_on_clean_external_review": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether a clean PostHog Review run on a pull request that opened or was marked ready starts a silent stamphog review of that head, whatever review_mode says. A silent review posts only an approval: any other verdict is stored and nothing is written to the pull request. Only for review_mode 'label' in a repository where PostHog Review runs automatic reviews: 'all' refuses it, and setting review_mode to 'all' turns it off. With routing_mode 'fallback', a head waits for that silent review before routing. Defaults to false." })) }).annotate({ "description": "Input shape for creating/updating a repo config.\n\nSeparate from the read serializer because the contract is an output shape: it carries a\nrequired id, which a create request has no way to supply. Same split as visual_review's\ninput serializers.\n\ninstallation_id is deliberately absent: it may only ever be set by the verified\nsync_installation flow, which proves the caller owns the installation before binding it. A\nclient-supplied value on this path is ignored, so a manually created config carries no\ninstallation and simply won't resolve webhooks until synced.", "identifier": "StamphogRepoConfigWrite" })
