export const HighlightMetric = Schema.Struct({ "key": Schema.String.annotate({ "description": "Stable key of the metric: a key metric setting such as signup_event, insight:<short_id>, or experiment:<id>." }), "name": Schema.String.annotate({ "description": "Name of the key metric or of the insight, for example Sign-ups." }), "value": Schema.Number.annotate({ "description": "Value for the last complete period: the last 7 complete days, or the last complete week or month.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "unit": Schema.suspend((): Schema.Codec<HighlightUnitEnum> => HighlightUnitEnum).annotate({ "description": "`events` for a count of events, `people` for unique people, `number` for an insight value.\n\n* `events` - Events\n* `people` - People\n* `number` - Number" }), "change_pct": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Change against the period before, in percent. Null when the period before is 0.", "format": "double" }), "series": Schema.Array(Schema.Number.annotate({ "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" }))).annotate({ "description": "Values oldest first: daily for the last 28 complete days, or one value per week or month." }), "interval": Schema.suspend((): Schema.Codec<CalendarUnitEnum> => CalendarUnitEnum).annotate({ "description": "What one value in `series` covers: a day, a week or a month.\n\n* `day` - Day\n* `week` - Week\n* `month` - Month" }), "url": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Path of the insight the metric comes from. For a key metric, a new trends insight of the same days." }), "value_format": Schema.Union([HighlightValueFormat, Schema.Null], { mode: "oneOf" }).annotate({ "description": "How the insight formats its values. Null for a key metric and for an insight with plain numbers." }), "period_starts": Schema.Array(Schema.String.annotate({ "format": "date" })).annotate({ "description": "The first day of the period each value in `series` covers, in the project's timezone. Same length and order as `series`." }), "reason": Schema.Union([HighlightMetricReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why the pulse suggests the metric: `routine` for an insight the person opens often, `dashboard` for a tile of a dashboard they open often, `key_metric` for a key metric of the project, shown only when the person has no numbers of their own, `popular` for an insight that many people in the project open, `watched` for an insight the person gets an alert or a subscription for, `built` for an insight the person created or edited recently, `experiment` for a running experiment the person created, `agent` for an insight the person's AI agents read on several days, `evaluation` for the pass rate of an evaluation the person created. Null for metrics computed before this field existed.\n\n* `routine` - You open this often\n* `dashboard` - On a dashboard you open often\n* `key_metric` - Project key metric\n* `popular` - Opened often in this project\n* `watched` - You get updates on this\n* `built` - You created or edited this\n* `experiment` - An experiment you run\n* `agent` - Your agents query this\n* `evaluation` - An evaluation you created" }), "dashboard_name": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Name of the dashboard the tile comes from when `reason` is `dashboard`, else null." }), "dashboard_id": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Id of the dashboard the tile comes from, with its filters applied. Pass it when pinning the tile. Null otherwise." }), "opened_days": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "On how many of the last 14 days the person opened the insight, or the dashboard of the tile. Null for a key metric." }), "last_opened": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The last day the person opened the insight, or the dashboard of the tile, in the project's timezone. Null for a key metric.", "format": "date" }), "previous_value": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Value for the period before the last complete one, the base of `change_pct`. Null when unknown.", "format": "double" }), "movers": Schema.Array(HighlightMover).annotate({ "description": "For an insight with several series, the series that changed most last period, biggest change first. Empty otherwise." }), "experiment": Schema.Union([HighlightExperimentResult, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The primary metric result of an experiment. Then `value` is the change of `variant` against the control, in percent, and `series` is empty. Null for other metrics." }) }).annotate({ "identifier": "HighlightMetric" })
