export const Cluster = Schema.Struct({ "id": Schema.String.annotate({ "description": "The cluster id. Pass it as `theme` or `group` to `vision-scanners-observations-list` to read members.", "format": "uuid" }), "scanner_id": Schema.String.annotate({ "description": "The scanner whose observations the cluster groups.", "format": "uuid" }), "scanner_name": Schema.String.annotate({ "description": "The scanner's name." }), "name": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "A short model-written search phrase for a theme. Null for a group, and for a theme too small to be named; `example_summary` stands in." }), "status": Schema.suspend((): Schema.Codec<ClusterStatusEnum> => ClusterStatusEnum).annotate({ "description": "Where the cluster stands, from its members: `emerging` (first member this week), `active`, `fading` (last week under half of the week before) or `dormant` (no member for two weeks).\n\n* `emerging` - Emerging\n* `active` - Active\n* `fading` - Fading\n* `dormant` - Dormant" }), "observation_count": Schema.Number.annotate({ "description": "Readable observations in the window: issue observations, plus routine ones with `include_routine`." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "people_count": Schema.Number.annotate({ "description": "Distinct people among them; a session without an identified person counts as one." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "previous_observation_count": Schema.Number.annotate({ "description": "Members in the same-length window just before `date_from`, to compare the trend against." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "first_seen": Schema.String.annotate({ "description": "When the window's oldest member was observed.", "format": "date-time" }), "last_seen": Schema.String.annotate({ "description": "When the window's newest member was observed.", "format": "date-time" }), "example_observation_ids": Schema.Array(Schema.String.annotate({ "format": "uuid" })).annotate({ "description": "Up to 3 of the window's highest-ranked members, best first." }), "example_summary": Schema.String.annotate({ "description": "One-line summary of the best example; the readable label for a group, which has no name." }), "variants": Schema.Array(VariantCount).annotate({ "description": "The window's members split by experiment variant, largest first. Empty unless `by_variant` is set. Compare each variant's share of the group with its share of the scanner's sessions, since variants are sampled at different rates." }) }).annotate({ "identifier": "Cluster" })
