export const InlineScanRequest = Schema.Struct({ "built_in": Schema.optionalKey(Schema.suspend((): Schema.Codec<BuiltInScanKeyEnum> => BuiltInScanKeyEnum).annotate({ "description": "Run a scan PostHog defines instead of your own prompt. `summarize_recording` is the AI summary the Summarize button in the replay player runs, so its results are shared with that button. Leave out `prompt`, `scanner_type` and `scanner_config` when this is set.\n\n* `summarize_recording` - Summarize recording" })), "prompt": Schema.optionalKey(Schema.String.annotate({ "description": "What to look for in these sessions, in plain language. The same instruction a saved scanner carries. Required unless `built_in` is set." }).check(Schema.isMaxCodePoints(20000).annotate({ "expected": "a string with at most 20000 code points" }))), "scanner_type": Schema.optionalKey(Schema.suspend((): Schema.Codec<ScannerTypeEnum> => ScannerTypeEnum).annotate({ "description": "What the scan produces. Defaults to monitor, an open-ended observation against the prompt. Use `summarizer` for a summary in your own words; use `built_in: summarize_recording` for the Summarize button's summary. An inline scan is keyed by its whole config, so asking the same question again reuses its answers.\n\n* `monitor` - Monitor\n* `classifier` - Classifier\n* `scorer` - Scorer\n* `summarizer` - Summarizer\n* `experiment` - Experiment" })), "scanner_config": Schema.optionalKey(Schema.Json.annotate({ "expected": "JSON value", "description": "Type-specific configuration beyond the prompt: `tags` for a classifier, `scale` for a scorer, optional `length` for a summarizer. Omit it for a monitor. `prompt` belongs in the `prompt` field and is rejected here." })), "model": Schema.optionalKey(Schema.suspend((): Schema.Codec<ScannerModelEnum> => ScannerModelEnum).annotate({ "description": "Model to scan with. Determines what each observation costs in credits.\n\n* `gemini-3.5-flash-lite` - Gemini 3.5 Flash Lite\n* `gemini-3-flash-preview` - Gemini 3 Flash\n* `gemini-3.8-flash` - Gemini 3.8 Flash", "default": "gemini-3-flash-preview" })), "session_ids": Schema.Array(Schema.String.check(Schema.isMaxCodePoints(128).annotate({ "expected": "a string with at most 128 code points" }))).annotate({ "description": "Session recording IDs to scan, at most 200 per request. Scans start until the in-flight limit or monthly credit quota is reached; the rest are reported as skipped rather than failing the whole batch." }).check(Schema.isMaxLength(200).annotate({ "expected": "a value with a length of at most 200" })) }).annotate({ "description": "Body of POST /vision/scanners/inline_scan/ - a prompt or built-in scan plus the sessions to point it at.", "identifier": "InlineScanRequest" })
export type BulkObserveResult = { readonly "session_id": string, readonly "scan_outcome": ScanOutcomeEnum }
export const BulkObserveResult = Schema.Struct({ "session_id": Schema.String.annotate({ "description": "The session recording this outcome is for." }), "scan_outcome": Schema.suspend((): Schema.Codec<ScanOutcomeEnum> => ScanOutcomeEnum).annotate({ "description": "'started' - a scan workflow was kicked off; 'already_running' - a scan for this session is already in flight (no-op, not recharged); 'already_scanned' - this scanner already has a finished observation for this session, so nothing was started and nothing was charged (read it back, or use the retry action to run it again); 'skipped_limit' - the in-flight cap was reached before this session; 'skipped_quota' - the org's credit quota for this period would be exceeded; 'skipped_scanner_limit' - this scanner's own credit limit would be exceeded; 'failed' - the workflow failed to start.\n\n* `started` - Started\n* `already_running` - Already running\n* `already_scanned` - Already scanned\n* `skipped_limit` - Skipped, in-flight limit reached\n* `skipped_quota` - Skipped, the org's credit quota for this period was reached\n* `skipped_scanner_limit` - Skipped, scanner's own credit limit reached\n* `failed` - Failed to start" }) }).annotate({ "description": "Per-session outcome of a bulk scan trigger.", "identifier": "BulkObserveResult" })
