export const ObservationRequestSession = Schema.Struct({ "session_id": Schema.String.annotate({ "description": "The session recording this outcome is for." }), "scan_outcome": Schema.Union([ScanOutcomeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How the session's scan started, with the same values as a bulk scan trigger. Null while the request still waits for the session to end, or before its scan has started.\n\n* `started` - Started\n* `already_running` - Already running\n* `already_scanned` - Already scanned\n* `skipped_limit` - Skipped, in-flight limit reached\n* `skipped_quota` - Skipped, the org's credit quota for this period was reached\n* `skipped_scanner_limit` - Skipped, scanner's own credit limit reached\n* `failed` - Failed to start" }), "state": Schema.suspend((): Schema.Codec<RequestSessionStateEnum> => RequestSessionStateEnum).annotate({ "description": "Where the session stands now. 'pending' and 'running' are still in progress; 'succeeded' has a result; 'failed' and 'ineligible' finished without one; 'skipped' never started because a limit was reached (`scan_outcome` names which); 'lost' started but produced nothing before the scan timed out.\n\n* `pending` - Pending\n* `running` - Running\n* `succeeded` - Succeeded\n* `failed` - Failed\n* `ineligible` - Ineligible\n* `skipped` - Skipped\n* `lost` - Lost" }), "observation_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The observation for this session, once one exists. Null before that.", "readOnly": true, "format": "uuid" }), "scanner_result": Schema.Union([ScannerResult, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The scanner's answer for this session. Null until the session succeeds.", "readOnly": true }) }).annotate({ "description": "One session of a request: how it started and where it stands now.", "identifier": "ObservationRequestSession" })
