export const HogFlowBatchJob = Schema.Struct({ "id": Schema.String.annotate({ "description": "ID of the batch run.", "readOnly": true, "format": "uuid" }), "status": Schema.optionalKey(Schema.suspend((): Schema.Codec<HogFlowBatchJobStateEnum> => HogFlowBatchJobStateEnum).annotate({ "description": "Status of the batch run. waiting: the audience's cohort is still calculating. queued and active: the run is enrolling its audience. completed: the whole audience was enrolled. When every enrolled person's run has ended, or a day after the run completed, PostHog checks for errored sends. A completed run stays completed when no send errored, becomes partially_failed when some sends errored, and becomes failed when every send errored. failed also means the run could not enroll its audience. cancelled: someone stopped the run. A send errors when its step throws, for example on a template that does not render. Provider failures such as bounces are not errored sends; read them from the run's metrics.\n\n* `waiting` - Waiting\n* `queued` - Queued\n* `active` - Active\n* `completed` - Completed\n* `partially_failed` - Partially failed\n* `cancelled` - Cancelled\n* `failed` - Failed" })), "hog_flow": Schema.String.annotate({ "description": "ID of the workflow this batch run belongs to.", "format": "uuid" }), "filters": Schema.Json.annotate({ "expected": "JSON value", "description": "Audience snapshot the run fanned out to, taken from the workflow's batch trigger filters.", "readOnly": true }), "variables": Schema.optionalKey(Schema.Json.annotate({ "expected": "JSON value", "description": "Variable value overrides applied to this run." })), "created_at": Schema.String.annotate({ "description": "When the batch run was created.", "readOnly": true, "format": "date-time" }), "created_by": Schema.suspend((): Schema.Codec<UserBasic> => UserBasic).annotate({ "description": "User who started the batch run.", "readOnly": true }), "updated_at": Schema.String.annotate({ "description": "When the batch run was last updated.", "readOnly": true, "format": "date-time" }) }).annotate({ "identifier": "HogFlowBatchJob" })
export type WorkflowProposal = { readonly "id": string, readonly "title": string, readonly "rationale": string, readonly "content": { readonly [x: string]: Schema.Json }, readonly "evidence": { readonly [x: string]: Schema.Json }, readonly "step_id": string | null, readonly "base_version": number, readonly "is_stale": boolean, readonly "status": WorkflowProposalStatusEnum, readonly "source_id": string | null, readonly "created_at": string, readonly "resolved_at": string | null, readonly "resolved_by": UserBasic | null, readonly "applied_version": number | null, readonly "rejection_reason": string }
export const WorkflowProposal = Schema.Struct({ "id": Schema.String.annotate({ "readOnly": true, "format": "uuid" }), "title": Schema.String.annotate({ "description": "Short summary of the proposed change.", "readOnly": true }), "rationale": Schema.String.annotate({ "description": "Why the producer thinks this change is worth making.", "readOnly": true }), "content": Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })).annotate({ "description": "Only the content fields the proposal changes. Valid keys: actions, edges, trigger_masking, conversion, exit_condition, email_sending_rate_limit, variables. Each value has the same shape as on the workflow itself.", "readOnly": true }), "evidence": Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })).annotate({ "description": "The numbers behind the proposal, read back by name. Five keys are required: `metric`, the metric name; `current_value`, its value as a number (a rate as a fraction, 0.0865, never a string); `unit`, either `rate` or `count`, since 1.0 is either every message or one of them; `n`, the denominator that value was computed over; and `guardrails`, a list of {metric, value, n, unit} counter-metrics read over the same window, empty only if none apply. PostHog then reads the step's own metrics at `base_version` when the suggestion is filed and stores them under `measured`; the page shows that reading and flags a disagreement with yours. Also conventional: target_value, window (a relative one such as `-7d`, or an ISO 8601 interval `start/end` with offsets, which PostHog reads back exactly), query, app_source_id. A rate with no denominator lets a reviewer mistake noise for a result, a target with no counter-metrics hides a change that lifts one number by harming another, and a number under a key of your own reads to a person as no evidence at all.", "readOnly": true }), "step_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The workflow step this is about. Set for a change to one step: the evidence and the outcome then read that step's metrics, so a change to one email in a sequence is not measured against the rest. Null only for a change that spans the workflow, such as its exit condition or a step being taken out, which is measured on the workflow's own numbers.", "readOnly": true }), "base_version": Schema.Number.annotate({ "description": "Live workflow version this was authored against. Approving compares the steps and fields this changes against that version to tell whether somebody else already changed them.", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "is_stale": Schema.Boolean.annotate({ "description": "Whether approving this would undo an edit made since it was proposed. False while the workflow only changed elsewhere, because approving merges only what the proposal changes.", "readOnly": true }), "status": Schema.suspend((): Schema.Codec<WorkflowProposalStatusEnum> => WorkflowProposalStatusEnum).annotate({ "readOnly": true }), "source_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Stable id of the producing agent run or finding, e.g. 'run:<run id>:finding:<finding id>'.", "readOnly": true }), "created_at": Schema.String.annotate({ "readOnly": true, "format": "date-time" }), "resolved_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "readOnly": true, "format": "date-time" }), "resolved_by": Schema.Union([UserBasic, Schema.Null], { mode: "oneOf" }).annotate({ "readOnly": true }), "applied_version": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Workflow version the approved change went live as.", "readOnly": true }), "rejection_reason": Schema.String.annotate({ "description": "Why the person who rejected this suggestion rejected it, or empty when they gave no reason.", "readOnly": true }) }).annotate({ "identifier": "WorkflowProposal" })
export type WorkflowProposalVersionOutcome = { readonly "version": number, readonly "applied"?: boolean, readonly "proposed_against"?: boolean, readonly "carries_change"?: boolean, readonly "other_changes"?: boolean, readonly "changes"?: ReadonlyArray<WorkflowVersionChange>, readonly "published_at"?: string | null, readonly "published_by"?: UserBasic | null, readonly "versions"?: ReadonlyArray<number>, readonly "target": WorkflowProposalMetric, readonly "secondary"?: WorkflowProposalMetric, readonly "click_through": WorkflowProposalMetric, readonly "guardrails": ReadonlyArray<WorkflowProposalMetric> }
export const WorkflowProposalVersionOutcome = Schema.Struct({ "version": Schema.Number.annotate({ "description": "Workflow version these numbers belong to." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "applied": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the suggestion went live as this version." })), "proposed_against": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the suggestion was written against this version." })), "carries_change": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether this version still holds what the suggestion changed." })), "other_changes": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether this version also changed something the suggestion did not, which the numbers cannot separate." })), "changes": Schema.optionalKey(Schema.Array(WorkflowVersionChange).annotate({ "description": "What this version changed against the version before it." })), "published_at": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When this version went live.", "format": "date-time" })), "published_by": Schema.optionalKey(Schema.Union([UserBasic, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Who published this version." })), "versions": Schema.optionalKey(Schema.Array(Schema.Int).annotate({ "description": "Every version summed into these numbers. The after side runs on while later versions keep the change." })), "target": Schema.suspend((): Schema.Codec<WorkflowProposalMetric> => WorkflowProposalMetric).annotate({ "description": "The metric the suggestion aimed at." }), "secondary": Schema.optionalKey(Schema.suspend((): Schema.Codec<WorkflowProposalMetric> => WorkflowProposalMetric).annotate({ "description": "The rate read beside the target, so a lift in one is visible against the other." })), "click_through": Schema.suspend((): Schema.Codec<WorkflowProposalMetric> => WorkflowProposalMetric).annotate({ "description": "Click-through rate over the same window and denominator, since opens alone can move without clicks." }), "guardrails": Schema.Array(WorkflowProposalMetric).annotate({ "description": "Counter-metrics over the same window, so a harmful win is visible." }) }).annotate({ "identifier": "WorkflowProposalVersionOutcome" })
