export const AutoresearchTrainingRun = Schema.Struct({ "id": Schema.String.annotate({ "description": "Unique UUID of this training run.", "readOnly": true, "format": "uuid" }), "pipeline": Schema.String.annotate({ "description": "Pipeline this training run belongs to.", "format": "uuid" }), "task_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Parent Task ID in the tasks sandbox. Null for stub runs.", "format": "uuid" })), "task_run_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Task sandbox run ID. Null for stub/synchronous training runs.", "format": "uuid" })), "task_url": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Relative URL to the underlying sandbox Task detail page. Null for stub/synchronous training runs.", "readOnly": true }), "status": Schema.suspend((): Schema.Codec<ZendeskImportJobStatusEnum> => ZendeskImportJobStatusEnum).annotate({ "description": "Run status: pending, running, completed, or failed.\n\n* `pending` - Pending\n* `running` - Running\n* `completed` - Completed\n* `failed` - Failed", "readOnly": true }), "kickoff_reason": Schema.Union([AutoresearchTrainingRunKickoffReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why the run started: explore (the first burst of daily runs), scheduled (the research interval), rescue (the champion cannot score) or manual (a person or an agent asked). Null for older runs.\n\n* `explore` - Explore\n* `scheduled` - Scheduled\n* `rescue` - Rescue\n* `manual` - Manual", "readOnly": true }), "agent_runtime_adapter": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Runtime that drove the training agent, 'claude' or 'codex'. Null for older runs and runs with no task.", "readOnly": true }), "agent_model": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Model the training agent ran on. Null for older runs and runs with no task.", "readOnly": true }), "agent_model_label": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Display name of agent_model, e.g. 'Claude Opus 5.5'. Null when agent_model is null.", "readOnly": true }), "agent_reasoning_effort": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Reasoning effort the training agent ran at. Null for older runs, runs with no task, and models with no effort setting.", "readOnly": true }), "iteration_budget": Schema.optionalKey(Schema.Number.annotate({ "description": "Maximum iterations allowed for this run." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(-2147483648).annotate({ "expected": "a value greater than or equal to -2147483648" })).check(Schema.isLessThanOrEqualTo(2147483647).annotate({ "expected": "a value less than or equal to 2147483647" }))), "iteration_count": Schema.Number.annotate({ "description": "Number of iterations completed.", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "best_holdout_score": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Best holdout AUC achieved across all iterations in this run.", "readOnly": true, "format": "double" }), "summary": Schema.Union([TrainingRunSummary, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Distilled cross-run learning summary written on completion. Null until the run completes.", "readOnly": true }), "reader_summary": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "One or two plain sentences on what this run learned, for people. Null if not written.", "readOnly": true }), "headline": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Short title for this run, for people. Null if not written.", "readOnly": true }), "next_steps": Schema.Union([Schema.Array(Schema.String), Schema.Null]).annotate({ "description": "Short plain-language next steps for people, at most 5. Null if not written.", "readOnly": true }), "iterations": Schema.Array(IterationTrail).annotate({ "description": "Per-iteration breakdown — every recipe the agent tried this run, kept or discarded, with its model spec, holdout/train AUC, and one-line rationale. Ordered by iteration_number.", "readOnly": true }), "error": Schema.String.annotate({ "description": "Error message if the run failed.", "readOnly": true }), "started_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Timestamp when the training run started.", "readOnly": true, "format": "date-time" }), "completed_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Timestamp when the training run completed or failed.", "readOnly": true, "format": "date-time" }), "created_at": Schema.String.annotate({ "readOnly": true, "format": "date-time" }) }).annotate({ "identifier": "AutoresearchTrainingRun" })
