export const TrainingRunHistoryEntry = Schema.Struct({ "run_id": Schema.String.annotate({ "description": "UUID of the completed training run.", "format": "uuid" }), "pipeline_id": Schema.String.annotate({ "description": "UUID of the pipeline this run belongs to.", "format": "uuid" }), "is_current_pipeline": Schema.Boolean.annotate({ "description": "True if this run is from the pipeline you are training; False if it is a same-target sibling pipeline on the team." }), "target_event": Schema.String.annotate({ "description": "Target event this run's pipeline predicts." }), "horizon_days": Schema.Number.annotate({ "description": "Prediction horizon (days) of this run's pipeline." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "best_holdout_score": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Best holdout AUC achieved across this run's iterations.", "format": "double" }), "iteration_count": Schema.Number.annotate({ "description": "Number of iterations recorded in this run." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "completed_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When this run completed.", "format": "date-time" }), "summary": Schema.Union([TrainingRunSummary, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Distilled tier-1 summary of this run — read this first to orient. Null for older runs without one." }), "iterations": Schema.Array(IterationTrailWithRecipe).annotate({ "description": "The iteration trail: every recipe tried, kept or discarded, with rationale and score." }) }).annotate({ "description": "One prior completed training run plus its full iteration trail.", "identifier": "TrainingRunHistoryEntry" })
export type OnlinePerformanceRow = { readonly "validation_run_id": string, readonly "prediction_date": string, readonly "horizon_days": number, readonly "weekday": number, readonly "model_id": string, readonly "emitted_role": string, readonly "current_role": string, readonly "n_scored": number, readonly "n_positive": number, readonly "base_rate": number, readonly "mean_p_y": number | null, readonly "realized_auc": number | null, readonly "realized_auc_ci_low": number | null, readonly "realized_auc_ci_high": number | null, readonly "brier_score": number | null, readonly "calibration_error": number | null, readonly "lift_at_10": number | null, readonly "lift_at_20": number | null, readonly "average_precision": number | null, readonly "confusion": ConfusionByCutoff | null, readonly "likely_threshold": number | null, readonly "calibration_bins": ReadonlyArray<CalibrationBin> | null, readonly "warning": string | null, readonly "validated_at": string | null }
export const OnlinePerformanceRow = Schema.Struct({ "validation_run_id": Schema.String.annotate({ "description": "UUID of the validation run that recorded these metrics.", "format": "uuid" }), "prediction_date": Schema.String.annotate({ "description": "Date the predictions were made for (UTC).", "format": "date" }), "horizon_days": Schema.Number.annotate({ "description": "Prediction horizon, in days, the predictions were made under." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "weekday": Schema.Number.annotate({ "description": "ISO weekday of the prediction date: 1 is Monday and 7 is Sunday. Use it to find weekday effects." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "model_id": Schema.String.annotate({ "description": "UUID of the model that emitted the predictions.", "format": "uuid" }), "emitted_role": Schema.String.annotate({ "description": "Role the model had when it emitted the predictions: 'champion' or 'challenger'." }), "current_role": Schema.String.annotate({ "description": "Role the model has now: 'champion', 'challenger', 'archived', or 'deleted'. A former champion that a promotion archived keeps its rows." }), "n_scored": Schema.Number.annotate({ "description": "Number of users the model scored on this date." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "n_positive": Schema.Number.annotate({ "description": "Number of scored users who did the target event in the horizon." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "base_rate": Schema.Number.annotate({ "description": "Fraction of scored users who did the target event (n_positive / n_scored).", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "mean_p_y": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Mean predicted probability. Compare it with base_rate: a higher value means the model over-predicts. Null for dates validated before this metric existed.", "format": "double" }), "realized_auc": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Realized ROC AUC against actual outcomes. Null when the date has one class only.", "format": "double" }), "realized_auc_ci_low": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Lower bound of the 95% AUC interval (Hanley-McNeil). Null when realized_auc is null.", "format": "double" }), "realized_auc_ci_high": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Upper bound of the 95% AUC interval (Hanley-McNeil). Null when realized_auc is null.", "format": "double" }), "brier_score": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Brier score. Lower is better.", "format": "double" }), "calibration_error": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Expected calibration error over 10 equal-width bins. Lower is better.", "format": "double" }), "lift_at_10": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Positives in the top 10% by score, relative to a random 10%.", "format": "double" }), "lift_at_20": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Positives in the top 20% by score, relative to a random 20%.", "format": "double" }), "average_precision": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Average precision: area under the precision-recall curve. Higher is better, and a random model scores about base_rate. Null when no scored user did the target event, or for dates validated before this metric existed.", "format": "double" }), "confusion": Schema.Union([ConfusionByCutoff, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Confusion counts, precision and recall at three cutoffs: top 10%, top 20%, and the Likely segment. Null for dates validated before this metric existed." }), "likely_threshold": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "The Likely cut point the 'likely' confusion counts used for this date, from the base rate of the dates checked before it. Null when confusion is null.", "format": "double" }), "calibration_bins": Schema.Union([Schema.Array(CalibrationBin), Schema.Null]).annotate({ "description": "Calibration table with up to 10 bins cut at score quantiles, lowest scores first. Users with equal scores share a bin, so heavy ties give fewer bins. Null for dates validated before this metric existed." }), "warning": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "'single_class_no_auc' when every scored user had the same outcome, otherwise null." }), "validated_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When the validation run completed.", "format": "date-time" }) }).annotate({ "identifier": "OnlinePerformanceRow" })
