export const ExperimentRunningTimeCalculation = Schema.Struct({ "exposure_estimate_config": Schema.optionalKey(Schema.Union([ExperimentExposureEstimateConfig, Schema.Null]).annotate({ "description": "How the exposure estimate is configured: manual user-entered values or automatic from live experiment data.", "default": null })), "minimum_detectable_effect": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "title": "Minimum Detectable Effect", "description": "Minimum detectable effect as a percentage. Lower values need more users but catch smaller changes.", "default": null })), "recommended_running_time": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "title": "Recommended Running Time", "description": "Estimated number of days needed to reach the recommended sample size.", "default": null })), "recommended_sample_size": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "title": "Recommended Sample Size", "description": "Recommended number of exposed users needed for statistical significance.", "default": null })) }).annotate({ "title": "ExperimentRunningTimeCalculation", "identifier": "ExperimentRunningTimeCalculation" })
