export const ExperimentHealthInputsFlagHistory = Schema.Struct({ "checked": Schema.Boolean.annotate({ "description": "Whether the changes were compared with the exposures. False when not_checked_reason is set." }), "not_checked_reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why the changes were not compared with the exposures: 'no_history_access', 'no_query_access', 'exposure_filters', 'exposure_action', 'exposure_criteria', 'too_many_saves' or 'too_many_conditions'. Null when they were." }), "start_date": Schema.String.annotate({ "description": "The experiment's start date. The flag history counts changes from it, as the results count exposures from it.", "format": "date-time" }), "team_timezone": Schema.String.annotate({ "description": "The project's time zone, which the findings use for times." }), "changes": Schema.Array(ExperimentHealthInputsFlagChange).annotate({ "description": "Every change since launch that can move exposed people, of every kind, in time order. A bucketing change is one per setting and save. A rollout change alone is no release-condition change. Empty for 'no_history_access', which does not read them." }), "exposed_before_first": Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether anyone was exposed before the first counted change. Null when unknown or not checked." }), "exposed_between": Schema.Array(ExperimentHealthInputsExposedBetween).annotate({ "description": "One entry for each kind of change with a counted change, in the order of the kinds." }) }).annotate({ "identifier": "ExperimentHealthInputsFlagHistory" })
export type ExperimentSetupSdkProfile = { readonly "window_days": number, readonly "source_event": string, readonly "computed_at": string, readonly "libs": ReadonlyArray<ExperimentSetupSdkLib>, readonly "libs_truncated": boolean, readonly "flags_seen": number, readonly "flags_evaluated_on_server_and_web": number, readonly "evaluated_on_server_and_web": boolean, readonly "libs_on_any_event": ReadonlyArray<ExperimentSetupLibActivity> | null, readonly "libs_on_any_event_truncated": boolean }
export const ExperimentSetupSdkProfile = Schema.Struct({ "window_days": Schema.Number.annotate({ "description": "Days of flag calls read, ending now." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "source_event": Schema.String.annotate({ "description": "The event read: '$experiment_exposure' when the project receives it, otherwise '$feature_flag_called'. Only one is read, because one copies the other, and only multivariate responses count either way. This says what the project's events carry today, so it can differ from team_defaults.default_exposure_event, which says what a new experiment would count." }), "computed_at": Schema.String.annotate({ "description": "When the numbers were computed. They are cached for hours.", "format": "date-time" }), "libs": Schema.Array(ExperimentSetupSdkLib).annotate({ "description": "One row per SDK, most calls first." }), "libs_truncated": Schema.Boolean.annotate({ "description": "True when more SDKs sent flag calls than libs lists." }), "flags_seen": Schema.Number.annotate({ "description": "Distinct multivariate flag keys called in the window." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "flags_evaluated_on_server_and_web": Schema.Number.annotate({ "description": "How many of those flag keys were called by both a server SDK and the web SDK." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "evaluated_on_server_and_web": Schema.Boolean.annotate({ "description": "True when at least one flag key was called by both a server SDK and the web SDK. The same flag decided on the server and read in the browser can bucket one user into two variants." }), "libs_on_any_event": Schema.Union([Schema.Array(ExperimentSetupLibActivity), Schema.Null]).annotate({ "description": "Up to 10 SDKs seen on any event over the last day, most events first. Set only when libs is empty, so a project creating its first experiment still says which platforms it sends from. Null when flag calls exist, and null when this extra read timed out." }), "libs_on_any_event_truncated": Schema.Boolean.annotate({ "description": "True when more SDKs sent events than libs_on_any_event lists. False when it is null." }) }).annotate({ "identifier": "ExperimentSetupSdkProfile" })
