export const ExperimentMetricsRecalculationRun = Schema.Struct({ "id": Schema.String.annotate({ "description": "Unique identifier for this recalculation job", "readOnly": true, "format": "uuid" }), "experiment_id": Schema.Number.annotate({ "description": "ID of the experiment being recalculated", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "status": Schema.suspend((): Schema.Codec<MetricsRecalculationStatusEnum> => MetricsRecalculationStatusEnum).annotate({ "description": "Current status of the recalculation job\n\n* `pending` - Pending\n* `in_progress` - In Progress\n* `completed` - Completed\n* `failed` - Failed", "readOnly": true }), "total_metrics": Schema.Number.annotate({ "description": "Total number of metrics to recalculate", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "completed_metrics": Schema.Number.annotate({ "description": "Number of metrics with a COMPLETED result row that did not fail in this run (derived, not stored)", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "failed_metrics": Schema.Number.annotate({ "description": "Number of failed metrics in this run (derived): metrics with a FAILED result row or a metric_errors entry. A metric that fails keeps its earlier completed result, so it can count here and still have a completed row in results. The error of a rejected run counts only for a metric without a row", "readOnly": true }).check(Schema.isInt().annotate({ "expected": "an integer" })), "metric_errors": Schema.Json.annotate({ "expected": "JSON value", "description": "Terminal failure per metric_uuid: {step, message, error_type, retriable, timestamp, exposures_path}. retriable is true when a transient error exhausted its attempts, so a heal_latest_run or manual_retry can succeed; false when the metric config, the data, or a resource limit must change first. exposures_path is where the query read the exposures, and is missing when the query failed before it was built", "readOnly": true }), "created_at": Schema.String.annotate({ "description": "When the job was created", "readOnly": true, "format": "date-time" }), "started_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When processing started", "readOnly": true, "format": "date-time" }), "completed_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When processing completed", "readOnly": true, "format": "date-time" }), "query_to": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Upper time bound the metrics in this run were calculated against (the data freshness cutoff). Shared by every metric in the run; null until processing starts", "readOnly": true, "format": "date-time" }), "metric_retries": Schema.Json.annotate({ "expected": "JSON value", "description": "Transient retry state per metric_uuid: {attempt, max_attempts, error_type, message, next_retry_at}. message is a user-safe description of the error that triggered the retry. Present only while a metric is between failed attempts; cleared when it succeeds or fails terminally, so treat entries for metrics that already have a result as stale.", "readOnly": true }), "results": Schema.Array(MetricRecalculationResult).annotate({ "description": "Per-metric results of this run, scoped by the run's recalc fingerprint. When a metric fails, its earlier completed result at the same window stays here and the failure is in metric_errors", "readOnly": true }), "rows_read": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Rows read by the run's metric queries so far, both finished and currently running. Cumulative and roughly monotonic across the run; the primary live progress signal" })), "estimated_rows_total": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "ClickHouse's total_rows_approx across running queries plus the final read_rows of finished ones. A soft ceiling revised mid-scan, so it can exceed or trail rows_read; treat rows_read as the reliable signal" })) }).annotate({ "description": "GET by id: one run with its per-metric results, retry state and live query progress.", "identifier": "ExperimentMetricsRecalculationRun" })
