export const PatchedHogFlowActionEmailUpdate = Schema.Struct({ "base_updated_at": Schema.optionalKey(Schema.String.annotate({ "description": "Optimistic concurrency: the updated_at (or draft_updated_at) last loaded. If the stored workflow is newer, the patch is rejected with 409 instead of clobbering a concurrent edit.", "format": "date-time" })), "operations": Schema.optionalKey(Schema.Array(DesignOperation).annotate({ "description": "Ordered design edits applied atomically to this step's email design - the same operations as the email template patch. The result is re-rendered to HTML server-side, so the sent email always matches the patched design." })), "email_patch": Schema.optionalKey(Schema.Json.annotate({ "expected": "JSON value", "description": "Partial email fields deep-merged into the step's email (a null leaf deletes the key): subject, preheader, text, to, from, replyTo, cc, bcc. The sender is from: {integrationId, email?, name?}, where email and name are optional templated overrides resolved per invocation; the address must resolve to the selected sender's verified domain or the send fails. A sandbox step (type email_sandbox) takes only subject, preheader, text and to. The design is edited via operations, and html is always re-rendered from it." })), "sender": Schema.optionalKey(Schema.suspend((): Schema.Codec<EmailStepSenderEnum> => EmailStepSenderEnum).annotate({ "description": "Switch the step's sender. 'sandbox' moves it to PostHog's sandbox sender, which sends only to verified members of the organization and needs no verified domain; it is set up for the project on first use. 'own' moves a sandbox step back to one of the project's verified senders, named in email_patch.from.integrationId. The step keeps its id, recipient, content and category.\n\n* `sandbox` - sandbox\n* `own` - own" })), "drop_own_sender_settings": Schema.optionalKey(Schema.Boolean.annotate({ "description": "With sender 'sandbox': drop the settings the sandbox sender can't keep (custom from address or name, several senders, replyTo, cc, bcc, turned-off tracking, UTM tags). Without it, the switch is refused and the error lists them, so confirm with the user before setting it.", "default": false })) }).annotate({ "identifier": "PatchedHogFlowActionEmailUpdate" })
