export const BlastRadius = Schema.Struct({ "affected": Schema.Number.annotate({ "description": "Number of users matching the filters" }).check(Schema.isInt().annotate({ "expected": "an integer" })), "total": Schema.Number.annotate({ "description": "Total number of users" }).check(Schema.isInt().annotate({ "expected": "an integer" })), "limit": Schema.Number.annotate({ "description": "Maximum allowed audience size for batch triggers for this team." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "dedupe_key": Schema.Union([DedupeKeyEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The dedupe key that was actually applied to 'affected'. 'email' means it counts unique email addresses; null means it counts persons.\n\n* `email` - email" }), "confirm_token": Schema.String.annotate({ "description": "Proof this audience was previewed: pass it to the batch dispatch (confirm_token) after echoing 'affected' to the user. Signs these exact filters; expires in 15 minutes." }), "realtime_cohort": Schema.optionalKey(Schema.Union([RealtimeCohortStatus, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Set when the audience is one realtime cohort. 'affected' is then the cohort's last calculated size, and a batch run waits until the cohort is ready." })), "realtime_cohort_with_other_conditions": Schema.optionalKey(Schema.Union([RealtimeCohortRef, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Set when a realtime cohort shares the audience with other conditions. Saving that audience fails: a realtime cohort has to be the only condition." })), "rate_limited": Schema.optionalKey(Schema.Union([RateLimitedAudience, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Set when an email sending rate limit can raise 'limit'. A send at a slow enough rate leaves part of the project's daily email allowance to its other workflows, so it may reach more people over several days." })) }).annotate({ "identifier": "BlastRadius" })
