export const InsightDataChecks = Schema.Struct({ "status": Schema.suspend((): Schema.Codec<InsightDataChecksStatusEnum> => InsightDataChecksStatusEnum).annotate({ "description": "The worst result across the checks. `no_events` when no event matches the insight's events, filters and date range. `unsupported` when the insight has no event series to check, such as a SQL insight, and when a property the checks read is hidden from the caller. `inconclusive` when no check could run. `partial` when some checks could not run and the others found nothing. `on_request` when the checks would read a lot of data for a quick check, so they did not run: send `depth` `full` to run them.\n\n* `passed` - No data issues found\n* `warning` - A check found a small issue\n* `problem` - A check found a large issue\n* `partial` - Some checks could not run, and the others found no issue\n* `on_request` - The checks would read a lot of data, so they run only on request\n* `no_events` - No events to check\n* `unsupported` - This kind of insight cannot be checked\n* `inconclusive` - No check could run" }), "checks": Schema.Array(InsightDataCheck).annotate({ "description": "Every check, in a fixed order, whatever its result." }), "coverage": Schema.Union([InsightDataChecksCoverage, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Which days and how many events the checks read. Null when the checks could not choose the days to read, such as for an `unsupported` insight." }) }).annotate({ "identifier": "InsightDataChecks" })
