export const MetricThresholdConfig = Schema.Struct({ "metric_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Metric Id", "description": "Identifier of a metric on the report whose query this check measures. The metric's query is copied into `query` when the check is created.", "default": null })), "query": Schema.optionalKey(Schema.Union([Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })), Schema.Null]).annotate({ "title": "Query", "description": "Live InsightVizNode wrapping one TrendsQuery: supplied by the caller, or copied from the named metric when the check is created. `dateRange.date_from` must be a relative window such as `-13d`, and `date_to` must be empty, so the check measures the days before each run rather than the days before it was written. The query must produce exactly one output series: use one event or action series, or combine up to ten of them with exactly one formula. Use no breakdown and no compare mode. A `trendsFilter.display` of `Metric` turns compare mode on, so `metricShowChange` is switched off for you unless `metricSummary` is `latest`, which keeps compare mode off already.", "default": null })), "monitoring": Schema.optionalKey(Schema.Union([MonitoringMetricConfig, Schema.Null]).annotate({ "description": "Optional Monitoring measurement definition, available only with the organization's Monitoring rollout. Measurements cover Monitoring start through the observation time. Omit for existing whole-window checks.", "default": null })), "comparison": Schema.suspend((): Schema.Codec<CheckComparison> => CheckComparison).annotate({ "description": "What the measured value must satisfy to pass." }), "baseline_value": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "title": "Baseline Value", "description": "The value observed when the check was written, recorded on each result for context.", "default": null })), "metric_kind": Schema.optionalKey(Schema.Union([Schema.Literals(["affected_users", "affected_sessions", "occurrences", "conversion_rate", "error_rate", "duration", "revenue", "custom"]), Schema.Null]).annotate({ "title": "Metric Kind", "description": "How to draw this measurement; copied from a referenced metric.", "default": null })), "value_format": Schema.optionalKey(Schema.Union([Schema.Literals(["number", "count", "percentage", "percentage_scaled", "duration", "currency"]), Schema.Null]).annotate({ "title": "Value Format", "description": "How to format measured values; copied from a referenced metric.", "default": null })), "unit": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(40).annotate({ "expected": "a string with at most 40 code points" })), Schema.Null]).annotate({ "title": "Unit", "description": "Optional value suffix.", "default": null })) }).annotate({ "title": "MetricThresholdConfig", "description": "A deterministic check: measure one number, compare it, record the verdict.\n\nThe number comes either from a metric the report already shows (``metric_id``) or from a query\nthe author supplies. Both end up in the same runner, so a supplied query must satisfy the live\nmetric contract — the node allowlist, the bounded window, and the single-output-series rule.\n\nA caller names one source. When it names a metric, the create path copies that metric's query\ninto ``query`` before the row is stored, so the check keeps measuring what its author saw even if\nthe report's metric is later rewritten under the same id; ``metric_id`` stays as provenance.\n\nUnknown keys are refused rather than ignored, so a misspelled field name is reported instead of\nbeing dropped in silence and stored as it arrived.", "identifier": "MetricThresholdConfig" })
export type MetricThresholdReplacementConfig = { readonly "metric_id"?: string | null, readonly "query"?: { readonly [x: string]: Schema.Json } | null, readonly "monitoring": MonitoringMetricConfig, readonly "comparison": CheckComparison, readonly "baseline_value"?: number | null, readonly "metric_kind"?: "affected_users" | "affected_sessions" | "occurrences" | "conversion_rate" | "error_rate" | "duration" | "revenue" | "custom" | null, readonly "value_format"?: "number" | "count" | "percentage" | "percentage_scaled" | "duration" | "currency" | null, readonly "unit"?: string | null }
export const MetricThresholdReplacementConfig = Schema.Struct({ "metric_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Metric Id", "description": "Identifier of a metric on the report whose query this check measures. The metric's query is copied into `query` when the check is created.", "default": null })), "query": Schema.optionalKey(Schema.Union([Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })), Schema.Null]).annotate({ "title": "Query", "description": "Live InsightVizNode wrapping one TrendsQuery: supplied by the caller, or copied from the named metric when the check is created. `dateRange.date_from` must be a relative window such as `-13d`, and `date_to` must be empty, so the check measures the days before each run rather than the days before it was written. The query must produce exactly one output series: use one event or action series, or combine up to ten of them with exactly one formula. Use no breakdown and no compare mode. A `trendsFilter.display` of `Metric` turns compare mode on, so `metricShowChange` is switched off for you unless `metricSummary` is `latest`, which keeps compare mode off already.", "default": null })), "monitoring": Schema.suspend((): Schema.Codec<MonitoringMetricConfig> => MonitoringMetricConfig).annotate({ "description": "Monitoring definition for the replacement, including the target reference period and scaling policy." }), "comparison": Schema.suspend((): Schema.Codec<CheckComparison> => CheckComparison).annotate({ "description": "What the measured value must satisfy to pass." }), "baseline_value": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "title": "Baseline Value", "description": "The value observed when the check was written, recorded on each result for context.", "default": null })), "metric_kind": Schema.optionalKey(Schema.Union([Schema.Literals(["affected_users", "affected_sessions", "occurrences", "conversion_rate", "error_rate", "duration", "revenue", "custom"]), Schema.Null]).annotate({ "title": "Metric Kind", "description": "How to draw this measurement; copied from a referenced metric.", "default": null })), "value_format": Schema.optionalKey(Schema.Union([Schema.Literals(["number", "count", "percentage", "percentage_scaled", "duration", "currency"]), Schema.Null]).annotate({ "title": "Value Format", "description": "How to format measured values; copied from a referenced metric.", "default": null })), "unit": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(40).annotate({ "expected": "a string with at most 40 code points" })), Schema.Null]).annotate({ "title": "Unit", "description": "Optional value suffix.", "default": null })) }).annotate({ "title": "MetricThresholdReplacementConfig", "identifier": "MetricThresholdReplacementConfig" })
export type EmitReportRequest = { readonly "title": string, readonly "summary": string, readonly "evidence": ReadonlyArray<ReportEvidence>, readonly "actionability_explanation": string, readonly "actionability": ActionabilityEnum, readonly "already_addressed"?: boolean, readonly "repository"?: string | null, readonly "priority"?: AutonomyPriorityEnum | NullEnum, readonly "priority_explanation"?: string | null, readonly "suggested_reviewers"?: ReadonlyArray<SuggestedReviewer>, readonly "charts"?: ReadonlyArray<ReportChart>, readonly "metrics"?: ReadonlyArray<ReportMetricWrite>, readonly "suggested_prompts"?: ReadonlyArray<string>, readonly "links"?: ReadonlyArray<ReportLinkWrite>, readonly "source_issues"?: ReadonlyArray<SourceIssueWrite>, readonly "tags"?: ReadonlyArray<string>, readonly "idempotency_key"?: string | null }
export const EmitReportRequest = Schema.Struct({ "title": Schema.String.annotate({ "description": "One-line report title the inbox shows. Conventional-commit style (`type(scope): description`, e.g. `fix(insights): missing series color`) renders with type/scope styling." }).check(Schema.isMaxCodePoints(300).annotate({ "expected": "a string with at most 300 code points" })), "summary": Schema.String.annotate({ "description": "The report body the inbox shows. Markdown is supported (headings, lists, code, links; images are not rendered). Lead with one plain declarative sentence — the inbox card uses your first line verbatim as the headline (~140 chars, emphasis stripped), then renders the full markdown in the detail view. A heading, or a bold label on a line of its own with a blank line above it, marks a section that a threaded Slack delivery splits into its own reply." }), "evidence": Schema.Array(ReportEvidence).annotate({ "description": "The observations backing the report — each becomes a bound signal. At least one." }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })), "actionability_explanation": Schema.String.annotate({ "description": "2-3 sentence evidence-grounded justification for the actionability call below." }), "actionability": Schema.suspend((): Schema.Codec<ActionabilityEnum> => ActionabilityEnum).annotate({ "description": "The scout's actionability call: `immediately_actionable` -> the report surfaces READY; `requires_human_input` -> PENDING_INPUT; `not_actionable` -> suppressed. A safety-judge failure suppresses the report regardless. A root cause you have not found is not human input: a report that names the evidence, the code surface, or a reproducible failure path is `immediately_actionable`, because investigating it is the action. Reserve `requires_human_input` for a report blocked on a decision only a person can make.\n\n* `immediately_actionable` - immediately_actionable\n* `requires_human_input` - requires_human_input\n* `not_actionable` - not_actionable" }), "already_addressed": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the issue is already being handled — fixed in recent changes, or with a fix in flight (an open PR, a recently active branch, an assigned / in-progress issue or agent task). Gates autostart of a scout report, so a wrong `false` opens a duplicate PR. Tracked separately.", "default": false })), "repository": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional repo for opening a draft PR, by autostart of a scout report or by a person from the inbox. Pass `owner/repo` whenever you can say where a fix would land. Nothing selects a repository for you: omit the field when you can't tell, and the report records no repository unless its text links exactly one connected repo, so it cannot autostart a draft PR. Keep the `NO_REPO` sentinel for the rare report where nothing under version control could change, since a skill body, a config file, or a doc still lives in a repo." })), "priority": Schema.optionalKey(Schema.Union([AutonomyPriorityEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional priority (`P0`-`P4`). Required for autostart; pair with `priority_explanation`.\n\n* `P0` - P0\n* `P1` - P1\n* `P2` - P2\n* `P3` - P3\n* `P4` - P4" })), "priority_explanation": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "2-3 sentence justification for `priority`. Required when `priority` is set." })), "suggested_reviewers": Schema.optionalKey(Schema.Array(SuggestedReviewer).annotate({ "description": "Optional reviewers to route the report to (each a `github_login` and/or `user_uuid`). This is the primary way a report reaches a human — the inbox floats a reviewer's own reports to the top of their inbox even when no PR is involved — so set it whenever you can name a plausible owner. On a scout report it also gates autostart: a PR opens only if at least one reviewer clears their autonomy threshold. A report a person files never autostarts." }).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" }))), "charts": Schema.optionalKey(Schema.Array(ReportChart).annotate({ "description": "Optional charts to attach to the report — the inbox renders them inline, so a metric move is something the reader sees rather than a number they take on trust. Attach one whenever the finding rests on a trend, a spike, or a comparison you already queried. Reference a chart from `summary` as `[label](chart:<chart_id>)` to place it in the body; an unreferenced chart renders below the summary." }).check(Schema.isMaxLength(20).annotate({ "expected": "a value with a length of at most 20" }))), "metrics": Schema.optionalKey(Schema.Array(ReportMetricWrite).annotate({ "description": "Optional typed impact measurements, at most 6. Mark one metric `primary` for the key observation and the rest `supporting`, for users, sessions, occurrences, conversion, latency, or revenue. Every metric needs a live `query`: an InsightVizNode wrapping one bounded TrendsQuery built only from EventsNode or ActionsNode sources, with at most 1000 estimated longitudinal points. An affected-users metric counts distinct people through one series with `math: dau`; never sum its buckets. A `value`/`value_at` snapshot is only an optional cached fallback, and a metric without a query is invalid." }).check(Schema.isMaxLength(6).annotate({ "expected": "a value with a length of at most 6" }))), "suggested_prompts": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" }))).annotate({ "description": "Optional follow-up prompts to offer above the report's `Ask AI` box: questions to ask, or next-step actions to request (e.g. carrying out the report's recommendation). The reader clicks one to fill the box with it, then sends or edits it. Write the prompts your own research left open, phrased as the reader would send them." }).check(Schema.isMaxLength(3).annotate({ "expected": "a value with a length of at most 3" }))), "links": Schema.optionalKey(Schema.Array(ReportLinkWrite).annotate({ "description": "Typed, directed links from the new report to reports that already exist. Send them here, not in a later `edit-report` call, because autostart reads them when the report is created: a `duplicate_of` link to a report that already has a pull request, or a `depends_on` link to a report with no pull request yet, stops a second draft PR. Only the new report gets a row, so link from the side the sentence starts at. Links of the same kind must stay acyclic and every report must be in this project." }).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" }))), "source_issues": Schema.optionalKey(Schema.Array(SourceIssueWrite).annotate({ "description": "The GitHub issues this report is about, when the finding came from an issue tracker. Pass the issue whenever the report is about one, so the report links back to it: a GitHub issue signal for the same issue then joins this report instead of opening a second one. When the project turned on GitHub issue comments, the issue gets one comment that links the report once its GitHub source ingests the issue. At most 5 per call." }).check(Schema.isMaxLength(5).annotate({ "expected": "a value with a length of at most 5" }))), "tags": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Optional slug tags that group the report with related ones, at most 10. Write lowercase kebab-case slugs that name the category of the report (`cost-spike`, `tracking-gap`), not the specific entity. Reuse a slug the project already uses before you coin a new one. Near-miss formats are normalized to slugs, and a tag that is empty or longer than 50 characters after normalization is rejected." }).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" }))), "idempotency_key": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" })), Schema.Null]).annotate({ "description": "Optional name for this emission, unique within a scout's run or within a person's own reports. Reuse it verbatim to retry a call whose outcome you don't know (a timeout, a dropped connection): the retry returns the report the first call authored, with `idempotent_replay` true, instead of a second report. Omit it and the report's own content is the key, which covers a retry of the identical call — pass one when a retry might reword the report." })) }).annotate({ "description": "Request body for the scout `emit-report` action and the inbox report `create` action. A scout run is\ntaken from the URL path; a person is the authenticated caller.", "identifier": "EmitReportRequest" })
export type EditReportRequest = { readonly "expected_reviewers"?: ReviewerState, readonly "reviewer_outcome"?: ReviewerSelectionOutcomeEnum, readonly "reviewer_retry_reason"?: string, readonly "reviewer_outcome_reason"?: string, readonly "report_id": string, readonly "title"?: string | null, readonly "summary"?: string | null, readonly "append_note"?: string | null, readonly "corroboration_only"?: boolean, readonly "append_evidence"?: ReadonlyArray<ReportEvidence> | null, readonly "suggested_reviewers"?: ReadonlyArray<SuggestedReviewer>, readonly "repository"?: string | null, readonly "charts"?: ReadonlyArray<ReportChart> | null, readonly "metrics"?: ReadonlyArray<ReportMetricWrite> | null, readonly "suggested_prompts"?: ReadonlyArray<string> | null, readonly "links"?: ReadonlyArray<ReportLinkWrite>, readonly "source_issues"?: ReadonlyArray<SourceIssueWrite>, readonly "pull_requests"?: ReadonlyArray<string>, readonly "tags"?: ReadonlyArray<string> | null, readonly "supersedes_implementation"?: boolean, readonly "actionability"?: ActionabilityEnum | NullEnum, readonly "actionability_explanation"?: string | null, readonly "already_addressed"?: boolean | null, readonly "priority"?: AutonomyPriorityEnum | NullEnum, readonly "priority_explanation"?: string | null }
export const EditReportRequest = Schema.Struct({ "expected_reviewers": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReviewerState> => ReviewerState).annotate({ "description": "Report reviewer_assignment.state read before selection began. Required when reviewer corrections are enabled." })), "reviewer_outcome": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReviewerSelectionOutcomeEnum> => ReviewerSelectionOutcomeEnum).annotate({ "description": "A successful selection, a deliberate empty result, or an unavailable lookup. Defaults to selected when omitted.\n\n* `selected` - Selected\n* `no_suitable_owner` - No suitable owner\n* `lookup_failed` - Lookup failed" })), "reviewer_retry_reason": Schema.optionalKey(Schema.String.annotate({ "description": "Reason the reviewer lookup failed." }).check(Schema.isMaxCodePoints(500).annotate({ "expected": "a string with at most 500 code points" }))), "reviewer_outcome_reason": Schema.optionalKey(Schema.String.annotate({ "description": "Why no suitable owner exists, with `reviewer_outcome: no_suitable_owner`. Required to clear a report that already has suggested reviewers: without it the current reviewers stay and the response carries a warning. The reason is recorded in the report's work log." }).check(Schema.isMaxCodePoints(500).annotate({ "expected": "a string with at most 500 code points" }))), "report_id": Schema.String.annotate({ "description": "Id of the report to edit (must belong to this project)." }), "title": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(300).annotate({ "expected": "a string with at most 300 code points" })), Schema.Null]).annotate({ "description": "Optional new title. Conventional-commit style (`type(scope): description`) renders with type/scope styling. The pipeline may later re-research and overwrite it." })), "summary": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(20000).annotate({ "expected": "a string with at most 20000 code points" })), Schema.Null]).annotate({ "description": "Optional new summary. Markdown is supported (headings, lists, code, links; images are not rendered); lead with one plain declarative sentence — it becomes the inbox card headline. A heading, or a bold label on a line of its own with a blank line above it, marks a section that a threaded Slack delivery splits into its own reply. The pipeline may later re-research and overwrite it." })), "append_note": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(10000).annotate({ "expected": "a string with at most 10000 code points" })), Schema.Null]).annotate({ "description": "Optional free-form note to append to the report's work log, attributed to this scout. Prefer it over rewriting a report you did not author: a note is additive and keeps the audit trail." })), "corroboration_only": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Set only when `append_note` confirms the finding with no new information. The first four confirmations stay in the work log as entries; later ones only raise the report's corroboration count. Other notes always stay in the work log." })), "append_evidence": Schema.optionalKey(Schema.Union([Schema.Array(ReportEvidence).check(Schema.isMaxLength(50).annotate({ "expected": "a value with a length of at most 50" })), Schema.Null]).annotate({ "description": "Optional observations to add to the report's evidence rail, each becoming a bound signal attributed to this scout — adds to the report's evidence rather than replacing it. Use this for a new observation a reader should be able to check, and `append_note` for commentary (the owning team knows, a deploy fixed it). The report's signal count and weight move with the appended rows. Emit plus every append share a cap of 50 signals per report." })), "suggested_reviewers": Schema.optionalKey(Schema.Array(SuggestedReviewer).annotate({ "description": "Optional reviewers to set on the report (each a `github_login` and/or `user_uuid`), replacing any existing list. Use this to route a report that surfaced with no reviewer — it re-runs autostart, so a report that was missing a qualifying reviewer can now open a draft PR. An empty list clears automatic reviewers when correction rules are enabled. Pins, exclusions, and confirmed lists are preserved. Pass expected_reviewers from the report reviewer_assignment.state read before selection." }).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" }))), "repository": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional repository to point the report at, as `owner/repo` — the fix for a report that surfaced against the wrong codebase, so you correct it in place instead of filing a duplicate. It replaces the report's current target and re-runs autostart, so a report that had no repository to open a PR against can now open a draft PR. Omit the field to leave the target as it is, and pass the `NO_REPO` sentinel for a report where nothing under version control could change. The response's `repository` reads the target back from the report, and the call fails when the target you named did not land." })), "charts": Schema.optionalKey(Schema.Union([Schema.Array(ReportChart).check(Schema.isMaxLength(20).annotate({ "expected": "a value with a length of at most 20" })), Schema.Null]).annotate({ "description": "The full set of charts the report should show. Replaces the report's charts rather than adding to them, the way `summary` replaces the summary — so read the report first and send every chart you want kept. Omit the field (or send null) to leave the report's existing charts untouched, and send an empty list to take them all down." })), "metrics": Schema.optionalKey(Schema.Union([Schema.Array(ReportMetricWrite).check(Schema.isMaxLength(6).annotate({ "expected": "a value with a length of at most 6" })), Schema.Null]).annotate({ "description": "The report's full impact-metric set, at most 6. Omit it or send null to keep the current set, send an empty list to clear it, or send the complete replacement. Mark one metric `primary` for the key observation and the rest `supporting`, for users, sessions, occurrences, conversion, latency, or revenue. Every metric needs a live `query`: an InsightVizNode wrapping one bounded TrendsQuery built only from EventsNode or ActionsNode sources, with at most 1000 estimated longitudinal points. An affected-users metric counts distinct people through one series with `math: dau`; never sum its buckets. A `value`/`value_at` snapshot is only an optional cached fallback, and a metric without a query is invalid." })), "suggested_prompts": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String.check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" }))).check(Schema.isMaxLength(3).annotate({ "expected": "a value with a length of at most 3" })), Schema.Null]).annotate({ "description": "The full set of follow-up prompts (questions or next-step actions) the report should offer above its `Ask AI` box. Replaces the report's prompts rather than adding to them, so send every one you want kept. Omit the field (or send null) to leave them untouched, and send an empty list to take them down, which is what you want once a rewrite has left them pointing at the old report." })), "links": Schema.optionalKey(Schema.Array(ReportLinkWrite).annotate({ "description": "Typed, directed links from this report to others, recording how the work relates. Use `depends_on` when you split one finding into a stack and the second report's fix cannot land until the first one's does, so the order is recorded rather than left to a reader of the diffs. Additive: links join what the report already has rather than replacing them, and only this report gets a row, so link from the side the sentence starts at. Links of the same kind must stay acyclic and every report must be in this project." }).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" }))), "source_issues": Schema.optionalKey(Schema.Array(SourceIssueWrite).annotate({ "description": "The GitHub issues this report is about, when the finding came from an issue tracker. Pass the issue whenever the report is about one, so the report links back to it: a GitHub issue signal for the same issue then joins this report instead of opening a second one. When the project turned on GitHub issue comments, the issue gets one comment that links the report once its GitHub source ingests the issue. At most 5 per call. Additive: issues join the ones the report already names, and an issue it already names is skipped. Only a newly added issue gets a comment." }).check(Schema.isMaxLength(5).annotate({ "expected": "a value with a length of at most 5" }))), "pull_requests": Schema.optionalKey(Schema.Array(Schema.String.annotate({ "format": "uri" }).check(Schema.isMaxCodePoints(2048).annotate({ "expected": "a string with at most 2048 code points" }))).annotate({ "description": "GitHub pull request URLs (`https://github.com/<owner>/<repo>/pull/<number>`) that fix what this report describes, when you found a fix that a person or another agent already opened. A linked pull request is the report's implementation: the report resolves on its own when every linked pull request is closed or merged and at least one merged, and a merged pull request resolves it at once. Additive: a pull request the report already links is skipped. Linking does not claim the report and does not change the pull request itself (no labels, reviewers, or ready-for-review). Link only a pull request whose diff targets this report's cause. The edit refuses a pull request outside the report's repository, one GitHub cannot read, and one closed without merging. At most 5 per call." }).check(Schema.isMaxLength(5).annotate({ "expected": "a value with a length of at most 5" }))), "tags": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" })), Schema.Null]).annotate({ "description": "The report's full set of slug tags, at most 10. Replaces the report's tags rather than adding to them, so send every tag you want kept. Omit the field (or send null) to leave them untouched, and send an empty list to remove them. Reuse a slug the project already uses before you coin a new one." })), "supersedes_implementation": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Set this only when your rewrite changes what the fix should be: a different root cause, a different file or layer, a materially wider or narrower scope. More evidence for the same fix is not a reason, because the report's open pull request already implements it: put that in `append_note`. Setting it true records a replacement decision for a ready report. Policy and eligibility checks gate the replacement. The existing pull request closes only after a successful, verified replacement. Technical failures retry automatically; policy blocks wait for a new edit or research trigger. Only honored alongside a `title` or `summary` that actually changes, and only within the first four content revisions, including revisions that did not request replacement. When the flag is not applied, `warnings` says why." })), "actionability": Schema.optionalKey(Schema.Union([ActionabilityEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional new actionability call, for when new evidence changed your judgment. Replaces the report's actionability decision and re-runs autostart: `immediately_actionable` can open a draft PR, `requires_human_input` and `not_actionable` stop autostart from opening one. The report's inbox status does not change. Send it with `actionability_explanation`, and with `already_addressed` when the issue is handled, since the three replace the decision as one unit.\n\n* `immediately_actionable` - immediately_actionable\n* `requires_human_input` - requires_human_input\n* `not_actionable` - not_actionable" })), "actionability_explanation": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "2-3 sentence evidence-grounded justification for `actionability`. Required when you set it." })), "already_addressed": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether the issue is already handled: fixed, or with a fix in flight. Part of the actionability decision, so it requires `actionability` and `actionability_explanation` too; omitted means false. Set it when a fix lands or starts, so autostart does not open a duplicate PR." })), "priority": Schema.optionalKey(Schema.Union([AutonomyPriorityEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional new priority (`P0`-`P4`), for when the issue escalated or eased. Replaces the report's priority and re-runs autostart, which needs a priority to open a draft PR. Requires `priority_explanation`.\n\n* `P0` - P0\n* `P1` - P1\n* `P2` - P2\n* `P3` - P3\n* `P4` - P4" })), "priority_explanation": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "2-3 sentence justification for `priority`. Required when `priority` is set." })) }).annotate({ "description": "Request body for `edit-report`. Can target ANY of the team's inbox reports, not just scout-authored ones.", "identifier": "EditReportRequest" })
