export const SignalScoutConfigOptions = Schema.Struct({ "model": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" })), Schema.Null]).annotate({ "description": "Optional model id this scout's runs are pinned to, e.g. `claude-opus-4-5`. Must be one of the platform's agent models; an invalid id is rejected with the available ones listed. Null keeps the default model, chosen by the platform. Early access: the pin can only be set on projects enrolled in the scout model preview, and only takes effect there. Set null to clear it." })), "tags": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Free-form labels for grouping the fleet, e.g. `[\"revenue\", \"on-call\"]`. Normalized to lowercase kebab-case (`On Call` and `on_call` both become `on-call`), deduped, and stored sorted; at most 10 tags, each at most 50 characters once normalized. Pass the full desired set — a write replaces the existing tags rather than merging into them. Filter the config list with the `tags` query parameter." }).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" }))), "structured_output_schema": Schema.optionalKey(Schema.Union([Schema.Record(Schema.String, Schema.Json.annotate({ "expected": "JSON value" })), Schema.Null]).annotate({ "description": "Optional JSON Schema (draft 2020-12) describing ONE structured record this scout produces via `scout-record-output` — e.g. a per-report quality judgment (`{\"type\": \"object\", \"properties\": {\"verdict\": {\"enum\": [\"good\", \"bad\", \"unsure\"]}, \"reason\": {\"type\": \"string\"}}, \"required\": [\"verdict\", \"reason\"]}`). The root must be `\"type\": \"object\"`. Setting a schema turns the structured-output channel on: the run prompt renders the schema and every submitted record is validated against it and recorded in the project as a `$scout_structured_output` event, queryable like any event. The channel also requires emit — a dry-run scout has nowhere to record to. Cardinality is the scout's call (one record per run, one per judged entity, ...). Null = channel off. Setting a schema requires skill-authoring authorization (the `llm_skill:write` scope and skill editor access) since the scout reads it verbatim in its prompt; clearing it needs only the config write. Records validate against the schema in force when the run was dispatched." })), "mcp_gateway_server_ids": Schema.optionalKey(Schema.Array(Schema.String.annotate({ "format": "uuid" })).annotate({ "description": "MCP gateway servers (by id) this scout's runs may use, chosen from the connections members shared to the whole team. Selection is per scout: an empty list gives the scout no MCP servers. Applies from the scout's next run." }).check(Schema.isMaxLength(100).annotate({ "expected": "a value with a length of at most 100" }))), "repositories": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxCodePoints(255).annotate({ "expected": "a string with at most 255 code points" }))).annotate({ "description": "GitHub repositories this scout clones into its sandbox, each in `organization/repo` format. Set them for a scout that reads code, so it can search the tree and run the project's own tests instead of reading files one API call at a time. Empty (the default) leaves the sandbox without a checkout. The scout's GitHub access stays read-only either way, so a repository listed here is never writable from a run. At most 10, each reachable through the project's GitHub connection. Applies from the scout's next run." }).check(Schema.isMaxLength(10).annotate({ "expected": "a value with a length of at most 10" }))), "write_scopes": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Write access granted to this one scout, as scope strings. The grantable set is `account_note:write`, `alert:write`, `annotation:write`, `canvas:write`, `customer_task:write`, `dashboard:write`, `event_definition:write`, `experiment:write`, `hog_flow_proposal:write`, `insight:write`, `llm_skill:write`, `notebook:write`, `replay_scanner:write`, `ticket:write`, `warehouse_table:write`, `warehouse_view:write`. A new scout starts with `notebook:write` when this field is omitted. Empty means the scout reads the project and writes only its findings and its own memory. Each scope is project-wide and object-level, so a scout holding `dashboard:write` can update or delete any dashboard in the project, not only ones it made. `ticket:write` lets the scout update tickets, manage saved views, and add private notes. Scouts cannot send public replies, compose emails, change existing notes, or change customer identity fields. Ticket changes can start workflows that message customers. `event_definition:write` lets the scout change the tags on event definitions and nothing else. `account_note:write` lets the scout write and retag notes on Customer analytics accounts. Its notes are always tagged `scout` and with its skill name, and the account notes API refuses its deletes. Account notes are also notebooks, so `notebook:write` can still edit or trash one. Grant only what this scout maintains. Only the person the scout's runs act as (whoever authored it) or a project admin can set it, and a scoped API key must itself carry each scope it grants. A dry run (`emit=false`) never holds the grant, and a run that acts as a project member other than the author holds only the default scopes. Applies from the scout's next run." }).check(Schema.isMaxLength(16).annotate({ "expected": "a value with a length of at most 16" }))), "lifecycle_locked": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Opt-in guard on this scout's lifecycle. Off by default, so anyone with scout write access may pause, resume, switch the scout to dry run, or delete it. On, only the person the scout's runs act as or a project admin may do any of those, or change this flag. Use it on a scout whose output people depend on: `signal_scout:write` is a project-wide scope held by people and by unattended agents alike, and a resume has to pass the project's enabled-scout maximum that a pause does not, so a bulk pause is not undone in one step. The lock never stops an automatic pause, such as the inactivity sweep or the repeated-failure breaker." })), "allowed_mcp_tools": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String), Schema.Null]).annotate({ "description": "Exact MCP tool names selected for this scout, excluding its built-in run context tools. Null means no tool restriction; an empty list selects no additional tools. Write access is derived from selected write tools. Clearing to null preserves the last write scopes. Send this field or tool_preset, never both. Requires the scouts-tool-access feature flag." })), "tool_preset": Schema.optionalKey(Schema.suspend((): Schema.Codec<ToolPresetEnum> => ToolPresetEnum).annotate({ "description": "Expand this named preset into a saved tool list. Later preset changes do not alter the saved list. Send this field or allowed_mcp_tools, never both. Requires the scouts-tool-access feature flag.\n\n* `read_only` - Read only\n* `support_notes` - Support notes" })), "precheck_query": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(10000).annotate({ "expected": "a string with at most 10000 code points" })), Schema.Null]).annotate({ "description": "Optional HogQL `SELECT` a scheduled run evaluates before it starts. When it returns no rows, or one row with one false value (`false`, `0`, null or empty), the run is skipped: no sandbox, no model call, and no run row. Any other result starts the run, and the scout reads the rows. A query error also starts the run. Use `{since}` (the start of the last run that ran, or when the scout was created) and `{now}` to look only at what is new, e.g. `SELECT count() FROM events WHERE event = '$exception' AND timestamp > {since}`. To run at least once a week however quiet it is, add `OR {since} < {now} - INTERVAL 7 DAY` to the condition. Only scheduled runs evaluate it: a manual or workflow run always starts. `{interval_minutes}` is the gap between two scheduled runs, so a backstop can follow the schedule: `{since} < {now} - toIntervalMinute(greatest(1440, 2 * {interval_minutes}))` runs at least daily and never more often than every two intervals. The query stops after 10 seconds and reads at most 50 rows. Try a query with `scout-config-precheck-test` before you save it. Null or blank uses the default pre-check the scout's skill ships, if any. To turn every pre-check off, set `precheck_disabled`." })), "enabled": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether this scout runs on its schedule. Defaults to true." })), "emit": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the scout writes findings to the inbox. False = dry-run: it runs and logs but emits nothing. Defaults to true." })), "run_interval_minutes": Schema.optionalKey(Schema.Number.annotate({ "description": "Minutes between runs (30–43200). Defaults to 1440 (every 24 hours)." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(30).annotate({ "expected": "a value greater than or equal to 30" })).check(Schema.isLessThanOrEqualTo(43200).annotate({ "expected": "a value less than or equal to 43200" }))), "output_destinations": Schema.optionalKey(Schema.suspend((): Schema.Codec<SignalScoutOutputDestinations> => SignalScoutOutputDestinations).annotate({ "description": "Destinations that receive each finding or report this scout emits. Empty by default." })), "network_access": Schema.optionalKey(Schema.suspend((): Schema.Codec<SignalScoutConfigNetworkAccessEnum> => SignalScoutConfigNetworkAccessEnum).annotate({ "description": "What the scout's sandbox can reach over the network while it runs. Defaults to `trusted`, the platform's trusted-domain allowlist (PostHog, GitHub, common package registries). Set `full` to let this scout reach any site, for skills that read external sources such as documentation or papers.\n\n* `trusted` - Trusted domains only\n* `full` - Full" })), "auto_pause_exempt": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Exempt this scout from the inactivity pause, which otherwise switches off a scout that goes a fortnight without surfacing anything anyone engages with. Set it on watchdog scouts whose value is staying quiet. Defaults to false." })), "run_cron_schedule": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(100).annotate({ "expected": "a string with at most 100 code points" })), Schema.Null]).annotate({ "description": "Optional five-field cron expression, e.g. '30 9 * * *' (daily at 09:30), '0 9,17 * * *' (twice daily), or '0 9 * * 1-5' (weekday mornings). Evaluated in the project timezone. Takes precedence over `run_interval_minutes`; occurrences must be at least 30 minutes apart." })) }).annotate({ "description": "Schedule, enablement, and delivery options accepted while creating a scout.", "identifier": "SignalScoutConfigOptions" })
export type SignalScoutConfigCreate = { readonly "model"?: string | null, readonly "tags"?: ReadonlyArray<string>, readonly "structured_output_schema"?: { readonly [x: string]: Schema.Json } | null, readonly "mcp_gateway_server_ids"?: ReadonlyArray<string>, readonly "repositories"?: ReadonlyArray<string>, readonly "write_scopes"?: ReadonlyArray<string>, readonly "lifecycle_locked"?: boolean, readonly "allowed_mcp_tools"?: ReadonlyArray<string> | null, readonly "tool_preset"?: ToolPresetEnum, readonly "precheck_query"?: string | null, readonly "enabled"?: boolean, readonly "emit"?: boolean, readonly "run_interval_minutes"?: number, readonly "output_destinations"?: SignalScoutOutputDestinations, readonly "network_access"?: SignalScoutConfigNetworkAccessEnum, readonly "auto_pause_exempt"?: boolean, readonly "run_cron_schedule"?: string | null, readonly "display_name"?: string, readonly "skill_name": string }
