export const ScoutMember = Schema.Struct({ "user_uuid": Schema.String.annotate({ "description": "The member's stable PostHog user UUID — the same id that appears as `created_by.uuid` on entities they own. A durable handle for this person across runs." }), "email": Schema.String.annotate({ "description": "The member's email — use to match a finding's owner by name/email.", "format": "email" }), "first_name": Schema.String.annotate({ "description": "The member's first name (may be empty)." }), "last_name": Schema.String.annotate({ "description": "The member's last name (may be empty)." }), "github_login": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The member's resolved GitHub login (lowercased), already resolved server-side. Null when the member has no linked GitHub account, which does not stop you routing to them: pass their `user_uuid` in `suggested_reviewers` and the report reaches them. A null login only means no draft PR can be opened as that person." }), "teams": Schema.Array(ScoutMemberTeam).annotate({ "description": "The teams this member is on, from the project's synced team roster. Empty when no roster is synced, or when the member has no linked GitHub account, since the roster is keyed on that login. The roster is a periodic snapshot, so it can lag the live team." }), "activity": Schema.optionalKey(Schema.Union([ScoutMemberActivity, Schema.Null], { mode: "oneOf" }).annotate({ "description": "What the member worked on recently. Use it as context to check against the report, not as proof: general activity is not evidence that the member owns the affected work. Filled only when the call passes `search` or `team` and returns at most 10 members. Null when the member has no ready summary, or when activity summaries are not available for this project." })) }).annotate({ "description": "One project member's routing identity, for picking a `suggested_reviewers` entry on a report.", "identifier": "ScoutMember" })
