export const ProjectProfileSummary = Schema.Struct({ "emit_eligibility": Schema.Union([EmitEligibility, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The delivery gate: whether scout findings can reach the inbox for this team, with a one-line `remediation` when they cannot. Check `can_emit` before investigating anything, because when it is False every emit is silently dropped. Null only for a stored profile built before this section existed, which the caller should treat as unknown rather than as permission to emit." }), "existing_inbox_reports": Schema.Union([ExistingInboxReports, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Counts of reports already in the inbox, grouped by status, which is what a new finding would be deduped against. Null for a stored profile built before this section existed." }) }).annotate({ "description": "The compact envelope returned ahead of the verbose `payload`.\n\nBoth sections are repeated from `payload.inventory`. They lead the response because a\nclient that truncates a long tool result keeps the prefix, and these are the two things a\nscout has to know before it does anything: whether its output can reach the inbox at all,\nand what is already there. Read `summary` rather than digging for the same keys inside\n`payload.inventory`, because it is the same data and it is guaranteed to be in the part you\nreceived.", "identifier": "ProjectProfileSummary" })
export type ProjectProfileInventory = { readonly "project_context": ProjectContext, readonly "products_in_use": ReadonlyArray<string>, readonly "product_intents": ReadonlyArray<ProductIntentEntry>, readonly "integrations": ReadonlyArray<IntegrationEntry>, readonly "external_data_sources": ReadonlyArray<ExternalDataSourceEntry>, readonly "signal_source_configs": SignalSourceConfigsBuckets, readonly "emit_eligibility": EmitEligibility, readonly "scout_fleet": ScoutFleet, readonly "existing_inbox_reports": ExistingInboxReports, readonly "recent_activity": RecentActivity, readonly "recent_reviewer_corrections": RecentReviewerCorrections, readonly "recent_dashboards": ReadonlyArray<RecentDashboardEntry>, readonly "recent_surveys": RecentSurveys, readonly "recent_feature_flags": RecentFeatureFlags, readonly "recent_experiments": RecentExperiments, readonly "recent_alerts": RecentAlerts, readonly "recent_hog_functions": RecentHogFunctions, readonly "recent_hog_flows": RecentHogFlows, readonly "recent_notebooks": RecentNotebooks, readonly "recent_cohorts": RecentCohorts, readonly "recent_actions": RecentActions, readonly "top_events": ReadonlyArray<TopEventEntry> | null }
export const ProjectProfileInventory = Schema.Struct({ "project_context": Schema.suspend((): Schema.Codec<ProjectContext> => ProjectContext).annotate({ "description": "Free-form orientation: human-set product description + registered app URLs." }), "products_in_use": Schema.Array(Schema.String).annotate({ "description": "Product keys this team has completed onboarding for, sorted alphabetically." }), "product_intents": Schema.Array(ProductIntentEntry).annotate({ "description": "Products the team signaled intent to use; useful for spotting stuck onboardings." }), "integrations": Schema.Array(IntegrationEntry).annotate({ "description": "Connected integrations (kind + connection time only — config never surfaced)." }), "external_data_sources": Schema.Array(ExternalDataSourceEntry).annotate({ "description": "Connected warehouse sources (excludes soft-deleted)." }), "signal_source_configs": Schema.suspend((): Schema.Codec<SignalSourceConfigsBuckets> => SignalSourceConfigsBuckets).annotate({ "description": "Signal source configs split into enabled / disabled buckets." }), "emit_eligibility": Schema.suspend((): Schema.Codec<EmitEligibility> => EmitEligibility).annotate({ "description": "Whether scout findings can actually reach the inbox for this team — the org-level AI data-processing consent gate and the `signals_scout` source toggle, plus a one-line remediation pointer. Read at cold start to quick-close before doing throwaway work." }), "scout_fleet": Schema.suspend((): Schema.Codec<ScoutFleet> => ScoutFleet).annotate({ "description": "The other scouts configured on this project, split into enabled / disabled, each with its cadence, dry-run posture, last run, and last emit. Read it to see who else is watching this project before investigating a surface a sibling already covers." }), "existing_inbox_reports": Schema.suspend((): Schema.Codec<ExistingInboxReports> => ExistingInboxReports).annotate({ "description": "Counts of reports already in the inbox, grouped by status." }), "recent_activity": Schema.suspend((): Schema.Codec<RecentActivity> => RecentActivity).annotate({ "description": "Per-scope counts off the activity log over the recent-activity window — cross-cutting orientation across every entity type (surveys, feature flags, experiments, dashboards, insights, cohorts, notebooks, actions, etc.). Each scope reports `edits` (total log entries), `users` (distinct user count), and `last_edit` (ISO-8601). Use to triage which scope a team has been working in lately before drilling down via the per-entity readers or `advanced-activity-logs-list`." }), "recent_reviewer_corrections": Schema.suspend((): Schema.Codec<RecentReviewerCorrections> => RecentReviewerCorrections).annotate({ "description": "Recent human edits to report reviewer lists (before/after GitHub logins). The strongest ownership precedent available — check it before setting `suggested_reviewers` and fold what it shows into `reviewer:` memory keys." }), "recent_dashboards": Schema.Array(RecentDashboardEntry).annotate({ "description": "Up to 20 dashboards on this team sorted by `last_accessed_at` desc — what the team is currently looking at, not necessarily the most-trafficked. We don't have per-dashboard view counts in Postgres, only the timestamp of the most recent access." }), "recent_surveys": Schema.suspend((): Schema.Codec<RecentSurveys> => RecentSurveys).annotate({ "description": "Surveys orientation: total + active count, plus the 5 most recently updated surveys with id, name, type, status (draft / running / stopped / archived), and updated_at." }), "recent_feature_flags": Schema.suspend((): Schema.Codec<RecentFeatureFlags> => RecentFeatureFlags).annotate({ "description": "Feature flag orientation: total + active count, plus the 5 most recently updated non-deleted flags with id, key, name, active, and updated_at." }), "recent_experiments": Schema.suspend((): Schema.Codec<RecentExperiments> => RecentExperiments).annotate({ "description": "Experiment orientation: total + running count, plus the 5 most recently updated experiments. The feature_flag_key on each row lets the scout correlate experiments with the `recent_feature_flags` section." }), "recent_alerts": Schema.suspend((): Schema.Codec<RecentAlerts> => RecentAlerts).annotate({ "description": "Alert orientation: total + enabled count, plus the 5 most recently created alerts with their state and threshold metadata." }), "recent_hog_functions": Schema.suspend((): Schema.Codec<RecentHogFunctions> => RecentHogFunctions).annotate({ "description": "Hog function orientation: total + enabled count, plus the 5 most recently updated destinations / transformations the team has wired up via the CDP pipelines." }), "recent_hog_flows": Schema.suspend((): Schema.Codec<RecentHogFlows> => RecentHogFlows).annotate({ "description": "Hog flow orientation: total + non-archived count, plus the 5 most recently updated automation flows." }), "recent_notebooks": Schema.suspend((): Schema.Codec<RecentNotebooks> => RecentNotebooks).annotate({ "description": "Notebook orientation: total + the 5 most recently modified notebooks — useful signal for what the team has been investigating." }), "recent_cohorts": Schema.suspend((): Schema.Codec<RecentCohorts> => RecentCohorts).annotate({ "description": "Cohort orientation: total + the 5 most recently created cohorts on the team." }), "recent_actions": Schema.suspend((): Schema.Codec<RecentActions> => RecentActions).annotate({ "description": "Action orientation: total + the 5 most recently updated actions — useful to anchor agent reasoning about what the team treats as a meaningful interaction." }), "top_events": Schema.Union([Schema.Array(TopEventEntry), Schema.Null]).annotate({ "description": "Top ~50 events by count over a recent rolling window (each row carries `window_days`), with first/last seen timestamps within that window. These are WINDOWED counts, not lifetime totals: a capture gap can collapse a real, high-volume project's counts to near-zero here, so rule out an ingestion gap (compare against a trailing baseline via a direct `execute-sql`) before reading thinness as a genuinely low-volume project. `null` if the underlying ClickHouse query failed or timed out (distinct from `[]`, which means the team has no captures in the window). Use the gap between `first_seen_in_window` and `now` to spot new event types or recent bursts." }) }).annotate({ "description": "The deterministic inventory layer of a project profile.\n\nRead this to orient on the team's product mix, integrations, warehouse sources, signal\ncoverage, and existing inbox surface in one tool call. Distinct from `SignalScratchpad`:\nprofile is ground truth from authoritative tables; memory is agent inference.", "identifier": "ProjectProfileInventory" })
