export const StamphogRoutingRunOwner = Schema.Struct({ "outcome": Schema.suspend((): Schema.Codec<RoutingOwnerOutcomeEnum> => RoutingOwnerOutcomeEnum).annotate({ "description": "What the run did with the owner: 'requested', 'labeled' (a fork label instead of a request), 'refused' (GitHub refused the request or the label), 'cut', 'not_requested' (stamphog approved, and routing would have asked this owner without the approval; on an older run whose llm_skipped is 'stamphog_approved' it means only that the owner owns changed code) or 'already_requested' (an earlier run asked this pinned owner).\n\n* `requested` - Requested\n* `labeled` - Labeled\n* `refused` - Refused by GitHub\n* `cut` - Cut\n* `not_requested` - Not requested\n* `already_requested` - Already requested", "readOnly": true }), "reason": Schema.suspend((): Schema.Codec<RoutingOwnerReasonEnum> => RoutingOwnerReasonEnum).annotate({ "description": "Why: 'sensitive' or 'new_path' (pinned, never cut), 'largest_owner' (a pull request keeps at least one reviewer), 'diff_not_seen' (the model did not see all of the owner's diff), 'cut_skipped' (no model call, see llm_skipped on the run), 'model_kept', 'model_cut' or 'stamphog_approved' (older runs only).\n\n* `sensitive` - Owns a sensitive path\n* `new_path` - Owns a new path\n* `largest_owner` - Has the largest part\n* `diff_not_seen` - Diff not shown to the model\n* `cut_skipped` - Cut step skipped\n* `model_kept` - Kept by the model\n* `model_cut` - Cut by the model\n* `stamphog_approved` - Stamphog approved", "readOnly": true }), "pins": Schema.Array(StamphogRoutingPin).annotate({ "description": "The changed paths that pinned the owner, so no cut could remove them.", "readOnly": true }), "kind": Schema.suspend((): Schema.Codec<OwnerKindEnum> => OwnerKindEnum).annotate({ "description": "Whether the owner is a GitHub team or a person.\n\n* `team` - Team\n* `person` - Person", "readOnly": true }), "owner": Schema.String.annotate({ "description": "The owner as owners.yaml spells it: a team slug such as 'team-devex', or a GitHub login such as '@octocat'." }), "model_reason": Schema.optionalKey(Schema.String.annotate({ "description": "The model's one-line reason to cut this owner. Also set when a guard kept the owner anyway. Blank when the model proposed no cut for them." })), "lines": Schema.optionalKey(Schema.Number.annotate({ "description": "Changed lines in the files this owner owns." }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "file_count": Schema.optionalKey(Schema.Number.annotate({ "description": "Changed files this owner owns." }).check(Schema.isInt().annotate({ "expected": "an integer" }))) }).annotate({ "identifier": "StamphogRoutingRunOwner" })
