export const ClaudeTaskRunCreateSchema = Schema.Struct({ "imported_mcp_servers": Schema.optionalKey(Schema.Union([Schema.Array(ImportedMcpServer), Schema.Null]).annotate({ "description": "Local url-based MCP servers from the creating client (PostHog Desktop) to make available inside the cloud sandbox. Header values are treated as credentials: stored encrypted and never returned by the API.", "writeOnly": true })), "relayed_mcp_servers": Schema.optionalKey(Schema.Union([Schema.Array(RelayedMcpServer), Schema.Null]).annotate({ "description": "Names of desktop-only MCP servers the creating client (PostHog Desktop) relays into the cloud sandbox over the durable event/command channel. Names only — the server configuration (command, env, URL, headers) never crosses the wire.", "writeOnly": true })), "rtk_enabled": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether rtk command-output compression is enabled for this run. Omitted or null follows the server-side default (enabled); false opts this run out." })), "benjamin_enabled": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether the Benjamin-Plus token-efficiency instruction applies to this run. Omitted or null lets the server decide from the feature flag; true or false pins the choice for this run." })), "claude_model_access": Schema.optionalKey(Schema.Union([ModelAccessEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How the Claude runtime pays for model use. 'own-subscription' makes the sandbox request a Claude token from whoever started the run; Desktop relays it interactively and an API key caller relays it unattended. The token is sent in flight and never stored on PostHog servers. Only PostHog Desktop and API keys can select 'own-subscription'; other callers get a 400. If omitted or null, resumed runs keep their billing choice and new runs use the PostHog gateway.\n\n* `posthog-gateway` - posthog-gateway\n* `own-subscription` - own-subscription" })), "codex_model_access": Schema.optionalKey(Schema.Union([ModelAccessEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How the Codex runtime pays for model use. 'own-subscription' makes the sandbox fetch a ChatGPT access token from the PostHog API, refreshed from the ChatGPT account the run owner connected in Desktop settings. If omitted or null, resumed runs keep their billing choice and new runs use the PostHog gateway.\n\n* `posthog-gateway` - posthog-gateway\n* `own-subscription` - own-subscription" })), "scheduled_at": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Earliest start time for a one-off cloud run, in ISO 8601 format. Must be in the future and within 30 days. Times without an offset use UTC. Omit or send null to start immediately." })), "mode": Schema.optionalKey(Schema.suspend((): Schema.Codec<TaskExecutionModeEnum> => TaskExecutionModeEnum).annotate({ "description": "Execution mode: 'interactive' for user-connected runs, 'background' for autonomous runs\n\n* `interactive` - interactive\n* `background` - background", "default": "background" })), "branch": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(255).annotate({ "expected": "a string with at most 255 code points" })), Schema.Null]).annotate({ "description": "Git branch to checkout in the sandbox" })), "resume_from_run_id": Schema.optionalKey(Schema.String.annotate({ "description": "ID of a previous run to resume from. Must belong to the same task.", "format": "uuid" })), "pending_user_message": Schema.optionalKey(Schema.String.annotate({ "description": "Initial or follow-up user message to include in the run prompt." })), "pending_user_artifact_ids": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxCodePoints(128).annotate({ "expected": "a string with at most 128 code points" }))).annotate({ "description": "Identifiers for staged task artifacts that should be attached to the initial run prompt." })), "sandbox_environment_id": Schema.optionalKey(Schema.String.annotate({ "description": "Optional sandbox environment to apply for this cloud run.", "format": "uuid" })), "custom_image_id": Schema.optionalKey(Schema.String.annotate({ "description": "Optional custom base image for this cloud run's sandbox (Modal VM runtime only); takes precedence over the environment's image.", "format": "uuid" })), "pr_authorship_mode": Schema.optionalKey(Schema.suspend((): Schema.Codec<PrAuthorshipModeEnum> => PrAuthorshipModeEnum).annotate({ "description": "Whether pull requests for this run should be authored by the user or the bot.\n\n* `user` - user\n* `bot` - bot" })), "auto_publish": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "When true, the cloud run agent pushes its work and opens a draft pull request on completion without waiting for an explicit ask." })), "run_source": Schema.optionalKey(Schema.suspend((): Schema.Codec<RunSourceEnum> => RunSourceEnum).annotate({ "description": "High-level source that triggered this run, used to distinguish manual and signal-based cloud runs.\n\n* `manual` - manual\n* `signal_report` - signal_report\n* `agent` - agent" })), "signal_report_id": Schema.optionalKey(Schema.String.annotate({ "description": "Optional signal report identifier when this run was started from Inbox." })), "runtime_adapter": Schema.suspend((): Schema.Codec<ClaudeRuntimeAdapterEnum> => ClaudeRuntimeAdapterEnum).annotate({ "description": "Agent runtime adapter to launch for this run. Must be 'claude' for Claude runtimes.\n\n* `claude` - claude" }), "model": Schema.String.annotate({ "description": "LLM model identifier to run in the Claude runtime." }), "reasoning_effort": Schema.optionalKey(Schema.suspend((): Schema.Codec<ReasoningEffortEnum> => ReasoningEffortEnum).annotate({ "description": "Reasoning effort to request for models that expose an effort control.\n\n* `low` - low\n* `medium` - medium\n* `high` - high\n* `xhigh` - xhigh\n* `max` - max\n* `ultracode` - ultracode" })), "context_window": Schema.optionalKey(Schema.suspend((): Schema.Codec<ContextWindowEnum> => ContextWindowEnum).annotate({ "description": "Context window size for models that support the 1M window.\n\n* `200k` - 200k\n* `1m` - 1m" })), "fast_mode": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Enable fast mode for models that support it." })), "github_user_token": Schema.optionalKey(Schema.String.annotate({ "description": "Optional GitHub user token from PostHog Desktop for user-authored cloud pull requests. Prefer linking GitHub from Settings → Linked accounts so the server can manage tokens; this field remains supported for callers that still manage their own tokens.", "writeOnly": true })), "initial_permission_mode": Schema.optionalKey(Schema.suspend((): Schema.Codec<InitialPermissionModeEnum> => InitialPermissionModeEnum).annotate({ "description": "Initial permission mode for Claude runtimes.\n\n* `default` - default\n* `acceptEdits` - acceptEdits\n* `plan` - plan\n* `bypassPermissions` - bypassPermissions\n* `auto` - auto" })) }).annotate({ "description": "Request body for creating a new task run", "identifier": "ClaudeTaskRunCreateSchema" })
