export const CreateObservationRequest = Schema.Struct({ "session_ids": Schema.Array(Schema.String.check(Schema.isMaxCodePoints(128).annotate({ "expected": "a string with at most 128 code points" }))).annotate({ "description": "Session recording IDs to scan, at most 200 per request. Scans start until the in-flight limit or monthly credit quota is reached; the rest are reported as skipped rather than failing the whole request. Duplicates are dropped." }).check(Schema.isMaxLength(200).annotate({ "expected": "a value with a length of at most 200" })), "scanner_id": Schema.optionalKey(Schema.String.annotate({ "description": "A saved scanner to apply to the sessions. Pass this or `inline`, not both.", "format": "uuid" })), "inline": Schema.optionalKey(Schema.suspend((): Schema.Codec<InlineScanConfig> => InlineScanConfig).annotate({ "description": "A question to ask without saving a scanner first. Asking the same question again reuses the answers already given for the same sessions. Pass this or `scanner_id`, not both." })), "idempotency_key": Schema.optionalKey(Schema.String.annotate({ "description": "Any unique string per logical request, such as a UUID. Sending the same key again returns the first request instead of starting new scans, so a retry after a timeout never charges twice." }).check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" }))), "reference": Schema.optionalKey(Schema.String.annotate({ "description": "Your own id for this request, such as a ticket or job id. Returned unchanged.", "default": "" }).check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" }))), "wait_for_session_end": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Hold the scans until every session has been quiet for 35 minutes, so each one is scanned whole. Use it when the sessions may still be recording. A scan of a live session sees only part of it, and its observation can't be replaced later. Sessions still active after 6 hours are scanned as they are.", "default": false })) }).annotate({ "description": "Body of POST /vision/requests/ - the sessions plus a saved scanner or an inline question.", "identifier": "CreateObservationRequest" })
