export const FlakinessEntry = Schema.Struct({ "variant_count": Schema.Number.annotate({ "description": "Distinct alternate hashes the classifier can still match for this snapshot's current baseline. Reads as how many different images this snapshot is currently allowed to produce. Resets when the baseline moves, because tolerations recorded against an old baseline hash can never match again." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "hard_count": Schema.Number.annotate({ "description": "Default-branch runs in the last 7 days where this snapshot failed the gate, so somebody could not merge until it was resolved. Counts every result that is not `unchanged`: a diff over a threshold, a baseline that was never committed or was dropped, and a baseline whose story no longer renders." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "soft_count": Schema.Number.annotate({ "description": "Default-branch runs in the last 7 days where this snapshot rendered differently from its baseline and a toleration absorbed it, blocking nobody." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "window_runs": Schema.Number.annotate({ "description": "Completed default-branch runs of this run type in the last 7 days. The rate denominator, so a reader can tell 2 failures out of 3 runs from 2 out of 300." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "hard_rate": Schema.Number.annotate({ "description": "`hard_count` over `window_runs`. The denominator counts every run of this run type, so a snapshot that only started rendering partway through the window reads lower than it is.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "soft_rate": Schema.Number.annotate({ "description": "`soft_count` over `window_runs`.", "format": "double" }).check(Schema.isFinite().annotate({ "expected": "a finite number" })), "last_flaked_at": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Last default-branch run in the last 30 days that rendered this snapshot differently from its baseline, whether the gate failed or a toleration absorbed it. Reads over the full window rather than the rate span, so a snapshot that stopped failing still reports when it last did. Null when nothing happened at all.", "format": "date-time" })), "avg_diff_percentage": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Mean fraction of pixels that differed across the live variants. Separates sub-pixel noise from a small but real rendering change.", "format": "double" })), "worst_soft_diff_percentage": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Largest pixel diff any absorbed run in the last 30 days produced. Reads the full window rather than the rate span, because it asks for the worst case a snapshot can produce and more days are better evidence of that. Null when nothing was absorbed.", "format": "double" })), "headroom": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Fraction of the 2.5% pixel threshold that `worst_soft_diff_percentage` leaves free. A snapshot is absorbed only while it stays under the threshold, so this is what says whether it will keep doing so: 1.0 means it rendered identically every time it was absorbed, 0.0 means it reached the line and only luck kept it on the passing side. Null when nothing was absorbed, which is not the same as full headroom.", "format": "double" })), "baseline_age_days": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Days since the first default-branch run that compared against the current baseline, which is when that baseline took effect. Reads too new for a `broken` snapshot, which records a change against an unmoved baseline on every run." })), "daily_hard_counts": Schema.Array(Schema.Int).annotate({ "description": "Gate-failing runs per day over the last 30 days, oldest first. Always that length, so a fixed time axis can be rendered." }), "daily_soft_counts": Schema.Array(Schema.Int).annotate({ "description": "Absorbed runs per day over the same 30 days, oldest first." }), "baseline_moved_day_index": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "Index into the daily series where the baseline moved. Null when it moved before the window opened, which is the common case." })), "flakiness_state": Schema.suspend((): Schema.Codec<FlakinessStateEnum> => FlakinessStateEnum).annotate({ "description": "An urgency ladder, where each rung asks for a different fix. `broken` fails nearly every run, so its baseline is wrong and quarantining it only hides that. `unstable` fails some runs and not others, the classic flake. `at_risk` never fails, but its worst absorbed diff is already touching the threshold, so the next unrelated change turns it red. `clean` has no gate failure inside the rate span, and any diff it absorbed sits far below the threshold.\n\n* `broken` - broken\n* `unstable` - unstable\n* `at_risk` - at_risk\n* `clean` - clean" }), "needs_decision": Schema.Boolean.annotate({ "description": "True when an active quarantine has run out, is about to, or covers a snapshot that has stopped failing the gate. All three mean a human has to extend it or lift it." }), "quarantine": Schema.optionalKey(Schema.Union([BaselineQuarantineSummary, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Active quarantine details when `is_quarantined` is true. Null otherwise." })), "owner_team": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Slug of the team that owns the file this snapshot's story lives in, from the repository's ownership files. `unowned` when no entry covers the file. Null when ownership is unknown: the snapshot is not a Storybook snapshot, the newest default-branch run sent no story index, the story is not in it, or the ownership files could not be read." })), "identifier": Schema.String, "run_type": Schema.String, "browser": Schema.Union([Schema.String, Schema.Null]), "thumbnail_hash": Schema.Union([Schema.String, Schema.Null]), "width": Schema.Union([Schema.Int, Schema.Null]), "height": Schema.Union([Schema.Int, Schema.Null]), "is_quarantined": Schema.Boolean }).annotate({ "identifier": "FlakinessEntry" })
