export const CompleteTrainingRun = Schema.Struct({ "best_iteration_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Advisory nomination. The server promotes the kept iteration with the highest holdout_score; this id only breaks a tie at that score, and a lower-scoring nomination is logged and ignored.", "format": "uuid" })), "model_explanation": Schema.optionalKey(Schema.suspend((): Schema.Codec<ModelExplanationField> => ModelExplanationField).annotate({ "description": "Global feature importance / directionality bundle for the champion model card." })), "recommended_next": Schema.optionalKey(Schema.String.annotate({ "description": "What a future run should try next, given what this run learned. Stored in the run summary so the next run reads it during orientation. Keep it short and concrete; max 2000 characters.", "default": "" }).check(Schema.isMaxCodePoints(2000).annotate({ "expected": "a string with at most 2000 code points" }))), "distillation": Schema.optionalKey(Schema.String.annotate({ "description": "A 1–2 sentence distillation of what this run learned — the winning signal, the key transform, the dead-ends. Stored in the run summary as the cheapest thing the next run reads. Max 2000 characters.", "default": "" }).check(Schema.isMaxCodePoints(2000).annotate({ "expected": "a string with at most 2000 code points" }))), "reader_summary": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(600).annotate({ "expected": "a string with at most 600 code points" })), Schema.Null]).annotate({ "description": "One or two plain sentences for people on what this run learned. Max 600 characters." })), "headline": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "A short title for people, at most 60 characters, on what this run learned. Use plain words, with no column names, SQL or model jargon. Longer text is cut, not rejected." })), "next_steps": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String.check(Schema.isMaxCodePoints(80).annotate({ "expected": "a string with at most 80 code points" }))).check(Schema.isMaxLength(5).annotate({ "expected": "a value with a length of at most 5" })), Schema.Null]).annotate({ "description": "Short next steps for people, at most 5 items of a few words each (max 80 characters per item)." })), "report_notebook_short_id": Schema.optionalKey(Schema.String.annotate({ "description": "Short id of the report notebook you built for this run. Stored in the run summary only if the notebook exists in this project; an unknown id is dropped and does not fail the completion.", "default": "" })) }).annotate({ "description": "Input for finalizing a training run. The backend selects/promotes the champion.", "identifier": "CompleteTrainingRun" })
