export type DeliverySummary = { readonly "cost_per_merged_pr_usd": ScopeRepoFigure, readonly "billable_minutes_per_merged_pr": ScopeRepoFigure, readonly "cost_per_push_usd": ScopeRepoFigure, readonly "median_ready_to_merge_seconds": ScopeRepoFigure, readonly "p90_ready_to_merge_seconds": ScopeRepoFigure, readonly "median_ready_to_first_approval_seconds": ScopeRepoFigure, readonly "median_first_approval_to_merge_seconds": ScopeRepoFigure, readonly "before_first_approval_share": ScopeRepoFigure, readonly "pushes_after_approval_per_merged_pr": ScopeRepoFigure, readonly "merge_queue_attempts_per_merged_pr": ScopeRepoFigure, readonly "failed_merge_queue_share": ScopeRepoFigure, readonly "lead_time": DeliveryLeadTime, readonly "scope_kind": DeliveryScopeKindEnum, readonly "scope": string, readonly "has_membership_data": boolean, readonly "jobs_available": boolean, readonly "review_data_available": boolean, readonly "ready_data_available": boolean, readonly "opened_pr_count": number, readonly "merged_pr_count": number, readonly "open_pr_count": number, readonly "draft_pr_count": number, readonly "total_cost_usd": number | null, readonly "total_billable_minutes": number | null, readonly "push_count": number }
export const DeliverySummary = Schema.Struct({ "cost_per_merged_pr_usd": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Median estimated CI cost per merged PR, in USD, over every run linked to the PR (merge-queue gate runs included) that started up to 30 days before the window. Null when the jobs table isn't synced." }), "billable_minutes_per_merged_pr": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Median billable runner minutes per merged PR, on the billed clock. Null when the jobs table isn't synced." }), "cost_per_push_usd": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Total CI cost divided by total pushes over the merged PRs: the price of one iteration. A push is a distinct head commit that triggered CI." }), "median_ready_to_merge_seconds": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Median seconds from the last ready_for_review to merge. Null when issue events aren't synced." }), "p90_ready_to_merge_seconds": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "90th percentile of the ready-to-merge seconds." }), "median_ready_to_first_approval_seconds": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Median seconds from ready to the first approval. An approval given while the PR was a draft counts as 0. PRs merged without an approval are left out. Null when reviews aren't synced." }), "median_first_approval_to_merge_seconds": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Median seconds from the first approval to merge. This median and the one before it do not add up to the ready-to-merge median." }), "before_first_approval_share": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Share (0 to 1) of all ready-to-merge hours spent before the first approval, summed over the PRs, so long PRs weigh more. The rest came after the approval." }), "pushes_after_approval_per_merged_pr": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Mean pushes after the first approval per merged PR, over PRs with an approval." }), "merge_queue_attempts_per_merged_pr": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Mean merge-queue gate attempts per merged PR that went through the queue. A bisection probe folds into its attempt." }), "failed_merge_queue_share": Schema.suspend((): Schema.Codec<ScopeRepoFigure> => ScopeRepoFigure).annotate({ "description": "Share (0 to 1) of queue-landed merged PRs with at least one failed gate attempt. A failure caused by another PR ahead in the queue also counts, because the queue history is not in the warehouse." }), "lead_time": Schema.suspend((): Schema.Codec<DeliveryLeadTime> => DeliveryLeadTime).annotate({ "description": "Lead time to deploy for the scope against the repository." }), "scope_kind": Schema.suspend((): Schema.Codec<DeliveryScopeKindEnum> => DeliveryScopeKindEnum).annotate({ "description": "What the read covers: 'author' (one GitHub login), 'github_team' (the members of one GitHub team, through the team membership table), or 'pull_request' (one pull request).\n\n* `author` - Author\n* `github_team` - GitHub Team\n* `pull_request` - Pull Request" }), "scope": Schema.String.annotate({ "description": "The GitHub login or GitHub team slug the summary is for." }), "has_membership_data": Schema.Boolean.annotate({ "description": "True when the team membership table is synced. A github_team scope without it matches no pull requests, so every scope figure is empty rather than the whole repository." }), "jobs_available": Schema.Boolean.annotate({ "description": "True when the workflow jobs table is synced, which cost needs." }), "review_data_available": Schema.Boolean.annotate({ "description": "True when the reviews table is synced, which the approval split needs." }), "ready_data_available": Schema.Boolean.annotate({ "description": "True when issue events are synced, which ready-to-merge time needs." }), "opened_pr_count": Schema.Number.annotate({ "description": "PRs in scope opened in the window, drafts included, bots excluded." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "merged_pr_count": Schema.Number.annotate({ "description": "PRs in scope merged in the window (bots and drafts excluded): the population of every per-merged-PR figure." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "open_pr_count": Schema.Number.annotate({ "description": "PRs in scope that are open and not drafts right now. Ignores the window." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "draft_pr_count": Schema.Number.annotate({ "description": "PRs in scope that are open drafts right now. Ignores the window." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "total_cost_usd": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Estimated CI cost summed over the merged PRs in scope. Null when nothing was costable.", "format": "double" }), "total_billable_minutes": Schema.Union([Schema.Finite, Schema.Null]).annotate({ "description": "Billable minutes summed over the merged PRs in scope. Null when the jobs table isn't synced.", "format": "double" }), "push_count": Schema.Number.annotate({ "description": "Pushes summed over the merged PRs in scope." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "identifier": "DeliverySummary" })
export type JobLogInsights = { readonly "job": ReadonlyArray<JobLogBadge>, readonly "steps": ReadonlyArray<JobStepLogBadges>, readonly "log_read": boolean, readonly "attributed_to_steps": boolean, readonly "log_truncated"?: boolean }
export const JobLogInsights = Schema.Struct({ "job": Schema.Array(JobLogBadge).annotate({ "description": "Every badge found in the log, for the job as a whole." }), "steps": Schema.Array(JobStepLogBadges).annotate({ "description": "The same badges per step. Only steps with a badge are listed. Empty when `attributed_to_steps` is false." }), "log_read": Schema.Boolean.annotate({ "description": "False when no log was read: a Depot CI job, a job the source does not hold, a log GitHub no longer keeps, or a failed fetch. Empty badges then mean 'unknown', not 'nothing found'." }), "attributed_to_steps": Schema.Boolean.annotate({ "description": "False when the log's step markers did not line up with the job's steps, so the badges are reported for the job only." }), "log_truncated": Schema.optionalKey(Schema.Boolean.annotate({ "description": "True when only part of the log was parsed, because the log is too large or its download took too long. The badges are then a lower bound: an outcome in the part that was not parsed is missing." })) }).annotate({ "identifier": "JobLogInsights" })
export type PullRequestTimelines = { readonly "items": ReadonlyArray<PRTimeline>, readonly "red_seconds_per_merged_pr": ReadonlyArray<PRTimelineRedTime>, readonly "scope_kind": DeliveryScopeKindEnum, readonly "scope": string, readonly "has_membership_data": boolean, readonly "review_data_available": boolean, readonly "jobs_available": boolean, readonly "merge_queue_state_available": boolean, readonly "generated_at": string, readonly "merged_pr_count": number, readonly "truncated": boolean, readonly "limit": number }
export const PullRequestTimelines = Schema.Struct({ "items": Schema.Array(PRTimeline).annotate({ "description": "The pull requests in scope, newest first: open PRs plus PRs merged in the window, or the one pull request of a pull_request scope." }), "red_seconds_per_merged_pr": Schema.Array(PRTimelineRedTime).annotate({ "description": "Average red time per merged pull request, grouped by the evidence that classifies each red stretch." }), "scope_kind": Schema.suspend((): Schema.Codec<DeliveryScopeKindEnum> => DeliveryScopeKindEnum).annotate({ "description": "What the read covers: 'author' (one GitHub login), 'github_team' (the members of one GitHub team, through the team membership table), or 'pull_request' (one pull request).\n\n* `author` - Author\n* `github_team` - GitHub Team\n* `pull_request` - Pull Request" }), "scope": Schema.String.annotate({ "description": "The GitHub login, GitHub team slug, or 'owner/name#number' the timelines are for." }), "has_membership_data": Schema.Boolean.annotate({ "description": "True when the team membership table is synced. A github_team scope without it lists no pull requests." }), "review_data_available": Schema.Boolean.annotate({ "description": "False when reviews aren't synced: review stretches read review_state_unknown." }), "jobs_available": Schema.Boolean.annotate({ "description": "False when workflow jobs aren't synced: a check a re-run turned green is not visible, and no red stretch reads red_master_broken." }), "merge_queue_state_available": Schema.Boolean.annotate({ "description": "True when the Trunk merge-queue table is synced, so out_of_merge_queue can appear." }), "generated_at": Schema.String.annotate({ "description": "The now every open PR's timeline ends at.", "format": "date-time" }), "merged_pr_count": Schema.Number.annotate({ "description": "Every pull request merged in the selected scope and window." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "truncated": Schema.Boolean.annotate({ "description": "True when more PRs matched than the limit." }), "limit": Schema.Number.annotate({ "description": "The maximum number of PRs returned." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "identifier": "PullRequestTimelines" })
