export const ExperimentApiMetric = Schema.Struct({ "breakdownAttributionType": Schema.optionalKey(Schema.Union([ExperimentApiBreakdownAttributionType, Schema.Null]).annotate({ "description": "For funnel metrics with breakdowns: which step the breakdown value is read from. 'all_events' is not supported for experiment funnels.", "default": null })), "breakdownAttributionValue": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "title": "Breakdownattributionvalue", "description": "When breakdownAttributionType is 'step', the 0-indexed step to attribute from.", "default": null })), "breakdownFilter": Schema.optionalKey(Schema.Union([ExperimentApiBreakdownFilter, Schema.Null]).annotate({ "description": "Break the metric results down by up to 3 event, person, session or group properties.", "default": null })), "completion_event": Schema.optionalKey(Schema.Union([ExperimentApiEventSource, Schema.Null]).annotate({ "description": "For retention metrics: completion event.", "default": null })), "conversion_window": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "title": "Conversion Window", "description": "Only count metric events within this many units after the user's first exposure. Requires conversion_window_unit: a window without a unit is ignored and the metric counts events until the experiment ends. Omit both to count until the experiment ends.", "default": null })), "conversion_window_unit": Schema.optionalKey(Schema.Union([FunnelConversionWindowTimeUnit, Schema.Null]).annotate({ "description": "Unit for conversion_window: 'second', 'minute', 'hour', 'day', 'week' or 'month'. Required when conversion_window is set.", "default": null })), "denominator": Schema.optionalKey(Schema.Union([ExperimentApiEventSource, Schema.Null]).annotate({ "description": "For ratio metrics: denominator source.", "default": null })), "denominator_outlier_handling": Schema.optionalKey(Schema.Union([ExperimentMetricOutlierHandling, Schema.Null]).annotate({ "description": "For ratio metrics: winsorization applied to the denominator aggregate. Leave unset for a binomial-style denominator, which is never clamped.", "default": null })), "funnel_order_type": Schema.optionalKey(Schema.Union([StepOrderValue, Schema.Null]).annotate({ "description": "For funnel metrics: how the steps must occur. 'ordered' (default) or 'unordered'. Do not use 'strict': experiment funnels give wrong counts with it.", "default": null })), "goal": Schema.optionalKey(Schema.Union([ExperimentMetricGoal, Schema.Null]).annotate({ "description": "Whether higher or lower values indicate success.", "default": null })), "ignore_zeros": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Ignore Zeros", "description": "For mean metrics: exclude zero values when computing the winsorization percentile thresholds.", "default": null })), "kind": Schema.optionalKey(Schema.Literal("ExperimentMetric").annotate({ "title": "Kind", "default": "ExperimentMetric" })), "lower_bound_percentile": Schema.optionalKey(Schema.Union([Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })).check(Schema.isLessThanOrEqualTo(1).annotate({ "expected": "a value less than or equal to 1" })), Schema.Null]).annotate({ "title": "Lower Bound Percentile", "description": "For mean metrics: winsorization lower percentile bound, as a fraction in [0, 1] (e.g. 0.01 for the 1st percentile). Per-user values below this percentile are clamped to it before aggregation.", "default": null })), "metric_type": ExperimentMetricType, "name": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Name", "description": "Human-readable metric name.", "default": null })), "numerator": Schema.optionalKey(Schema.Union([ExperimentApiEventSource, Schema.Null]).annotate({ "description": "For ratio metrics: numerator source.", "default": null })), "numerator_outlier_handling": Schema.optionalKey(Schema.Union([ExperimentMetricOutlierHandling, Schema.Null]).annotate({ "description": "For ratio metrics: winsorization applied to the numerator aggregate, independently of the denominator and each with its own percentile thresholds.", "default": null })), "quantile": Schema.optionalKey(Schema.Union([Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0.01).annotate({ "expected": "a value greater than or equal to 0.01" })).check(Schema.isLessThanOrEqualTo(0.99).annotate({ "expected": "a value less than or equal to 0.99" })), Schema.Null]).annotate({ "title": "Quantile", "description": "For quantile metrics: the quantile level, for example 0.9 for p90. The metric takes this quantile of `source.math_property` over all qualifying events of a variant.", "default": null })), "retention_window_end": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "title": "Retention Window End", "default": null })), "retention_window_start": Schema.optionalKey(Schema.Union([Schema.Int, Schema.Null]).annotate({ "title": "Retention Window Start", "default": null })), "retention_window_unit": Schema.optionalKey(Schema.Union([FunnelConversionWindowTimeUnit, Schema.Null]).annotate({ "default": null })), "series": Schema.optionalKey(Schema.Union([Schema.Array(ExperimentApiEventSource), Schema.Null]).annotate({ "title": "Series", "description": "For funnel metrics: array of EventsNode/ActionsNode steps.", "default": null })), "source": Schema.optionalKey(Schema.Union([ExperimentApiEventSource, Schema.Null]).annotate({ "description": "For mean and quantile metrics: event source. Quantile metrics need `math_property`.", "default": null })), "start_event": Schema.optionalKey(Schema.Union([ExperimentApiRetentionStart, Schema.Null]).annotate({ "description": "For retention metrics: start event. Pass {\"kind\": \"ExperimentExposureNode\"} to start retention from the experiment's exposure event; a conversion window or 'last_seen' start_handling is rejected then, because the start is always the user's first exposure.", "default": null })), "start_handling": Schema.optionalKey(Schema.Union([StartHandling, Schema.Null]).annotate({ "default": null })), "threshold": Schema.optionalKey(Schema.Union([Schema.Finite, Schema.Null]).annotate({ "title": "Threshold", "description": "For mean metrics: when set, reports the percentage of users whose per-user summed/counted value reaches or exceeds this threshold. Only meaningful for sum/count math types.", "default": null })), "upper_bound_percentile": Schema.optionalKey(Schema.Union([Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })).check(Schema.isLessThanOrEqualTo(1).annotate({ "expected": "a value less than or equal to 1" })), Schema.Null]).annotate({ "title": "Upper Bound Percentile", "description": "For mean metrics: winsorization upper percentile bound, as a fraction in [0, 1] (e.g. 0.99 for the 99th percentile). Per-user values above this percentile are clamped to it before aggregation.", "default": null })), "uuid": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Uuid", "description": "Unique identifier. Auto-generated if omitted.", "default": null })), "value_format": Schema.optionalKey(Schema.Union([ExperimentMetricValueFormat, Schema.Null]).annotate({ "description": "For mean metrics without a threshold, ratio metrics and quantile metrics: what the metric's value is, so that results show it in a readable format. Set `type` to 'currency' for an amount in the project's base currency, 'duration' for seconds, 'duration_ms' for milliseconds, 'percentage' for a percent on a 0-100 scale, or 'percentage_scaled' for a fraction on a 0-1 scale. Omit it to show a plain number. It only changes how results show the value, and a change to it does not recalculate results.", "default": null })) }).annotate({ "title": "ExperimentApiMetric", "identifier": "ExperimentApiMetric" })
export type ExperimentHealthCheckResult = { readonly "key": ExperimentHealthCheckKeyEnum, readonly "name": string, readonly "description": string, readonly "status": ExperimentHealthCheckStatusEnum, readonly "reason": string | null, readonly "values": { readonly [x: string]: string | number | boolean | null }, readonly "rule": ExperimentHealthCheckRule | null, readonly "rows": ReadonlyArray<{ readonly [x: string]: string | number | boolean | null }> }
export const ExperimentHealthCheckResult = Schema.Struct({ "key": Schema.suspend((): Schema.Codec<ExperimentHealthCheckKeyEnum> => ExperimentHealthCheckKeyEnum).annotate({ "description": "Stable identifier of the check. A check can report several finding codes, so the key is not a finding code.\n\n* `flag_state` - Flag State\n* `flag_shared` - Flag Shared\n* `flag_history` - Flag History\n* `split_changed_mid_run` - Split Changed Mid Run\n* `bucketing_changed_mid_run` - Bucketing Changed Mid Run\n* `release_conditions_changed_mid_run` - Release Conditions Changed Mid Run\n* `flag_variants_mismatch` - Flag Variants Mismatch\n* `forced_variant_release_condition` - Forced Variant Release Condition\n* `new_flag_no_traffic` - New Flag No Traffic\n* `no_metric` - No Metric\n* `metric_event_not_ingested` - Metric Event Not Ingested\n* `metric_cannot_compile` - Metric Cannot Compile\n* `metric_calculation_failed` - Metric Calculation Failed\n* `metric_all_zero` - Metric All Zero\n* `exposure_criteria_cannot_match` - Exposure Criteria Cannot Match\n* `exposure_filters` - Exposure Filters\n* `early_significance` - Early Significance\n* `metrics_not_matured` - Metrics Not Matured\n* `stale_experiment` - Stale Experiment\n* `zero_exposures` - Zero Exposures\n* `test_account_filter_removes_exposures` - Test Account Filter Removes Exposures\n* `srm` - Srm\n* `unserved_variant_exposures` - Unserved Variant Exposures\n* `bias_risk_multiple_excluded` - Bias Risk Multiple Excluded\n* `multiple_variants_share` - Multiple Variants Share" }), "name": Schema.String.annotate({ "description": "The problem the check looks for, for example 'Metrics not set up'." }), "description": Schema.String.annotate({ "description": "What the check looks for and why it matters. The same for every experiment and every status." }), "status": Schema.suspend((): Schema.Codec<ExperimentHealthCheckStatusEnum> => ExperimentHealthCheckStatusEnum).annotate({ "description": "passed: the check found no problem. finding: the check reported a finding in `findings`. not_applicable: the check does not cover the experiment's current state, for example a check of the changes since launch on a draft. not_checked: the check covers the experiment, but it could not read an input or it failed, so a problem it looks for can be present without a finding.\n\n* `passed` - Passed\n* `finding` - Finding\n* `not_applicable` - Not Applicable\n* `not_checked` - Not Checked" }), "reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why the check did not look, for the statuses not_applicable and not_checked, for example 'Runs after launch'. Null for passed and finding." }), "values": Schema.Record(Schema.String, Schema.Union([Schema.String, Schema.Finite, Schema.Boolean, Schema.Null], { mode: "oneOf" })).annotate({ "description": "What the check read on the experiment, for every status, as numbers, strings, booleans or null. Empty when the check read nothing or shows nothing. The suffix of a key gives the unit: _count is a count, _percentage is on the 0-100 scale, _hours is hours and _at is an ISO 8601 time in UTC. A key without a suffix is a setting or a state. A key means the same thing in every check. `rule.value` names the key that decides." }), "rule": Schema.Union([ExperimentHealthCheckRule, Schema.Null], { mode: "oneOf" }).annotate({ "description": "How the check decides. The same for every experiment and every status. Null for a check without a numeric rule." }), "rows": Schema.Array(Schema.Record(Schema.String, Schema.Union([Schema.String, Schema.Finite, Schema.Boolean, Schema.Null], { mode: "oneOf" }))).annotate({ "description": "What the check read per variant, metric or feature flag change, one object each, with the keys and units of `values`. For example, the significance check gives each variant's difference and the smallest difference its sample can detect. Empty when the check reads no such list." }) }).annotate({ "identifier": "ExperimentHealthCheckResult" })
