export const ReportMonitoringSummary = Schema.Struct({ "state": Schema.suspend((): Schema.Codec<MonitoringSummaryStateEnum> => MonitoringSummaryStateEnum).annotate({ "description": "Where the Monitoring period stands. `not_on_track`: a check's latest interim reading misses its target. `awaiting_reading`: a metric check has no interim reading yet. `readings_hidden`: this viewer may not read the data of a metric check whose readings would decide the state. `on_track`: every metric check's latest reading meets its target. `final_check_only`: no metric check takes interim readings, so the outcome waits for the final checks. `window_ended`: every observation window has ended and final verification is due or running.\n\n* `not_on_track` - Not on track\n* `on_track` - On track\n* `awaiting_reading` - Awaiting first reading\n* `readings_hidden` - Readings hidden\n* `final_check_only` - Final check only\n* `window_ended` - Window ended" }), "started_at": Schema.String.annotate({ "description": "When this Monitoring period started.", "format": "date-time" }), "ends_at": Schema.String.annotate({ "description": "When the last open check's observation window ends.", "format": "date-time" }), "lead_check": Schema.Union([MonitoringLeadCheck, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The metric check that best stands for the report: the first one this viewer can see is off track, otherwise the first metric check that takes interim readings. Null when none does." }) }).annotate({ "identifier": "ReportMonitoringSummary" })
