export type SignalReportCheckReplacement = { readonly "title": string, readonly "rationale"?: string, readonly "config": MetricThresholdReplacementConfig, readonly "soak_minutes"?: number, readonly "run_interval_minutes"?: number, readonly "runs_remaining"?: number }
export const SignalReportCheckReplacement = Schema.Struct({ "title": Schema.String.annotate({ "description": "Label for the new metric check." }).check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" })), "rationale": Schema.optionalKey(Schema.String.annotate({ "description": "Why this check is better." }).check(Schema.isMaxCodePoints(2000).annotate({ "expected": "a string with at most 2000 code points" }))), "config": Schema.suspend((): Schema.Codec<MetricThresholdReplacementConfig> => MetricThresholdReplacementConfig).annotate({ "description": "Metric threshold configuration, including a bounded query, comparison, and required Monitoring definition." }), "soak_minutes": Schema.optionalKey(Schema.Number.annotate({ "description": "Observation window in minutes from Monitoring start. Omission preserves the existing window, including zero. Replacing a check during Monitoring restarts the period for all open checks." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })).check(Schema.isLessThanOrEqualTo(43200).annotate({ "expected": "a value less than or equal to 43200" }))), "run_interval_minutes": Schema.optionalKey(Schema.Number.annotate({ "description": "Minutes between interim Monitoring measurements. Must be at least six hours and shorter than the observation window. Omit to use a quarter of the window, bounded to six hours through one day. Windows of six hours or less have no interim samples." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(360).annotate({ "expected": "a value greater than or equal to 360" })).check(Schema.isLessThanOrEqualTo(129600).annotate({ "expected": "a value less than or equal to 129600" }))), "runs_remaining": Schema.optionalKey(Schema.Number.annotate({ "description": "Monitoring performs one terminal evaluation. Omit or set to 1; higher counts are not supported. Interim measurements do not consume this count." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })).check(Schema.isLessThanOrEqualTo(1).annotate({ "expected": "a value less than or equal to 1" }))) }).annotate({ "identifier": "SignalReportCheckReplacement" })
