export const SignalScoutCreate = Schema.Struct({ "display_name": Schema.optionalKey(Schema.String.annotate({ "description": "Name shown wherever people identify this scout, written however you want it — spaces, capitalization, and acronyms are kept as typed, and two scouts may share one. It does not change the scout's skill name, which stays its identity, so renaming a scout keeps its schedule, run history, notes, memory, and links. At most 200 characters; blank means the scout has no name of its own and is labelled from its skill name instead." }).check(Schema.isMaxCodePoints(200).annotate({ "expected": "a string with at most 200 code points" }))), "name": Schema.optionalKey(Schema.String.annotate({ "description": "Optional skill name for the scout — its permanent identifier, containing only lowercase letters, numbers, and hyphens. Omit it and one is generated from `display_name` (`My APM scout` becomes `my-apm-scout`), with a numeric suffix when that name is taken. Pass it to pick the identifier yourself, or to keep a client written before display names working unchanged. The `signals-scout-` prefix is optional." }).check(Schema.isMaxCodePoints(64).annotate({ "expected": "a string with at most 64 code points" }))), "description": Schema.String.annotate({ "description": "Short description of the signal or behavior this scout investigates." }).check(Schema.isMaxCodePoints(1024).annotate({ "expected": "a string with at most 1024 code points" })), "body": Schema.String.annotate({ "description": "Complete markdown prompt executed on every scout run. Include any project-specific signal names, thresholds, investigation steps, and report criteria here." }), "files": Schema.optionalKey(Schema.Array(LLMSkillFileInput).annotate({ "description": "Optional reference files bundled with the scout prompt." })), "config": Schema.optionalKey(Schema.suspend((): Schema.Codec<SignalScoutConfigOptions> => SignalScoutConfigOptions).annotate({ "description": "Optional schedule, enablement, dry-run posture, and delivery settings. Defaults to an enabled, emitting scout on the daily interval with no external destination." })), "suggestion_id": Schema.optionalKey(Schema.String.annotate({ "description": "Optional id of the suggestion this scout was created from. The suggestion then stops being offered on this project. An id this project's batch does not hold is ignored." }).check(Schema.isMaxCodePoints(64).annotate({ "expected": "a string with at most 64 code points" }))) }).annotate({ "description": "Create a runnable custom scout and its config in one atomic request.", "identifier": "SignalScoutCreate" })
