export type BatchExportRequest = { readonly "name": string, readonly "model"?: BatchExportModelEnum, readonly "destination": BatchExportDestinationRequest, readonly "interval": BatchExportIntervalEnum, readonly "paused"?: boolean, readonly "hogql_query"?: string | null, readonly "hogql_modifiers"?: HogQLQueryModifiers | null, readonly "primary_key"?: ReadonlyArray<string> | null, readonly "version_key"?: ReadonlyArray<string> | null, readonly "incremental_mode"?: IncrementalModeEnum, readonly "filters"?: Schema.Json, readonly "timezone"?: string | null, readonly "offset_day"?: number | null, readonly "offset_hour"?: number | null }
export const BatchExportRequest = Schema.Struct({ "name": Schema.String.annotate({ "description": "Human-readable name for the batch export." }), "model": Schema.optionalKey(Schema.suspend((): Schema.Codec<BatchExportModelEnum> => BatchExportModelEnum).annotate({ "description": "Which data model to export: events, persons, sessions, or hogql. The hogql model exports the results of hogql_query.\n\n* `events` - Events\n* `persons` - Persons\n* `sessions` - Sessions\n* `hogql` - Hogql" })), "destination": Schema.suspend((): Schema.Codec<BatchExportDestinationRequest> => BatchExportDestinationRequest).annotate({ "description": "Destination configuration. Required integration_id is enforced per destination type." }), "interval": Schema.suspend((): Schema.Codec<BatchExportIntervalEnum> => BatchExportIntervalEnum).annotate({ "description": "How often the batch export should run.\n\n* `hour` - hour\n* `day` - day\n* `week` - week\n* `every 5 minutes` - every 5 minutes\n* `every 15 minutes` - every 15 minutes" }), "paused": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the batch export is paused." })), "hogql_query": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "HogQL SELECT query. With model 'hogql', its results are the data exported by every run. The query may reference the {data_interval_start} and {data_interval_end} placeholders, replaced with each run's data interval bounds, for example: WHERE timestamp >= {data_interval_start} AND timestamp < {data_interval_end}. Without them every run exports all rows the query returns. Required when model is 'hogql'." })), "hogql_modifiers": Schema.optionalKey(Schema.Union([HogQLQueryModifiers, Schema.Null], { mode: "oneOf" }).annotate({ "description": "HogQL modifiers to use when the query runs, as an object keyed by modifier name, for example {\"convertToProjectTimezone\": true}. Only supported when 'model' is 'hogql'. Each modifier set here overrides the project modifier with the same name, and the project modifiers apply to all others. If neither sets convertToProjectTimezone, it defaults to false, so timestamps are exported in UTC. Set it to true to export timestamps in the project timezone instead. Unknown modifier names are rejected. On update, the object replaces the modifiers stored on the export, so include every modifier to keep, or send null to remove them all." })), "primary_key": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String), Schema.Null]).annotate({ "description": "The column or columns in the provided HogQL query that make up the primary key for a HogQL-backed batch export. Required if incremental mode is 'MERGE'" })), "version_key": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String), Schema.Null]).annotate({ "description": "The column or columns in the provided HogQL query that make up the version key for a HogQL-backed batch export." })), "incremental_mode": Schema.optionalKey(Schema.suspend((): Schema.Codec<IncrementalModeEnum> => IncrementalModeEnum).annotate({ "description": "How this batch export handles incremental updates.\n\n* `APPEND` - Append\n* `MERGE` - Merge" })), "filters": Schema.optionalKey(Schema.Json.annotate({ "expected": "JSON value", "description": "Optional list of property filters to restrict which events are exported. Each filter is a serialized HogQL property filter object with a 'type' of one of: 'event', 'hogql', 'person' (e.g. {\"key\": \"$browser\", \"operator\": \"exact\", \"type\": \"event\", \"value\": [\"Firefox\"]})." })), "timezone": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "IANA timezone name (e.g. 'America/New_York', 'Europe/London', 'UTC') controlling daily and weekly interval boundaries." })), "offset_day": Schema.optionalKey(Schema.Union([Schema.Int.check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })).check(Schema.isLessThanOrEqualTo(6).annotate({ "expected": "a value less than or equal to 6" })), Schema.Null]).annotate({ "description": "Day-of-week offset for weekly intervals (0=Sunday, 6=Saturday)." })), "offset_hour": Schema.optionalKey(Schema.Union([Schema.Int.check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" })).check(Schema.isLessThanOrEqualTo(23).annotate({ "expected": "a value less than or equal to 23" })), Schema.Null]).annotate({ "description": "Hour-of-day offset (0-23) for daily and weekly intervals." })) }).annotate({ "description": "Request body for create/partial_update on BatchExportViewSet.\n\nMirrors the writeable fields of `BatchExportSerializer` but uses a polymorphic\n`destination` schema so integration_id is marked required on the types that need\nit. Responses continue to use `BatchExportSerializer`.", "identifier": "BatchExportRequest" })
