export const PatchedFeatureFlagPartialUpdateRequestSchema = Schema.Struct({ "ask_rollback_reason": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, the edit lowers the flag's exposure, and the request sends no `rollback_reason`, the flag is not saved and the response is a 409 with the code `rollback_reason_required`. Send the edit again without this field to save it, with or without a `rollback_reason`. Ignored for an edit that needs approval and for a config version 2 flag.", "default": false })), "rollback_reason": Schema.optionalKey(Schema.Union([RollbackReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why this edit lowers the flag's exposure, for example a rollback after errors. Stored on the activity log entry of the edit. Not stored for an edit that needs approval or for a config version 2 flag.\n\n* `errors` - Errors or bugs\n* `metrics` - Metrics got worse\n* `planned` - It was planned\n* `wrong_configuration` - Wrong configuration\n* `other` - Other" })), "rollback_reason_note": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxCodePoints(1000).annotate({ "expected": "a string with at most 1000 code points" })), Schema.Null]).annotate({ "description": "A free-text note for `rollback_reason`. Requires `rollback_reason`." })), "key": Schema.optionalKey(Schema.String.annotate({ "description": "Feature flag key." })), "name": Schema.optionalKey(Schema.String.annotate({ "description": "Feature flag description (stored in the `name` field for backwards compatibility)." })), "filters": Schema.optionalKey(Schema.suspend((): Schema.Codec<FeatureFlagFiltersSchema> => FeatureFlagFiltersSchema).annotate({ "description": "Feature flag targeting configuration." })), "active": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the feature flag is active." })), "archived": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the flag is archived. Archived flags are hidden from the flag list by default and must be disabled (`active: false`)." })), "tags": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Organizational tags for this feature flag." })), "evaluation_contexts": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Evaluation contexts that control where this flag evaluates at runtime." })), "is_remote_configuration": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether this flag is a remote configuration flag that delivers a payload rather than gating a feature." })), "ensure_experience_continuity": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether to persist a user's flag value across the anonymous-to-identified transition (the 'persist across authentication steps' option). Incompatible with device_id bucketing." })), "evaluation_runtime": Schema.optionalKey(Schema.Union([EvaluationRuntimeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Where this flag is allowed to evaluate: 'server' (server-side SDKs only), 'client' (client-side SDKs only), or 'all' (both). Defaults to 'all'.\n\n* `server` - Server\n* `client` - Client\n* `all` - All" })), "bucketing_identifier": Schema.optionalKey(Schema.Union([BucketingIdentifierEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Identifier used to bucket users into rollout percentages and variants: 'distinct_id' (user ID, the default) or 'device_id'. Using 'device_id' is incompatible with ensure_experience_continuity=True.\n\n* `distinct_id` - User ID (default)\n* `device_id` - Device ID" })), "version": Schema.optionalKey(Schema.Number.annotate({ "description": "The `version` from your most recent read of this flag. Required when the flag's `filters.version` is 2: the update is then refused with 409 if anyone else changed the flag after that version. Other flags do not check it." }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(Schema.isGreaterThanOrEqualTo(0).annotate({ "expected": "a value greater than or equal to 0" }))) }).annotate({ "identifier": "PatchedFeatureFlagPartialUpdateRequestSchema" })
export type ExperimentHealthInputs = { readonly "is_launched": boolean, readonly "is_running": boolean, readonly "has_ended": boolean, readonly "is_paused": boolean, readonly "archived": boolean, readonly "baseline_variant_key": string | null, readonly "excluded_variant_keys": ReadonlyArray<string>, readonly "primary_metric_count": number, readonly "secondary_metric_count": number, readonly "flag": ExperimentHealthInputsFlag | null, readonly "flag_last_called_at": string | null, readonly "flag_called": boolean | null, readonly "flag_called_during_run": boolean | null, readonly "flag_called_after_end": boolean | null, readonly "exposure_events": ExperimentHealthInputsExposureEvents | null, readonly "events_received": { readonly [x: string]: boolean }, readonly "metric_compiles": ExperimentHealthInputsMetricCompiles | null, readonly "latest_calculation": ExperimentHealthInputsLatestCalculation | null, readonly "flag_history": ExperimentHealthInputsFlagHistory | null, readonly "condition_set_traffic_status": ExperimentHealthInputsTrafficStatusEnum, readonly "condition_set_traffic": ExperimentHealthInputsConditionSetTraffic | null, readonly "reader_access": ExperimentHealthInputsReaderAccess, readonly "exposures": ExperimentHealthInputsExposures, readonly "project": ExperimentHealthInputsProject }
export const ExperimentHealthInputs = Schema.Struct({ "is_launched": Schema.Boolean.annotate({ "description": "Whether the experiment has a start date." }), "is_running": Schema.Boolean.annotate({ "description": "Whether the experiment is launched and not ended." }), "has_ended": Schema.Boolean.annotate({ "description": "Whether the experiment has an end date." }), "is_paused": Schema.Boolean.annotate({ "description": "Whether the experiment is paused." }), "archived": Schema.Boolean.annotate({ "description": "Whether the experiment is archived." }), "baseline_variant_key": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The baseline set in the experiment's settings. Null when unset." }), "excluded_variant_keys": Schema.Array(Schema.String).annotate({ "description": "The variants the analysis leaves out of the results. The forced-variant check ignores pins to them." }), "primary_metric_count": Schema.Number.annotate({ "description": "Single-use primary metrics plus shared metrics linked as primary." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "secondary_metric_count": Schema.Number.annotate({ "description": "Single-use secondary metrics plus shared metrics linked as secondary." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "flag": Schema.Union([ExperimentHealthInputsFlag, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The experiment's feature flag. Null when it has none." }), "flag_last_called_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The flag's latest recorded call, which a periodic sync of the flag call events sets. Null when the experiment has no flag, or the flag has no recorded call.", "format": "date-time" }), "flag_called": Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether PostHog has recorded any call of the flag. The flag traffic check reads it on a draft. Null when the experiment has no flag, or the organization's flag calls are stored where the checks can't read them." }), "flag_called_during_run": Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether PostHog has recorded a call of the flag between launch and the end, or until now. The zero exposures check reads it to say whether the flag is called. Null before launch, after a latest call that came after the end, or when the organization's flag calls can't be read." }), "flag_called_after_end": Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether PostHog has recorded a call of the flag after the end and within the last 3 days. The flag state check reads it on an ended experiment whose flag is still active with multiple variants. False only once 3 days have passed since the end. Null before the end, before those 3 days are over without a call, or when the organization's flag calls can't be read." }), "exposure_events": Schema.Union([ExperimentHealthInputsExposureEvents, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The events the exposure criteria count. Null when the stored exposure criteria don't parse." }), "events_received": Schema.Record(Schema.String, Schema.Boolean).annotate({ "description": "Whether the project has received each event that the metrics and the exposure criteria name, by event name. A name that ingestion keeps no record of is absent." }), "metric_compiles": Schema.Union([ExperimentHealthInputsMetricCompiles, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The compile of each metric's query without running it, as the reader, which the 'Invalid metric definitions' check reads. A metric that compiles is cached per reader for a day, and a failing metric compiles again on every request. Null when the compile itself failed." }), "latest_calculation": Schema.Union([ExperimentHealthInputsLatestCalculation, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The latest finished calculation of the metrics, which the metric results check reads. Null before launch, on an archived experiment, or when the read failed." }), "flag_history": Schema.Union([ExperimentHealthInputsFlagHistory, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The changes of the flag since launch that can move exposed people. Null when the experiment is not running, is archived, its flag is missing or deleted, or the read failed." }), "condition_set_traffic_status": Schema.suspend((): Schema.Codec<ExperimentHealthInputsTrafficStatusEnum> => ExperimentHealthInputsTrafficStatusEnum).annotate({ "description": "Whether the condition-set traffic was read, or why not. The forced-variant check needs it when the experiment is launched and some but not all release conditions pin a variant that has a share of the split and is not excluded from the analysis. The release-condition check needs it when such an override was removed after launch.\n\n* `read` - Read\n* `not_needed` - Not Needed\n* `no_query_access` - No Query Access\n* `denied_properties` - Denied Properties\n* `no_flag_version` - No Flag Version\n* `unknown` - Unknown" }), "condition_set_traffic": Schema.Union([ExperimentHealthInputsConditionSetTraffic, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The flag's recent calls by condition set. Null unless condition_set_traffic_status is 'read'." }), "reader_access": Schema.suspend((): Schema.Codec<ExperimentHealthInputsReaderAccess> => ExperimentHealthInputsReaderAccess).annotate({ "description": "What the reader may read, which decides what the checks can load." }), "exposures": Schema.suspend((): Schema.Codec<ExperimentHealthInputsExposures> => ExperimentHealthInputsExposures).annotate({ "description": "The exposure query's answer that the exposure checks read, from the cache." }), "project": Schema.suspend((): Schema.Codec<ExperimentHealthInputsProject> => ExperimentHealthInputsProject).annotate({ "description": "Facts about the project that no check reads yet, from the same providers as the setup context." }) }).annotate({ "identifier": "ExperimentHealthInputs" })
