export const PersonalRanking = Schema.Struct({ "status": Schema.suspend((): Schema.Codec<PersonalRankingStatusEnum> => PersonalRankingStatusEnum).annotate({ "description": "ready: the list is in `results`. unavailable: personal ranking is off now, and `results` is empty.\n\n* `ready` - ready\n* `unavailable` - unavailable" }), "personalized": Schema.Boolean.annotate({ "description": "True when the language model ranked the list with your activity summary. False when you have no summary yet or the build fell back to the inbox order." }), "cached": Schema.Boolean.annotate({ "description": "True when the list is a stored one. False when it is the inbox order fallback or the new list that `wait_seconds` waited for." }), "stale": Schema.Boolean.annotate({ "description": "True when the list does not match your current inbox or focus. When `building` is true, a newer list is on the way. Otherwise a report in the list changed since the build, and the next scheduled build updates it. Pass `refresh` for a new list now." }), "building": Schema.Boolean.annotate({ "description": "True when a new list is being built in the background. Call again in a few seconds, or pass `wait_seconds`, to get it." }), "fallback_reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why the list is in inbox order and not ranked by the language model. building: no list is stored yet and one is being built. rate_limited: no list is stored yet and a build limit was reached, either yours or the shared daily one. build_failed: no list is stored yet and the build could not start. no_activity_summary: you have no activity summary yet, so the model did not rank the list. llm_error, timeout, malformed_output, truncated_output, no_candidates or ai_not_approved: the stored build fell back. Null when the model ranked it." }), "generated_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When the list was built.", "format": "date-time" }), "checked_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "When a build or a check last compared the list with your full inbox. The list is current as at this time. Null when no list is stored.", "format": "date-time" }), "latency_ms": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "How long the model call of the build took, in ms. Null when there was no model call." }), "activity_summary_version": Schema.Union([Schema.Int, Schema.Null]).annotate({ "description": "The version of your activity summary that the build read, or null." }), "candidates_considered": Schema.Number.annotate({ "description": "How many reports the build considered." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "ranked_count": Schema.Number.annotate({ "description": "How many reports the stored list ranks. `results` holds at most `limit` of them." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "results": Schema.Array(PersonalRankingEntry).annotate({ "description": "Your reports, best first. A report that left your inbox since the build, for example a resolved one, is left out." }), "folded": Schema.Array(PersonalRankingFold).annotate({ "description": "Reports the list leaves out because another report in it covers the same work." }) }).annotate({ "identifier": "PersonalRanking" })
